-- Generated by QuestData/Tools/import_multilanguage_quests.py.
-- Known IDs only; Classic-source passages are compatibility fallbacks on Forever.
local source = "MultiLanguage Classic c51dc2e5141f070f5b92de190521d79e8dccaeab"
local data = WordHunterWoW_QuestDataByFlavor
local function apply(id, targets, passages)
    for _, flavor in ipairs(targets) do
        local languages = data and data[flavor]
        for locale, fields in pairs(passages) do
            local record = languages and languages[locale] and languages[locale][id]
            if record then
                for field, text in pairs(fields) do
                    if not record[field] or record[field] == "" then
                        record[field] = text
                        record[field .. "Source"] = source
                        record[field .. "SourceFlavor"] = "classic"
                    end
                end
            end
        end
    end
end

apply(1138, { "classic", "forever" }, { deDE = { progress = "... Zitronenkrebs, Peitscherwurzelkrebs und Ironforgekrebs à la Surprise. Das war's eigentlich.\n\nOh, hallo, {name}. Habt Ihr die feinen Krebsbrocken, von denen ich Euch erzählte?", completion = "Prima, diese feinen Krebsbrocken sind genau, was ich brauche. Danke, {name}! Ich habe das hier gefunden, als ich vor einiger Zeit geangelt habe, und ich habe keine Verwendung dafür. Vielleicht könnt Ihr etwas damit anfangen. Man kann damit allerdings ganz sicher keine guten Krebsgerichte machen.\n\nIch habe Euch doch alles über Krebse berichtet, oder?" }, enUS = { progress = "...lemon crab, whipper root crab, and Ironforge surprise crab.  That's about it.\n\nOh, hello there {name}.  Do you have them fine crab chunks I was telling you about?", completion = "Wow, these fine crab chunks are what I need.  Thanks {name}!  I found this while I was fishing a while ago, and I have no use for it.  Maybe you can do something with it.  It sure don't make any good crab dishes.\n\nI told you all about crabs, right?" } })
apply(1139, { "classic", "forever" }, { deDE = { progress = "Hammertoes Auftrag muss aktualisiert werden, {name}. Das schulde ich ihm.\n\nNicht nur deswegen ist es zwingend, dass Ihr nach Uldaman zurückkehrt, sondern auch für die Sicherheit aller Zwerge. Wenn die Tafel den Dunkeleisenzwergen in die Hände fällt, kann niemand sagen, wie mächtig ihre Golemarmee werden könnte.", completion = "<Berater Belgrum schüttelt ungläubig den Kopf, als Ihr ihm den Steinsplitter gebt.>\n\n{name}, das ist erstaunlich. Ich muss das schnellstens zu den Magiern des Königs bringen lassen. Sie werden das Teil studieren und herausfinden, ob die Legenden wahr sind. Doch das soll ein andermal diskutiert werden. Ihr habt unserem Volk mehr geholfen, als ich für möglich hielt - danke." }, enUS = { progress = "Hammertoe's quest must be actualized, {name}. I owe him that much.\n\nYour return to Uldaman is imperative not only to that goal, but also to the safety of all dwarven kind. With the tablet in the hands of the Dark Irons who knows how powerful their army of golems would become.", completion = "<Advisor Belgrum shakes his head in disbelief as you hand him the stone shard.>\n\n{name}, this is amazing. I shall have this brought to the king's mages as soon as possible. They will want to study it to find out if the legends are true. But that is a discussion for another time: you have aided our people more than I would have ever expected--thank you." } })
apply(1140, { "classic", "forever" }, { deDE = { completion = "Vielleicht hat man die Satyrn schon viel zu lange im Wald geduldet. Ich spreche mit Elissa darüber, wenn ich wieder nach Auberdine reise.\n\nWie auch immer, nachdem die Seelenedelsteine zerstört sind, dürfte Athrikus' Macht sichtlich geschwunden sein. Wir müssen die Gelegenheit nutzen, ihn und seinen Kult auszurotten." }, enUS = { completion = "Perhaps the satyrs have been allowed to persist in the forest for too long. I will speak with Elissa about it when next I travel to Auberdine.\n\nNonetheless, with the soulgems destroyed, Athrikus' power will be greatly diminished. We must seize on this opportunity to eliminate him and his cult." } })
apply(1141, { "classic", "forever" }, { deDE = { progress = "Es gibt sehr viele gute Gerichte, für die man Dunkelküstenbarsche braucht. Man kann sie prima essen, aber ich finde, es macht noch mehr Spaß, sie zu fangen.\n\nHabt Ihr schon ein paar Dunkelküstenbarsche gefangen?", completion = "Das sind echt schöne Zackenbarsche, {name}! Danke, dass Ihr mir geholfen habt!\n\nIhr könnt mindestens so gut angeln wie meine Cousine Graun Blump. Sie hat auch einen Bart und sie riecht etwas merkwürdig, aber das hält sie nicht vom Angeln ab. Tja, ich denke, Ihr könnt auch eine Blump-Familienangel benutzen." }, enUS = { progress = "There's plenty of good dishes you use Darkshore groupers for.  They're good to eat, but I think it's more fun catching them.\n\nYou caught any Darkshore groupers yet?", completion = "Them's some real nice groupers, {name}!  Thanks for helping me out!\n\nYou're at least as good of a fisherman as my cousin, Graun Blump.  She also has a beard and she smells kinda funny, but that don't do nothing to stop her fishing.  I reckon you have what it takes to use a Blump Family Fishing Pole." } })
apply(1142, { "classic", "forever" }, { deDE = { progress = "Was führt Euch in mein Haus, {race}?", completion = "Nein!\n\nDas ist nicht fair. Oh grausame, unerträgliche Welt!\n\nJetzt muss ich diese Last des Kummers tragen und darf Heralaths Werk nicht mit ihm sterben lassen.\n\nEs war tapfer von Euch, von so einem gefährlichen Ort anzureisen, {name}. Doch bitte lasst mich jetzt allein.\n\nIch will in Abgeschiedenheit trauern." }, enUS = { progress = "What brings you to my home, {race}?", completion = "No!\n\n'Tis not fair. Oh, cruel and intolerable world!\n\nI must now carry this burden of grief and not let Heralath's work die with him.\n\nYou were brave to journey from such a dangerous place, {name}. But please leave me now.\n\nIn solitude I shall mourn." } })
apply(1143, { "classic", "forever" }, { deDE = { progress = "Athrikus Narassin ist ein alter und mächtiger Hexenmeister. Vielleicht sollten wir auf Delgrens Unterstützung warten, aber offenbar setzt er großes Vertrauen in Euch, wenn er Euch allein schickt.", completion = "Ich hoffe, nach dem Tod von Athrikus werden die dämonischen Kräfte in dieser Gegend zurückgedrängt. Ich zweifle nicht, dass sie sich neu formieren und zurückkehren, aber bis dahin werden wir auf die Bedrohung vorbereitet sein." }, enUS = { progress = "Athrikus Narassin is an ancient and powerful warlock. Perhaps we should wait for Delgren's assistance, but he obviously had much faith in you to send you alone.", completion = "With the death of Athrikus, I hope that the demonic forces in this area will be driven back. I have no doubt that they will regroup and return, but then we shall be even more prepared to meet their threat." } })
apply(1144, { "classic", "forever" }, { deDE = { completion = "Nochmals danke, Freund! Ich sagte doch, es würde sich für Euch lohnen." }, enUS = { completion = "Thanks again, friend! I told you I'd make it worth your while." } })
apply(1147, { "classic", "forever" }, { deDE = { completion = "Ha! Dieses Sekret, das Euch bedeckt, macht Euch nur hübscher, {name}! Leider hat es Euren Geruch nicht eben verbessert. Geht nicht zu nahe zu den Kodos; Ihr löst entweder eine Stampede aus oder macht sie lüstern.\n\nIch glaube, meine Gefährten würden zustimmen, dass Euer Geruch allein beweist, welche Hilfe Ihr uns gegen diese Insektenkreaturen wart. Danke, {name}." }, enUS = { completion = "Ha! That ichor you're covered in actually makes you prettier, {name}! It certainly does make you reek at the same time though. Don't stand too close to the kodo; you'll either start a stampede or cause them to go into heat.\n\nI think my companions would agree that your smell alone is proof you've done your part to help us against those insect creatures. Thank you, {name}." } })
apply(1148, { "classic", "forever" }, { deDE = { progress = "Ah, es ist lange her, seit Ihr mich besucht habt, {name}. Was kann ich heute für Euch tun? Ihr seht aus, als hättet Ihr jüngst das Antlitz des Krieges geschaut. Gut... gut für die Horde und gut für Euch. Je mehr Kämpfe Ihr gesehen habt, desto hilfreicher seid Ihr; und stärker.", completion = "Habt Ihr Moktar neuerdings gesehen? Er ist ständig auf der Suche nach mir. Zu meinem Bedauern muss ich hören, dass er lieber über seine kleine Kriegerschar wacht, als in den Kampf zu ziehen, aber ich bin sicher, es würde ihm gefallen, Mitglieder der Forscherliga zu töten.\n\nEs war klug, mir diese Proben zu bringen, {name}. Zusammen mit den Eiern vom Feld der Riesen sollte ich herausbekommen können, was diese Insekten sind und was sie vorhaben könnten." }, enUS = { progress = "Ah, it been a long time since you've come to see me, {name}. What can I do for you today? You be looking like you've seen the face of battle recently. Good... good for the Horde and good for you. The more battle you've seen, the more helpful you'll be; stronger, too.", completion = "Ahh, you've seen Moktar recently? He always be lookin' out for me. I'm sorry to hear he spends his time watching over his little war band instead of seeing battle, but I'm sure he be takin' great joy in killing members of the Explorers' League.\n\nYou be smart to bring me these specimens, {name}. Along with the eggs we be findin' in the Field of Giants, these should give me a good start in figuring out what these insects are, and what they be wantin'." } })
apply(1149, { "classic", "forever" }, { deDE = { progress = "Glauben. Er ist wichtiger als vielen bewusst ist.\n\nManchmal ist es gar nicht wichtig, was man glaubt. Es ist nur wichtig, dass man überhaupt an etwas glaubt.", completion = "Erst wenn wir unvorhergesehenen Widersachern gegenüberstehen, begreifen wir, wie stark unser Geist ist. Ihr habt den Sprung des Glaubens gewagt, obwohl Ihr keine Garantie hattet, dass Ihr überleben würdet. Euer Verstand ist offen und Euer Geist bereit für das, was kommen wird.\n\nWenn Ihr bereit seid, wartet der nächste Test auf Euch." }, enUS = { progress = "Faith. It is far more important than some realize.\n\nIt does not matter what you believe sometimes. It is just important that you believe in something.", completion = "It is not until faced with unforeseen adversity that we begin to see how strong our spirits are. You took the leap of faith even though you had no guarantees that you would survive. Your mind is open, and your spirit is prepared for what is to come.\n\nIf you are willing, then the next of your tests is ready." } })
apply(1150, { "classic", "forever" }, { deDE = { progress = "Ihr müsst spirituell, körperlich und geistig auf die Herausforderungen vorbereitet sein, die vor Euch liegen.\n\nZu oft stürmen wir los, ehe wir bereit sind. Ich betrachte es als meine Pflicht gegenüber der Jugend, ganz gleich welchen Stammes, sie auf die Gefahren vorzubereiten, denen sie sich gegenübersehen könnten, wenn sie ihr Haus verlassen haben.", completion = "Grenka war selbst nach {race}-Standards mächtig. Ihr solltet stolz auf Eure heutige Leistung sein.\n\nBeim Test des Glaubens hast du die Kraft des Geistes gezeigt, und jetzt auch Belastbarkeit im Kampf gegen die Harpyien der Wildfedern, doch die Zeit ist reif für einen neuen Test." }, enUS = { progress = "You must be prepared spiritually, physically and mentally for the challenges that lie ahead of you.\n\nToo often do we rush forward before we are ready. I consider it my duty to the youth, no matter which tribe they belong to, to prepare them for the dangers they may face after they leave the sanctity of their home.", completion = "Grenka was powerful, even by {race} standards. You should be proud of your accomplishment this day.\n\nDuring your test of faith you displayed strength of spirit, and now you have shown endurance in battle by taking on the Roguefeather harpies, but the time has come for a new test." } })
apply(1151, { "classic", "forever" }, { deDE = { progress = "Von den Zentaurenstämmen in Tausend Nadeln wird Rok'Alim auch der Trommler genannt, weil er auf alle Kreaturen, die tapfer oder dumm genug sind, sich ihm in den Weg zu stellen, mit den Fäusten eintrommelt.", completion = "Euer Test der Kraft ist beendet. Ihr habt Kraft und Tapferkeit gezeigt und seid jetzt bereit für den letzten Test, bevor diese Rituale abgeschlossen sind." }, enUS = { progress = "Rok'Alim is also called the Pounder by the centaur tribes in Thousand Needles because of the thundering his fists make as he pummels the creatures brave, or stupid, enough to stand in his path.", completion = "The Test of Strength is done. You have shown strength and bravery, and you are now prepared for the final test before these rites are completed." } })
apply(1152, { "classic", "forever" }, { deDE = { completion = "Die Tage und Nächte allerorten auf der Welt werden kälter, da die Goblins das Land vergewaltigen, und die Nachtelfen zeigen mit den Fingern auf die jüngeren Völker. Die Verlassenen und die Orcs sind nicht die Einzigen, die man für die Härten in Kalimdor und Lordaeron verantwortlich machen kann. Viele der intelligenten Völker haben zum Schmerz der Welt beigetragen. Dorn weiß das und hat Euch zu mir geschickt, weil Ihr die erforderlichen Attribute besitzt, das auch zu erkennen.\n\nJetzt steht Ihr vor Braug." }, enUS = { completion = "The days and nights grow colder throughout the world as goblins rape the land, and the night elves point fingers at the younger races. The Forsaken and orcs are not the only ones to blame for the hardships found throughout Kalimdor and Lordaeron. Many of the intelligent races have contributed to the world's pain. Dorn knows this, and he has sent you to me because you have shown the attributes necessary to realize it also.\n\nNow you stand before Braug." } })
apply(1153, { "classic", "forever" }, { deDE = { progress = "Ich sah jene Reisenden wieder, die mir keine Erzprobe verkaufen wollten. Ich spuckte sie an, weil sie dem Kriegshäuptling nicht halfen.\n\nMögen sie im Kampf wie Feiglinge sterben und nicht wie Krieger, wie es das Recht aller Völker sein sollte, die sich mit der Horde verbünden.", completion = "Gute Probe, {name}. Wirklich eine gute Probe.\n\nDiese Reisenden können mich nach Eurer erfolgreichen Rückkehr nicht mehr wegen diesem Erz verspotten.\n\nIch werde mich sofort an die Arbeit machen. Wenn das Material stark genug ist, werde ich dem Kriegshäuptling eine daraus gefertigte Waffe schicken, um ihm unsere Erfolge zu zeigen.\n\nIch werde Eure Hilfe nicht vergessen, {class}." }, enUS = { progress = "I saw the travelers again--the ones that would not sell me a sample of the ore. I spit at them for not helping the warchief.\n\nMay they die in battle like cowards and not like warriors as should be the right of all people who ally themselves with the Horde.", completion = "A good sample, {name}. A good sample indeed.\n\nThose travelers can no longer lord over me the ore they found, now that you have been successful.\n\nI shall get to work on it immediately. If it proves strong enough, I will send a weapon crafted from the material back to the warchief to show him our success.\n\nI shall not forget your help, {class}." } })
apply(1154, { "classic", "forever" }, { deDE = { progress = "Bringt mir das Buch, wenn Ihr es gelesen habt. Ich werde Euch erst Fragen stellen, wenn Ihr mir das Buch gegeben habt.", completion = "Das ist das Buch, das ich nannte. Dann besteht die Hoffnung, dass Ihr meine Fragen korrekt beantwortet... wenn Ihr nicht vergessen habt, es zu lesen.\n\nSprecht wieder mit mir, wenn Ihr bereit seid, dann stelle ich Euch eine Frage." }, enUS = { progress = "Bring me the book after you've studied it. I will not ask you your question until after you have given me the book.", completion = "This is the book I named. There is hope you will answer my question correctly then... unless you've forgotten to study its contents.\n\nWhen you are prepared, speak to me again and I shall ask a question of you." } })
apply(1159, { "classic", "forever" }, { deDE = { completion = "Braug schickt Euch? Unmöglich.\n\n<Parqual schaut auf und ab.>\n\nDor'Danil gemeistert, einen Sprung des Glaubens gewagt, einen mächtigen Elementar bekämpft und überwältigt? Pah! Ihr seid vermutlich ein Lügner; ein Abenteurer, der Gerede in einer Taverne mitgehört hat. Und jetzt glaubt Ihr, Ihr könnt meinen Test bestehen. So sei es denn ... {class}." }, enUS = { completion = "Braug sent you? Impossible.\n\n<Parqual looks you up and down.>\n\nBraved Dor'Danil, took a leap of faith, fought and overpowered a powerful elemental? Bah! You're probably a farce; some adventurer that overheard talk in a tavern. And now you think you have what it takes to pass my test. So be it... {class}." } })
apply(1160, { "classic", "forever" }, { deDE = { progress = "Ich hoffe, Ihr habt den Scharlachroten Kreuzzug ordentlich leiden lassen, bevor Ihr das Buch gestohlen habt.\n\nMeine Ansichten über ihre Art sind nicht unumstritten. Die Kreuzzügler mögen einst Anhänger des Lichtes gewesen sein, aber jetzt möchten sie alle Kreaturen vernichten, die sich nicht ihrer Religion angeschlossen haben. Sie glauben, dass alle Untoten, Verlassene und andere, gesäubert werden müssen und die, die durch ihre Länder reisen, entweder irrsinnig oder Opfer der starken Magie der Untoten sein müssen. Idioten. Idioten und Narren, allesamt.", completion = "Das ist das Buch, das ich Euch suchen schickte.\n\n<Parqual streicht langsam und zärtlich mit der Hand über das Buch, während er es betrachtet.>\n\nJetzt wünscht Ihr also eine Frage, um zu beweisen, dass Euer Verstand so mächtig ist wie Euer Körper und Geist. Wenn Ihr das Buch lange genug studiert habt, dann stelle ich Euch die Frage und Ihr könnt diese Tests abschließen!" }, enUS = { progress = "I hope you made the Scarlet Crusade suffer some before stealing the book from them.\n\nMy views of their kind are not unwarranted. The Crusade may have been followers of the Light at one time, but now, they seek to destroy any creatures that have not sided with their religion. They believe all undead, Forsaken or otherwise, must be cleansed, and those traveling in their lands must either be insane, or subject to the undead's powerful magics. Idiots. Idiots and fools; all of them.", completion = "This is the book I sent you to search for.\n\n<Parqual slowly caresses his hand over the top of the book as he stares down at it.>\n\nSo now you wish a question to prove your mind is as powerful as your body and spirit. If you have studied the book long enough, then I shall ask you your question and you can be done with these tests!" } })
apply(1164, { "classic", "forever" }, { deDE = { progress = "Tötet sie alle und bringt mir ihre Köpfe!", completion = "Ihr steht als Racheengel vor mir und ich verneige mich dankbar vor Euch.\n\nNachdem diese Kuh tot ist und ich weiß, dass ihre Brut sich nicht mehr über Azeroth ausbreiten kann, kann ich meine Energie lukrativeren Dingen zuwenden. Ich hoffe, Ihr habt ihren Bauernhof geplündert, als Ihr sie getötet hattet." }, enUS = { progress = "Kill them all and bring me their heads!", completion = "You stand before me as a figure of vengeance, and I bow down before you in thanks.\n\nWith that cow's death, and knowing that their seed will no longer spread over the face of Azeroth, I can put my energy into something more lucrative. I hope you looted their farmstead after you finished them off." } })
apply(1166, { "classic", "forever" }, { deDE = { progress = "Ich durstig nach Grog. Ich auch Schnupftabak vermissen. Wo ist Geldkassette? Ihr geht holen für Oberanführer Mok'Morokk!\n\nGeht Süden in alter Heimat suchen. Ich zu beschäftigt, Oger anzuführen.", completion = "Sehr gut, {race}. Ich vermissen Sachen sehr. Ich Euch jetzt mögen." }, enUS = { progress = "Me thirsty for grog. Me miss snuff too. Where is strongbox? You go get for Overlord Mok'Morokk.\n\nGo find south in old home. Me too busy leading ogres to get.", completion = "You good {race}. Me miss things very much. Me like you now." } })
apply(1167, { "classic", "forever" }, { deDE = { completion = "Ah, wie schön, Euch wiederzusehen, {name}! Hier geschehen die seltsamsten Dinge, ich bin froh, dass Ihr Euch sehen lasst!\n\nEs war sehr seltsam, {name}. Alles schien normal - jedenfalls so normal, wie es hier sein kann -, und dann schoss plötzlich ein greller Lichtblitz aus dem obersten Turmzimmer. Dann kamen die Schreie. Die Schreie zerrissen die Stille, von Zeit zu Zeit schlugen Blitze in den Boden ein. Was geht hier vor?" }, enUS = { completion = "Ah, it's good to see you again, {name}! The strangest things have been happening around here, I'm glad you showed up!\n\nIt was very strange, {name}. Everything seemed normal--well, as normal as things get around here--and then suddenly there was a blinding flash of light from the upper room of the tower. Then came the screams. The cries split the air, and lightning struck the ground from time to time. What's going on?" } })
apply(1168, { "classic", "forever" }, { deDE = { completion = "Ihr tötet viele der Armee der schwarzen Großdrachen. Ihr Kriegerheld, {race}.\n\nMacht Tharg glücklich." }, enUS = { completion = "You kill many of the black dragon army. You brave {race}.\n\nMake Tharg happy." } })
apply(1169, { "classic", "forever" }, { deDE = { progress = "Mit den Herzen und Zungen versengter Nachkommen der Armee der schwarzen Großdrachen kann ich herausfinden, welche elende Bestie ihre Brut in unsere Heimat einführte. Wenn wir mehr über unsere Angreifer wissen, können wir versuchen, sie ein für allemal zu vernichten und das Dorf Stonemaul zurückzuerobern.\n\nNatürlich wird es an sich schon eine epische Aufgabe sein, Mok'Morokk zu überzeugen, dass er seine fette, träge Masse aus diesem Dreckloch hebt...", completion = "Zweifellos war es eine gefährliche Sache, diese Herzen und Zungen zu sammeln. Ich werde in die Tiefen des Arkanen vorstoßen, um den Ursprung der schwarzen Bedrohung zu finden, die über unsere einstige Heimat kam." }, enUS = { progress = "With the hearts and tongues of scorched offspring of the black dragon army, I can decipher what wretched beast introduced her spawn into our home. Perhaps with a greater knowledge of our aggressors, we can seek to destroy them once and for all and reclaim Stonemaul Village from ruin.\n\nOf course, convincing Mok'Morokk to move his lethargic, fat mass out of this muck hole is going to be an epic quest in and of itself...", completion = "'Twas a perilous affair, no doubt, collecting all of these hearts and tongues. I shall delve into the depths of the arcane to trace the origin of the black menace which has descended upon our former home." } })
apply(1170, { "classic", "forever" }, { deDE = { completion = "Warum Ihr mir von Großdrachen erzählen? Ich Großdrachen nicht mögen. Mir hier gefallen. Keine Drachen hier." }, enUS = { completion = "Why you tell me 'bout dragons? Me no like dragons. Me like it here. No dragons here." } })
apply(1171, { "classic", "forever" }, { deDE = { completion = "Dieser träge Feigling!\n\nMok'Morokks zeigte Kraft, als Rexxar unser Anführer war. Doch kurz nach Rexxars Verschwinden erlag Mok'Morokk den Verlockungen der Macht. Er führte nicht, er forderte. Er dient nicht seinem Volk, sondern erwartet, dass wir ihm dienen.\n\nEs muss etwas geschehen." }, enUS = { completion = "That lazy coward!\n\nMok'Morokk displayed strength when Rexxar was our leader. But soon after Rexxar's departure Mok'Morokk fell prey to temptations of power. Rather than lead, he demanded. He does not serve his people but rather expects us to serve him.\n\nSomething must be done." } })
apply(1172, { "classic", "forever" }, { deDE = { completion = "Großartig! Es wird einige Zeit dauern, bis Onyxia wieder Eier legen kann.\n\nIm Namen meines Volkes danke ich Euch, {name}.\n\nIch habe bislang viel von Euch verlangt. Vielleicht könnt Ihr dem Stonemaulklan einen letzten Dienst erweisen.\n\nMok'Morokk ist uns kein guter Anführer. Tharg wäre ein brillanter Anführer, ist aber durch seine Verletzungen und sein Alter behindert. Vertreibt Mok'Morokk mit Gewalt von hier. Erst dann können wir einen neuen Anführer bestimmen und in unsere angestammte Heimat im Süden zurückkehren." }, enUS = { completion = "Splendid! It will be sometime before Onyxia can produce more eggs.\n\nOn behalf of my people, I thank you, {name}.\n\nI have asked much of you so far. Perhaps you can do the Stonemaul Clan one last service.\n\nMok'Morokk is not fit to lead us. Tharg would make an excellent leader but is hindered by his injuries and age. Drive Mok'Morokk from this place by force. Only then can we appoint a new leader to return us to our proper home in the south." } })
apply(1173, { "classic", "forever" }, { deDE = { completion = "Dieser feige Fettwanst Mok'Morokk floh wie ein ängstliches Kind. Ihr habt uns einen großen Dienst erwiesen, {name}.\n\nJetzt kann mein Volk einen neuen Anführer bestimmen, mit dem wir unsere angestammte Heimat ein für allemal zurückerobern." }, enUS = { completion = "That cowardly fat mass Mok'Morokk fled like a scared child. You have done a great service, {name}.\n\nNow my people can appoint a new leader, one who will help us reclaim our old home once and for all." } })
apply(1175, { "classic", "forever" }, { deDE = { progress = "Es ist schon schlimm genug, wenn man die Trümmer der Rennwagen beseitigen muss, auch ohne sie aus verbrannten Tierkadavern herauszuklauben.", completion = "Ich hoffe, Ihr habt keine Basilisken auf der Rennstrecke selbst getötet! Es dauert lange, bis die Kadaver in der Sonne verfallen, und ich möchte lieber nicht mit einer Schaufel da raus und sie entsorgen." }, enUS = { progress = "It's bad enough having to clear out the wreckage of the racers without having to pick them out of burnt animal parts.", completion = "I hope you didn't kill any of the basilisks on the tracks themselves! It takes a long time for the carcasses to decay in the sun, and I'd rather not have to take a shovel out to clean up." } })
apply(1176, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Knochen für mich? Ich wollte gerade die Steueraufhängung leichter machen, möchte das Auto aber nicht zerlegen, solange ich nicht alle erforderlichen Teile habe.", completion = "Großartig! Ich lasse die Crew sofort daran arbeiten. Danke, {name}!" }, enUS = { progress = "Do you have those bones for me? I was just about to start working on lightening the steering rig, but I don't want to open her up without all the parts I need.", completion = "Great! I can get the crew working on this right away. Thanks, {name}!" } })
apply(1177, { "classic", "forever" }, { deDE = { progress = "Gebt mir Essen oder ich Euch fressen.", completion = "Ich mag Fischköpfe!\n\nIch Euch jetzt nicht fressen." }, enUS = { progress = "Gimme food or me eat you.", completion = "Me like fishy head!\n\nMe no eat you now." } })
apply(1178, { "classic", "forever" }, { deDE = { completion = "Pozzik hat Euch geschickt? Wisst Ihr, Pozzik war einer der angesehensten Tüftler in Undermine, bevor er sich zurückzog und an Rennwagen bastelte.\n\nAls er dem Team beitrat, entwickelte er als Erstes die zweimotorigen Rennwagen. Könnte sein, dass das Geschäft leidet, wenn er nicht mehr im Tüftlerverband arbeitet, aber wen interessiert das schon, was? Es geht doch nichts über die Rennen!" }, enUS = { completion = "Pozzik sent you, huh? You know, Pozzik was one of the most respected tinkerers in Undermine before he retired to start working on the racers.\n\nThe first thing he did when he joined the team was develop the two engine model racers. Could be that the businesses will suffer without him working with the Tinkers' Union, but who cares, right? There's nothing like the races!" } })
apply(1179, { "classic", "forever" }, { deDE = { progress = "Passt auf, wo Ihr hintretet! Aufpassen, aufpassen, aufpassen!!! Das hier sind empfindliche Teile, und wenn wir gewinnen wollen, muss alles perfekt funktionieren!", completion = "Ah! Longbeard hat Euch mit den Helmen geschickt! Hurrah!\n\nVielleicht können wir jetzt einen Fahrer überreden, unseren Wagen zu fahren..." }, enUS = { progress = "Watch where you're stepping!  Watch watch watch!!  This is delicate stuff you see here, and if we're to win then it must all work perfectly!", completion = "Ah!  Longbeard sent you with a load of helmets!  Hooray!\n\nNow maybe we can talk a pilot into driving our car..." } })
apply(1180, { "classic", "forever" }, { deDE = { completion = "Lieferungen nach Ratchet? Lasst mich in den Logbüchern nachsehen...\n\nNein, die letzte vermerkte Sendung nach Ratchet waren Stiefel von Drizzlik. Sonst nicht viel, abgesehen von Baustoffen und Werkzeugen. Definitiv keine Rennwagenteile." }, enUS = { completion = "Shipments to Ratchet? Let me just check the logbooks...\n\nNo, the most recent shipment I have on record of going out to Ratchet were boots from Drizzlik. Hasn't been much else, other than building supplies and tools. Definitely no race parts." } })
apply(1181, { "classic", "forever" }, { deDE = { completion = "Oh, gewiss, natürlich weiß ich, wovon Ihr redet. Neee, ich kann Euch aber nicht helfen. Einige meiner Männer sollten die Blaupausen für die Treibstoffeinspritzpumpe aufspüren, kamen aber mit leeren Händen zurück." }, enUS = { completion = "Oh, sure of course I know what you're talking about. Nope, can't help you though. Some of my men were supposed to go track down the blueprints for the fuel regulator, but they came back empty-handed." } })
apply(1182, { "classic", "forever" }, { deDE = { progress = "So ungern ich es zugebe, das Gnomen-Team, das Sie da draußen haben, ist ziemlich gut. Unsere Jungs brauchen jeden Vorteil, den sie bekommen können.", completion = "Lasst mich nur rasch eine Kopie dieser Blaupausen für meine eigenen Notizen machen, dann könnt Ihr sie direkt zu Pozzik bringen. Er soll nicht denken, dass ihn einer seiner Sponsoren im Stich lässt." }, enUS = { progress = "Much as I hate to admit it, that gnome team they have out there is pretty good. Our boys need every edge they can get.", completion = "Now, let me just get a copy of these blueprints for my own notes and you can bring these straight to Pozzik. Wouldn't want him to think that one of his sponsors was abandoning him." } })
apply(1183, { "classic", "forever" }, { deDE = { progress = "{name}! Habt Ihr die Treibstoffeinspritzpumpe aufspüren können?", completion = "Ich hatte gehofft, sie wäre schon zusammengebaut, aber dies bietet die einmalige Gelegenheit, die Pläne von Grund auf zu verbessern. Danke, {name}. Ich werde einige verbesserte Baupläne skizzieren, das Ding bauen und es schon bald installieren können." }, enUS = { progress = "{name}! Did you manage to track down the fuel regulator?", completion = "I was hoping that it would be already assembled, but this does present the unique opportunity to improve on the design from the ground up. Thanks, {name}. I'll be able to sketch up some improved schematics, build the thing, and have it installed real soon." } })
apply(1184, { "classic", "forever" }, { deDE = { completion = "Ich weiß Eure Anstrengungen zu schätzen, {class}. Der Kriegshäuptling wird gern hören, wie gewissenhaft Ihr Eure Pflicht erfüllt habt.\n\nOh, gewiss werde ich ihm Euren Namen nennen. Er spricht oft mit mir und schätzt meine Meinung hoch.\n\nGeht jetzt, ich habe viel Arbeit vor mir. Und wenn Ihr demnächst mit Korran sprecht und er Neuigkeiten über diese Kreaturen hat, dann kommt wieder zu mir - ich meine, sie sind eine Bedrohung, die man ernst nehmen muss." }, enUS = { completion = "I'm appreciative of your efforts, {class}. The warchief will enjoy hearing how tenacious you have been in your duties.\n\nOh, of course I will mention your name to him. He speaks to me often and values my opinions greatly.\n\nGo now, I have much to do. And if you speak to Korran soon, and he has news of these creatures, then return to me--I would think they are a threat that must be taken seriously." } })
apply(1186, { "classic", "forever" }, { deDE = { completion = "Ihr, {race}, habt Pozzik geholfen, richtig? Ich war einst wie Ihr, rannte in der Boxengasse herum und machte jede Arbeit, die die Mechaniker mich tun ließen.\n\nJetzt seht mich an! Der Super-Rennfahrer des Goblin-Teams!" }, enUS = { completion = "You're the {race} that's been helping Pozzik out, right? I was like you once, running around the pit area, helping with whatever work the mechanics would let me do.\n\nNow look at me! The goblin racing team's pilot extraordinaire!" } })
apply(1187, { "classic", "forever" }, { deDE = { progress = "Wie soll ich mich auf der Rennstrecke blicken lassen, wenn ich nicht ein bisschen extra Power habe? Ich sage Euch, das ist ein Witz.", completion = "Seht Euch nur diese Schönheit an! Fünfzehn Pfund robustes Zephyriumpulver! Wenn ich das an meinen Rennwagen festschnalle, bezwinge ich die Rennstrecke so schnell, dass ich die Gnome zweimal schlage!" }, enUS = { progress = "How'm I supposed to show my face around the track without a little extra kick to get me going? It's a travesty, I tell you.", completion = "Just take a look at this beauty! Fifteen pounds of solid seaforium power! Once I get this strapped on to the side of my racer, I'll be around the track so fast I'll beat the gnomes twice!" } })
apply(1188, { "classic", "forever" }, { deDE = { progress = "Wir Ihr sicher wisst, können im Gizmorium all Eure Tüftlerwünsche erfüllt werden! Wie kann ich Euch helfen?", completion = "Nur Razzeric würde einen Blick darauf werfen und sagen, dass ich eine Art Sicherung eingebaut habe. Dieser Nachbrenner besteht fast ausschließlich aus Zephyriumsprengstoff. Ich habe ihn schon so umgebaut, dass mehr von seiner Ladung bei der Benutzung freigesetzt wird, aber Razzeric ist immer erst zufrieden, wenn alles hundertundzehnprozentig ist!" }, enUS = { progress = "As I'm sure you know, the Gizmorium can service all of your tinkering needs! How can I help you?", completion = "Only Razzeric would take a look at this and say that I'd somehow put some sort of safety lock on it. This booster is almost completely seaforium explosives. I already modified it so that more of its payload would be delivered upon use, but Razzeric is never content unless he goes to eleven!" } })
apply(1189, { "classic", "forever" }, { deDE = { progress = "Könnt Ihr glauben, dass Pozzik einen Eimer Sand in dem Rennwagen verstaute? Wie soll ich Höchstgeschwindigkeit erreichen, wenn ich einen Eimer Sand unter dem Sitz habe?", completion = "Ja, das ist schon besser! Könnte ich doch nur die Gesichter der Gnome sehen, wenn ich mit diesem Baby durchstarte.\n\nLeider werde ich voll und ganz damit beschäftigt sein, einen neuen Streckenrekord aufzustellen!" }, enUS = { progress = "Can you believe Pozzik put a bucket of sand on the racer? How am I supposed to hit my maximum speed with a bucket of sand under the seat?", completion = "Now that's more like it! I wish I could see the look on the gnomes' eyes when they see me set this baby off.\n\nToo bad I'll be too busy pulling off a new course record!" } })
apply(1190, { "classic", "forever" }, { deDE = { completion = "Mit einer krakeligen Handschrift hastig hingekritzelte Anmerkungen und eine Notiz-Rolle über die Veredelung eines neuen Rohmaterials." }, enUS = { completion = "Scribbled in a hasty, hurried hand, a scroll of notes and designs for the refinement of some raw material." } })
apply(1195, { "classic", "forever" }, { deDE = { progress = "Wenn wir die gefüllte Phiole haben, können wir sie zu meinem Mitarbeiter Rau in Tausend Nadeln schicken. Er wollte die Phiole Wasser haben, also sollte er wohl auch wissen, wie wir sie nutzen können.", completion = "Sehr gut. Damit sollte Raus Bitte erfüllt sein. Könntet Ihr dies zu ihm bringen? Vielleicht genießt Ihr ja einen Ausflug nach Tausend Nadeln." }, enUS = { progress = "Once we have the filled phial, we can send it along to my associate, Rau, in the Thousand Needles. He was the one who requested the phial of water, so he'll better know how we can make use of it.", completion = "Very good. This should fill Rau's request just fine. Could you deliver this to him? You might enjoy spending some time out in the Needles." } })
apply(1196, { "classic", "forever" }, { deDE = { progress = "Ich nehme nicht an, dass Zangen Euch geschickt hat, hm?", completion = "Hm, ja, diese Phiole Wasser sollte für unsere Zwecke perfekt genügen. Da Dryaden und Zentauren gemeinsame Vorfahren haben, können wir mit dem Wasser der Mondbrunnen den Schutz der ewigen Flamme durchbrechen, die das Relikt der Zentauren umgibt." }, enUS = { progress = "I don't suppose you've been sent by Zangen, hm?", completion = "Hm, yes, this phial of water will serve our purposes perfectly. Because of the shared ancestry of the dryads and the centaurs, the water of the moonwells will enable us to breach the protection of the eternal flame surrounding the centaur relic." } })
apply(1197, { "classic", "forever" }, { deDE = { progress = "Ich brenne darauf, den gespaltenen Huf in die Finger zu bekommen. Habt Ihr ihn schon genommen?", completion = "Ich spüre eine seltsame Energie aus dem Huf kommen... Zweifellos werden wir durch seine Untersuchung überraschende neue Informationen über die Zentauren erhalten.\n\nMeinen Dank, {name}. Jetzt muss ich die Mysterien enträtseln, die Ihr mir gebracht habt." }, enUS = { progress = "I am eager to put my hands upon the Cloven Hoof. Have you taken it yet?", completion = "I sense a strange energy emanating from the Hoof... I have no doubt that we will discover surprising new information about the centaur from its study.\n\nMy thanks, {name}. Now I must begin to decipher the mysteries you have brought to me." } })
apply(1198, { "classic", "forever" }, { deDE = { completion = "Gut, dass Dämmerungsbehüter Shaedlass Euch geschickt hat. An diesem Ort der Verderbnis wird ein finsterer Plan geschmiedet." }, enUS = { completion = "Dawnwatcher Shaedlass was good to send you. There is indeed a wicked plot underway in this corrupted place." } })
apply(1199, { "classic", "forever" }, { deDE = { progress = "Die Blackfathom-Tiefe war einst ein alter Tempel der Nachtelfen. Ehedem befand sich einer der mächtigsten Mondbrunnen darin. Wer weiß, welches Übel die Twilight-Hammer jetzt dort ausbrüten?\n\nHabt Ihr schon Fortschritte bei ihrer Vertreibung erzielt?", completion = "Ihr seid zweifellos von tapferem und edlem Geblüt, {name}. Die Argentumdämmerung dankt Euch für Euren Einsatz gegen das Böse." }, enUS = { progress = "Blackfathom Deeps was once an ancient night elf temple. It once housed a most powerful moonwell. Who knows what evil brews there now at the hands of the Twilight's Hammer.\n\nHave you made any progress in ridding their presence?", completion = "You are no doubt of brave and noble blood, {name}. The Argent Dawn commends you for your efforts against evil." } })
apply(1200, { "classic", "forever" }, { deDE = { progress = "Zeit ist ein kostbares Gut, {class}.\n\nMeine Rolle hier in Darnassus ist es, sicherzustellen, dass die Argentumdämmerung gedeiht und die bösen Mächte aus Kalimdor vertrieben werden.\n\nSagt rasch, was Euer Begehr ist, oder zieht von dannen.", completion = "Kelris entwischt uns schon seit geraumer Zeit.\n\nOffenbar ist Kelris stets dabei, wenn das Böse in dieser Region sein hässliches Haupt erhebt. Eine Zeit lang hielten wir ihn für tot oder vermisst.\n\nDoch dies scheint logisch zu sein. Als Ihr seine Herrschaft beendet habt, habt Ihr vielen Unschuldigen das Leben gerettet.\n\nBeim Licht! Es ist mehr als schändlich, jemanden den Dienern eines Alten Gottes zu opfern, um persönlich Kapital daraus zu schlagen!\n\nIhr habt eine große Tat vollbracht, {name}. Ich salutiere im Namen der Argentumdämmerung vor Euch." }, enUS = { progress = "Time is a precious commodity, {class}.\n\nMy role here in Darnassus is to ensure that the Argent Dawn thrives and that the evil forces encroaching upon Kalimdor are thwarted.\n\nState your business quickly or be on your way.", completion = "Kelris has eluded us for quite some time.\n\nIt seems as though whenever evil made its presence known in these parts, Kelris had played a role. For some time we considered him dead or missing.\n\nBut this makes perfect sense. By ending his reign you have spared the lives of many innocent people.\n\nBy the light! To sacrifice someone to a servant of an Old God for one's personal gain is beyond reproachful!\n\nYou have done a great deed, {name}. I salute you on behalf of the Argent Dawn." } })
apply(1201, { "classic", "forever" }, { deDE = { completion = "Gute Arbeit. Ihre Spitzel sind geschickt, aber nicht gut genug, den wachsamen Blicken der Horde zu entkommen!" }, enUS = { completion = "Good work.  Their infiltrators are skilled, but they're not good enough to escape the watchful eye of the Horde!" } })
apply(1202, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Dokumente gefunden, {name}? Sie enthalten Informationen, die wichtig für die Stabilität der Allianz, und damit auch wichtig für die Sicherheit der Horde sind.", completion = "Ich bewundere Euch, {name}. Dies war keine leichte Mission. Aber die Dokumente, die Ihr gerettet habt, werden von unseren Vorgesetzten hoch geschätzt." }, enUS = { progress = "Did you find the documents, {name}?  They hold information vital to the stability of the Alliance and, hence, vital to the security of the Horde.", completion = "I commend you, {name}.  This was not an easy mission.  But the documents you gained are valued greatly by our superiors." } })
apply(1203, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meine Klinge???", completion = "Das ist eine gute Klinge. Sie schwingt gut. Es ist eine gute Schwingklinge. Danke. Danke, danke, danke!!! Jetzt möchte ich sie ausprobieren... \n\nSpäter. Ich probiere sie später aus. Aber wie ich schon sagte... danke." }, enUS = { progress = "You have my blade??", completion = "That's a good blade.  It has a good swing.  It's a good swing blade.  Thank you.  Thank you, thank you, thank you!!!  Now I want to try it....  \n\nLater.  I'll try it later.  But like I was saying... thanks." } })
apply(1204, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die gespaltenen Zungen gefunden?", completion = "Diese sind ganz exzellent! Danke, {name}!\n\nJetzt werde ich versuchen, durch verschiedene Kochtechniken herauszufinden, wie ihr Geschmack am besten zur Geltung kommt.\n\nVielleicht werde ich ein Gericht kreieren, das des Blauen Eremiten in Stormwind würdig ist!" }, enUS = { progress = "Did you get the forked tongues?", completion = "These will do fine!  Thank you, {name}!\n\nNow I'll try different cooking techniques on these tongues to find the best way to bring out their flavor.\n\nEventually I'll have a dish worthy of serving at the Blue Recluse in Stormwind!" } })
apply(1205, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Zahn von Schlammwühler, {name}? Habt Ihr das Leiden der Kreatur beendet?", completion = "Sehr gut, {name}.\n\nIch bin sicher, die Jagd war nicht leicht, aber es ist gut zu wissen, dass der Schmerz des Tieres ein Ende gefunden hat." }, enUS = { progress = "Do you have the tooth of Deadmire, {name}?  Have you ended the creature's suffering?", completion = "Very good, {name}.\n\nI am sure the hunt was not easy, but it is good to know the beast's pain has finally ended." } })
apply(1206, { "classic", "forever" }, { deDE = { progress = "Wo sind diese Augen?", completion = "Ihr habt die Augen! Ihr habt die Augen! Leckere, leckere Spinnenaugen!\n\nSchöne Augen... wenn man sie anstarrt, starren sie zurück. Die ess ich zuletzt. Sie leisten einem Gesellschaft... draußen im Sumpf.\n\nHallo, kleine Spinnenaugen. Hallo! Ihr seid so lecker wie Hühnchen. Glibberiges, salziges Hühnchen!\n\nMmmh." }, enUS = { progress = "Where are those eyes?", completion = "You got the eyes!  You got the eyes!  Tasty, tasty spider eyes!\n\nSome eyes... when you stare at them they stare back. Eat those last.  They keep you company... out in the swamp.\n\nHello, little spider eyes.  Hello!  You taste like chicken.  Gooey, salty chicken!\n\nMmmh." } })
apply(1218, { "classic", "forever" }, { deDE = { progress = "Gewürz. Wir könnten alle etwas Würze in unserem Leben brauchen. Meint Ihr nicht auch?", completion = "Ah, das ist ein Gewürz! Also, hier haben wir den leckeren sumpfigen Eintopf." }, enUS = { progress = "Spice.  We could all use some spice in our life.  You agree?", completion = "Ah, that's the spice!  Now here's some swampy good stew." } })
apply(1219, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Bericht zu erstatten?", completion = "Hm... Ich kann die Sprache der Orcs nicht sehr gut lesen, aber es scheint ein wichtiger Bericht zu sein... von einem Orc-Spion geschrieben!" }, enUS = { progress = "Do you have a report to make?", completion = "Hm... I can't read orcish very well, but this looks like a report... written by an orc spy!" } })
apply(1220, { "classic", "forever" }, { deDE = { progress = "Habt Ihr etwas für mich?", completion = "Ein Bericht von einem Orc-Spion! Wie habt Ihr den gefunden? Egal - mal sehen, was drin steht..." }, enUS = { progress = "You have something for me?", completion = "A report from an orc spy!  How did you find this?  No matter -- let's see what it says..." } })
apply(1221, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Knollen, {name}?", completion = "Prima, Ihr habt sie! Die kann ich meinen Verbindungsleuten für einen satten Preis verkaufen!\n\nDanke für die Lieferung, {name}! Ihr seid ein toller Partner." }, enUS = { progress = "Do you have the tubers, {name}?", completion = "Great, you got them!  I can sell these to my contacts for a bundle!\n\nThanks for the delivery, {name}!  You are a great partner." } })
apply(1238, { "classic", "forever" }, { deDE = { progress = "Habt Ihr etwas für mich?", completion = "Gute Arbeit, {name} . Unser Agent Marg Nighteye war außerhalb von Theramore stationiert. Seine Aufgabe war es, die Stadt auszuspionieren. \n\nDas ist sein jüngster Bericht und könnte sein letzter sein; nach Eurer Aussage fürchte ich, dass Marg im Sumpf sein Ende fand..." }, enUS = { progress = "You have something for me?", completion = "Good work, {name}.  Our agent, Marg Nighteye, was stationed outside Theramore.  He was charged to spy on the city.  \n\nThis is his latest report, and it may be his last -- from your testimony, I fear that Marg met his end in the swamp..." } })
apply(1239, { "classic", "forever" }, { deDE = { progress = "Habt ihr noch etwas zu berichten, {name}?", completion = "Dies ist der Kopf von Marg Nighteye! Er ist tot, wie ich befürchtete.\n\nSeht euch die Wunde an seinem Hals an! Kann eine Waffe diesen ausgefransten Schnitt gemacht haben, oder wurde unser Agent von einer Bestie angefallen?\n\nDas ist ein Rätsel, das wir lösen müssen, {name}! Wir müssen herausfinden, ob Marg durch die Hände der Allianz starb!" }, enUS = { progress = "You have another matter to report, {name}?", completion = "This is the head of Marg Nighteye!  As I feared, he is dead.\n\nLook at the wound on his neck!  Could a weapon have made that ragged cut, or did some beast slay our agent?\n\nThis is a mystery we must solve, {name}.  We must discover if Marg's death was at the hands of the Alliance!" } })
apply(1240, { "classic", "forever" }, { deDE = { progress = "Ihr habt einen wütenden Geist um Euch, Bruder. Was führt Euch zu Kin'weelay?", completion = "Ah, jetzt verstehe ich. Der Geist dieses Orcs ist an unsere Welt gebunden und kocht vor Wut über eine nicht erledigte Aufgabe.\n\nDann reden wir einmal mit diesem wütenden Orc..." }, enUS = { progress = "There is an angry spirit about you, brother.  What brings you to Kin'weelay?", completion = "Ah, I now see.  The spirit of this orc is bound in our world, boiling with rage from a task yet undone.\n\nWell, let us have words with this angry orc..." } })
apply(1241, { "classic", "forever" }, { deDE = { progress = "Hmpf, hoffentlich habt Ihr einen guten Grund, einen Mann beim Angeln zu stören. Ich reagiere ungehalten auf Schnüffler, von Bettlern ganz zu schweigen.", completion = "Hmm... <Jorgen schaut mit zusammengekniffenen Augen zu Euch auf.>\n\nNun gut. Ich helfe Euch, aber nicht, weil ich es will, sondern weil ich verpflichtet bin.\n\nUnd lasst uns eines klarstellen: Ihr wisst viel mehr als Ihr eigentlich solltet. Betrachten wir dies als unser kleines Geheimnis. Plappert nicht in irgendwelchen Tavernen über das, was Ihr herausfindet. Kapiert?" }, enUS = { progress = "Hmph, you better have good reason to interrupt a man and his fishin'. I don't take kindly to peddlers, let alone beggars.", completion = "Hmm... <Jorgen looks up at you through squinted eyes.>\n\nAll right. I'll help ya, but not because I want to, but because I'm obligated.\n\nAnd let's get one thing straight: you're knowin' far more than you should to begin with. Let's keep this our little secret, and don't go blabbin' at any taverns about anything you find out. Understand?" } })
apply(1242, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Kann ich etwas für Euch tun? Vielleicht würdet Ihr gern unseren speziellen Trias-Cheddar kosten? Oder ein Stück Darnassus-Blauschimmelkäse?", completion = "Pardon, ein Brief für mich? Also da soll mich doch... wenn man arbeitet, bekommt man nicht oft eine Zustellung, die keine Kiste oder ein Fass ist. Mal sehen, worum es geht.\n\n<Elling schaut zu Euch auf, während er den Brief öffnet.>\n\nIhr seht ein wenig nervös aus, alles klar, {name}?" }, enUS = { progress = "Hello, {name}. Is there something I can do for you? Perhaps you'd like to try some of our special Trias cheddar? Or a block of Darnassian bleu?", completion = "I'm sorry, a letter for me? Well, I'll be... not often you get a delivery that's not a crate or barrel when all you do is work. Let's see what this is about.\n\n<Elling looks up at you while he opens the letter.>\n\nYou look a little tense, you okay, {name}?" } })
apply(1243, { "classic", "forever" }, { deDE = { progress = "Es ist nicht eben sicher, durch den Wald zu reisen, {name}. Seid vorsichtig, und wenn Ihr etwas Verdächtiges oder Seltsames seht, meldet es sofort den Behütern. Versucht nicht, auf eigene Faust zu handeln. Wir tragen keine Verantwortung, wenn Euch etwas Schreckliches zustößt.\n\nAber wir wissen beide, dass Ihr nicht auf meine Worte hören und gegen alles kämpfen werdet, was aus der Dunkelheit kommt, nicht? Haha, ja, ihr Abenteurer-Typen ... ihr seid alle gleich.", completion = "Oh, Trias schickt Euch, hm? Das ist etwas anderes.\n\nDann könnt Ihr gegen alle Monster kämpfen, die aus der Dunkelheit kommen mögen. Ich bin sicher, Ihr werdet leicht damit fertig, wenn Ihr der Typ seid, der gern mit seinesgleichen herumhängt.\n\nAlso, was braucht mein Freund an einem so düsteren Tag wie diesem?" }, enUS = { progress = "Not too safe to be traveling about in the woods, {name}. Be careful, and if you see anything suspicious or dangerous, contact the Watchers immediately. Don't try and take anything on yourself. We're not responsible for anything terrible that might happen to you.\n\nBut we both know you're gonna ignore me and fight whatever comes out of the darkness anyway, don't we? Haha, yeah, you adventurer types... all the same.", completion = "Oh, Trias sent you, huh? That's a little different.\n\nFeel free to fight whatever monstrosities come at you from the darkness. I'm sure you'll be able to handle it pretty easily if you're the type to be hanging around with the likes of him.\n\nSo, what does my friend need of me on such a gloomy day as this?" } })
apply(1244, { "classic", "forever" }, { deDE = { progress = "Seid vorsichtig da draußen, {name}. Ich weiß, dass Trias Euch hergeschickt hat, aber das bedeutet nicht, dass es da draußen im Wald nichts gibt, das Euch Ärger machen könnte... besonders wenn Ihr die Defias untersucht.", completion = "Ihr seid heil und gesund zurück. Mehr konntet Ihr nicht verlangen, meint Ihr nicht auch?\n\nDann sehen wir mal, was wir hier haben. Das sieht ziemlich offiziell aus, wenn mich meine Erfahrung mit Defiasdokumenten nicht trügt. Es könnte jedoch auch eine Finte sein, um Euch von der Fährte abzubringen, auf die Ihr bei Eurer Suche gestoßen seid." }, enUS = { progress = "Be careful out there, {name}. I know Trias was the one to send you here, but that doesn't mean there isn't anything lurking out in the woods that couldn't cause you some trouble... especially with you investigating the Defias.", completion = "You're back safe and sound. Couldn't ask for much more than that, could you?\n\nNow, let's see what we have here. This looks pretty official as far as any Defias documents I've seen. But it could be a dupe just to throw you off track of whatever it is you're looking for." } })
apply(1245, { "classic", "forever" }, { deDE = { progress = "Ich sehe, Ihr seid in einem Stück zurück. Wir wissen beide, dass Ihr nicht wegen Käse hier seid, beenden wir also das Plaudern. Konnte Backus Euch helfen oder seid Ihr noch gar nicht im Dämmerwald gewesen?", completion = "Ja... das ist interessant zu lesen. Jorgen und DeLavey waren klug, mich einzuweihen.\n\nOffenbar haben sich die Defias sehr bemüht, ihren Plan hier abzuschließen. Hmm... was ist das? \"Fist\"? Das ist ein vertrauter Name." }, enUS = { progress = "I see you're back, and in one piece. We both know you're not here for cheese, so let's cut out the pleasantries. Was Backus any help, or have you even left for Duskwood yet?", completion = "Yeah... this is an interesting read. Jorgen and DeLavey were smart to bring me in on this.\n\nSeems the Defias have been trying pretty hard to complete this plan of theirs. Hmm... what's this? \"Fist\"? That's a familiar name." } })
apply(1246, { "classic", "forever" }, { deDE = { completion = "Was?!\n\nIhr kommt in meine Gasse und stellt Fragen nach meinen persönlichen Angelegenheiten? Angelegenheiten, mit denen Ihr offenkundig nichts zu tun habt." }, enUS = { completion = "What?!\n\nYou come into me alley and ask questions about me personal business? Business which you obviously have nothing to do with." } })
apply(1247, { "classic", "forever" }, { deDE = { completion = "Wie schön, dass Ihr noch am Leben seid, {name} . Mit Dashel lief demnach alles gut, hm?\n\nIch habe mehr über ihren Plan nachgelesen. Der Name des Diplomaten, auf den sie es abgesehen hatten, wurde zwar nicht genannt, aber es ist von einem Plan B die Rede, der zur Ausführung kam, nachdem der erste Versuch, ihn zu entführen, gescheitert war.\n\nDieser Slim, von dem Dashel sprach, hat hier keinen anderen Namen angegeben, aber wenn Ihr sagt, dass er in Menethil ist, ist das ein Anfang." }, enUS = { completion = "Good to see you're still alive, {name}. So, it went well with Dashel then, huh?\n\nI've been reading up more on this plan of theirs, and although it doesn't state the name of the diplomat they were after, it does talk about this plan B they enacted after failing on their first attempt to capture him.\n\nThis Slim that Dashel mentioned doesn't have any other name written here, but if you say he's in Menethil, then that's a start." } })
apply(1248, { "classic", "forever" }, { deDE = { completion = "Willkommen, willkommen, willkommen, {name}. Schön, dass Ihr Euch uns anschließt. Vielleicht heute ein kühles Bier. Oder etwas Hammel?\n\nNennt mir Euren Wunsch und ich sorge dafür, dass er erfüllt wird. Mein Name ist Mikhail und ich freue mich darauf, Euch zu bedienen.\n\nHmm? Wie war das? Trias? So sprecht doch leiser. Es soll doch nicht die ganze Taverne davon hören." }, enUS = { completion = "Welcome, welcome, welcome, {name}. Good of you to join us. Perhaps an ale today? Or some mutton?\n\nName your pleasure and I'll see to it that you're taken care of. My name is Mikhail, and I look forward to serving you.\n\nHmm? What's that? Trias? Keep your voice down, my friend. This isn't something for the whole tavern to hear about." } })
apply(1249, { "classic", "forever" }, { deDE = { progress = "Ist er entronnen? Sah ein wenig zwielichtig aus, wie er uns beobachtet hat.", completion = "Habt ihn erwischt, hm? Gut für Euch. Ich bin überrascht, dass das Slim war.\n\nIch will ehrlich sein, ich hätte nie gedacht, dass ich die Aufregung der unaufrichtigen Untergrundaktivitäten vermissen würde. Alte Gewohnheiten wird man wohl nicht so leicht los. Aber sagt Elling nichts davon - wenn er hört, dass mir die Aufregung fehlt, versucht er wahrscheinlich, mich wieder nach Stormwind zu locken.\n\nIch bin froh, dass ich Euch in Menethil wenigstens ein wenig zu Diensten sein konnte. Wenn Ihr noch etwas braucht, fragt nur." }, enUS = { progress = "Did he slip away? He looked a little shady the way he was watching us.", completion = "Caught him, huh? Good for you. I'm surprised that was Slim.\n\nI'll be honest, I never thought I'd miss the excitement of some of the more devious underground activities. I guess old habits die hard. Don't mention that to Elling--he'd probably try and get me to come back to Stormwind if he heard I missed the action.\n\nI'm glad I could at least be of a little service to you while you were in Menethil. If you need anything else, just ask." } })
apply(1250, { "classic", "forever" }, { deDE = { completion = "DER KÖNIG?! Ich meine... der König? Der echte König? Ist das ein Witz? Ihr habt nicht erwähnt, dass Ihr die Entführer des Königs sucht. Ich habe nicht einmal gehört, dass er vermisst wird - das würde erklären, warum bald sein Sohn gekrönt wird.\n\nIch werde Elling sofort informieren. Er sollte wissen, dass Ihr die Spur verfolgt.\n\nIch hätte nie gedacht, dass Jahn Stormwind nur des Geldes wegen verkaufen würde. In manchen Dingen muss doch selbst ein Schurke Ehrgefühl besitzen.\n\nJetzt ist es entscheidend, diesen Hendel zu finden. Und ich denke, da kann ich Euch helfen." }, enUS = { completion = "THE KING?! I mean... the king? The real king? Are you joking? You didn't mention you were looking for the king's kidnappers. I didn't even hear he was missing--that would explain his son being crowned some.\n\nI'll send word to Elling right away. He'll want to know you're on the trail.\n\nI would never have guessed Jahn would sell out Stormwind for some lousy coin. Even a rogue's got to have honor when it comes to some things.\n\nThe key now is to find this Hendel. And I think I can help with that." } })
apply(1251, { "classic", "forever" }, { deDE = { progress = "Was habt Ihr denn da, {name}? Beweismittel aus den Trümmern des Gasthauses Zur süßen Ruh?", completion = "Ich gebe ja zu, dass Menschen einen merkwürdigen Geschmack bei der Dekoration haben, aber würden sie einen einfachen Eisenschild benutzen, um ihren Feuerplatz zu schmücken? Vielleicht haben jene, die das Gasthaus niederbrannten, den Schild dort befestigt.\n\nEine Warnung? Eine Drohung?" }, enUS = { progress = "What's that you have there, {name}? Evidence from the remains of the Shady Rest Inn?", completion = "I grant that humans have strange decorating tastes, but would they use a plain iron shield to adorn their fireplace? Perhaps this shield was placed there by the ones who burned the inn.\n\nA warning? A threat?" } })
apply(1252, { "classic", "forever" }, { deDE = { progress = "Habt Ihr etwas Interessantes im Gasthaus Zur süßen Ruh gefunden?", completion = "Es bedeutet selten etwas Gutes, wenn mir das Abzeichen einer Wache gebracht wird.\n\nManchmal bedeutet es, dass ein Mann oder eine Frau im Kampf gefallen ist und ich der trauernden Familie die Nachricht überbringen muss. Manchmal erfahren wir nie, was ihnen zugestoßen ist. Und manchmal ist es sogar noch schlimmer." }, enUS = { progress = "Have you found anything of interest at the Shady Rest Inn?", completion = "It's never good news when a guard's badge is brought to me.\n\nSometimes it's a man or woman who's fallen in battle, and I'm left to bring the news to the grieving family. Other times we never find out what happened to them. And other times it's even worse than that." } })
apply(1253, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Beweise im ehemaligen Gasthaus Zur süßen Ruh gefunden?", completion = "Hm, ich bin kein Experte für die Herstellung von Waffen und Rüstungen. Für ihre Anwendung, ja, aber nicht für die Herstellung.\n\nDer Schild scheint ganz gewöhnlich wie jeder andere zu sein, abgesehen vom Schaden durch das Feuer, das das Gasthaus verwüstete." }, enUS = { progress = "Have you found evidence from the site of the Shady Rest Inn?", completion = "Hm, I'm no expert with the construction of arms and armor. Their use, yes, but not their making.\n\nThis shield seems as ordinary as any, excepting the damage from the fire that engulfed the inn." } })
apply(1258, { "classic", "forever" }, { deDE = { progress = "Meine Experimente mit den Schlammpanzerzungen machen gute Fortschritte. Ich hoffe, Eure Krebssuche kommt voran?", completion = "Das sind wunderbare Exemplare, {name}! Die Schalen sind in perfektem Zustand, das Fleisch ist rosa und zart. Ich bin sicher, das Blut eines Küchenchefs fließt in Euren Adern!" }, enUS = { progress = "My research with the Mudrock tongues is progressing nicely.  I trust your crab hunt goes well?", completion = "These are wonderful specimens, {name}!  The shells are in perfect condition, and the meat is pink and tender.  The blood of a chef is in your veins, I'm sure of it!" } })
apply(1259, { "classic", "forever" }, { deDE = { completion = "Hallo, {name}. Ihr möchtet Informationen über ein bestimmtes Mitglied der Wache von Theramore? Reethe, richtig?\n\nBitte habt einen Moment Geduld, bis ich das richtige Buch gefunden habe." }, enUS = { completion = "Hello, {name}. You'd like information about a specific member of the Theramore guard? Reethe, was it?\n\nJust give me a moment to find the right book." } })
apply(1260, { "classic", "forever" }, { deDE = { completion = "Oh, mein Onkel hat Euch geschickt, nicht?\n\nIch habe mich um die Rezepte gekümmert und ein paar Hinweise, aber ich brauche Hilfe.\n\nHilfe von jemandem, der keine Angst vor nassen Füßen hat." }, enUS = { completion = "Oh, my uncle sent you, did he?\n\nWell I've been researching recipes and I have some leads, but I need help.\n\nHelp from someone willing to get his feet wet." } })
apply(1261, { "classic", "forever" }, { deDE = { progress = "{name}, habt Ihr etwas über Margs Schicksal erfahren?", completion = "Dieser Anhänger wurde von einem Soldat aus Stormwind getragen???\n\nDanke, {name}. Ihr habt die Umstände von Margs Tod enträtselt! Doch dieser Anhänger ist ein neues Rätsel, das es zu lösen gilt, und es könnte schlimme Auswirkungen auf die Allianz und die Horde haben." }, enUS = { progress = "{name}, did you discover Marg's fate?", completion = "This pendant was worn by a soldier of Stormwind??\n\nThank you, {name}.  You have revealed the secret of Marg's death.  But this pendant is a new mystery to solve, one that may have dire effects on the Alliance, and the Horde." } })
apply(1262, { "classic", "forever" }, { deDE = { progress = "Ihr seid von Brackenwall in Dustwallow hierher gereist? Wie geht es Nazeer und wie weit sind seine Bemühungen im Sumpf gediehen?", completion = "Dieser Anhänger wurde mit großem Geschick und Präzision gefertigt, {name}. Kein Orc würde so ein Schmuckstück begehren...\n\nAber viele Menschen könnten es.\n\nIch werde diesen Anhänger untersuchen lassen. Hoffen wir, dass er uns bald seine Geheimnisse preisgibt..." }, enUS = { progress = "You traveled from Brackenwall Village in Dustwallow?  How fares Nazeer, and how fare his efforts in the marsh?", completion = "This pendant was crafted with great skill and precision, {name}.  No orc would covet such a jewel...\n\nBut many humans would.\n\nI will have this pendant studied.  In time let us hope that its mysteries will be revealed to us." } })
apply(1264, { "classic", "forever" }, { deDE = { completion = "Welche Freude, Euch zu sehen, {name}. Ich bin Kommandant Samaul. Ich kommandiere Miss Proudmoores Truppen hier in Theramore.\n\nZur Zeit bin ich zwar ziemlich beschäftigt, aber falls Ihr irgendwelche Fragen habt, sprecht mich ruhig an. Möglicherweise muss ich es kurz machen, aber ich will Euch gern helfen, wenn Ihr Hilfe braucht.\n\nFalls Ihr vorhabt, die Stadt zu verlassen, rate ich Euch, vorsichtig zu sein. Abgesehen von Ogern, Orcs und Murlocs wimmelt es im südlichen Teil des Sumpfs von schwarzen Großdrachen." }, enUS = { completion = "A pleasure to meet you, {name}. I am Commander Samaul. I'm in charge of Miss Proudmoore's forces here in Theramore.\n\nAlthough I'm quite busy, if you have any questions, please feel free to speak up. I might have to keep it short, but there's no reason for me to be rude if you need my help.\n\nIf you plan on traveling out of the city, I'd suggest you be careful. Besides ogres, orcs and murlocs, the southern part of the swamp is filled with black dragons." } })
apply(1265, { "classic", "forever" }, { deDE = { completion = "Der Mann namens Hendel, den Ihr sucht, ist nicht hier. Andere Quellen lieferten Lady Proudmoore Informationen, die Ihr wohl bereits kennt. Sie bat mich, Euch zu suchen und bei Eurer Mission zu unterstützen. Wenn Ihr gestattet, sage ich Euch, wo Ihr den Gefreiten Hendel finden könnt, damit er seine gerechte Strafe erhält." }, enUS = { completion = "The man you seek, the one known as Hendel, is not here. Other sources have brought to the Lady Proudmoore information I believe you already know. She has asked me to find you, and give you aid in your venture. If you would allow it, I will tell you where to find Private Hendel so we can bring him to justice." } })
apply(1266, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt. Dies ist ein gefährlicher Ort für einen Spaziergang. Ich würde nicht zu lange bleiben, wenn Euch Euer Leben lieb ist.\n\nWenn Ihr Euch auf kurze Fragen beschränkt, will ich sehen, ob ich Euch helfen kann. Haltet nur nach diesen schmutzigen Ogern Ausschau. Gerüchten zufolge gibt es einen Stützpunkt der Horde in den Sümpfen. Die Spitzel tun, was sie können, um ihn zu finden, aber das ist eine langwierige Angelegenheit und wir kommen nicht voran." }, enUS = { completion = "Hello, citizen. This is a dangerous place to be wandering about. I wouldn't hang around too long if you value your life.\n\nIf you keep your questions short, I'll see if I can help you. Just keep your eyes open for any of those filthy ogres. Rumor has it there's a Horde base somewhere in the swamps. The infiltrators are doing what they can to find it, but the process has been slow going and we've had little progress." } })
apply(1267, { "classic", "forever" }, { deDE = { completion = "Ich möchte der Erste sein, der Euch für all das dankt, was Ihr geleistet habt, {name}. Erneut wart Ihr ein unglaublicher Segen für mein Volk und die Bewohner von Stormwind. Es tut mir Leid, dass wir uns nicht unter glücklicheren Umständen kennen gelernt haben.\n\nVersteht bitte auch, dass ich Euch nicht offen für Eure Bemühungen danken kann, aber ich möchte Euch nochmals versichern, dass ich sie wohl zu schätzen weiß.\n\nWenn Ihr in Zukunft einmal nach Theramore kommt, schaut unbedingt bei mir herein, dann werde ich versuchen, Euch über die Lage auf dem Laufenden zu halten.\n\nNochmals danke, {name}." }, enUS = { completion = "Let me be first to thank you for all you've done, {name}. You have been an incredible blessing to my people and the people of Stormwind. I am sorry I couldn't make your acquaintance under better circumstances.\n\nUnderstand also that I cannot overtly thank you for your efforts, but I assure you again, it is appreciated.\n\nWhen you visit Theramore in the future, seek me out and I shall try to keep you apprised of the situation.\n\nThank you again, {name}." } })
apply(1268, { "classic", "forever" }, { deDE = { completion = "Hufabdrücke... Ich schätze, das könnten die Stacheleber gewesen sein. Oder vielleicht sogar die Zentauren. Sie sind im Brachland durchaus nicht so selten. So eine Tat zu begehen ist für mich kein kleines Delikt.\n\nSagte ich es Euch schon? Nicht nur das Gasthaus war niedergebrannt... Frau und Kind des Besitzers wurden getötet. Das ist eine schlimme Sache.\n\nDennoch werde ich Kagoro schicken, damit er herausfindet, wohin die Spuren führen." }, enUS = { completion = "Hoofprints... It could have been the quilboar, I suppose. Or maybe even the centaur. Their presence in the Barrens is not insignificant, and I would not think it a stretch to commit such an act.\n\nDid I tell you? It wasn't just that the inn was burned down... The owner's woman and pup were killed. Bad business, that.\n\nNonetheless, I will send Kagoro to find where the tracks lead." } })
apply(1269, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Hinweise gefunden, was im Gasthaus Zur süßen Ruh passiert ist?", completion = "Ich kenne diesen Menschen Paval Reethe. Jämmerlich, selbst für seine Art. Er ließ seine Kameraden im Stich und versteckt sich jetzt im Wald.\n\nIch schicke Gog'ron los, um ihn aufzuspüren. Einige andere vermuten, dass er unsere Vorräte stiehlt. Ich glaube, ich sah Ogron nach Südosten gehen." }, enUS = { progress = "Have you found any leads on what happened at the Shady Rest Inn?", completion = "I know this human, Paval Reethe. Pathetic, even for his kind. He deserted his fellow soldiers and is now hiding out in the woods.\n\nI sent Ogron out to track him down. Some of the others suspect he's been stealing from our supplies. I think I saw Ogron heading off to the southeast." } })
apply(1273, { "classic", "forever" }, { deDE = { completion = "Hmpf. Es ist gut, dass Reethe nicht mehr im Sumpf herumlungert. Ein Jammer, dass Menschen so empfindlich sind, dass er sich nicht von einer kleinen Pfeilwunde erholen konnte.\n\nScheinbar hat dieser Teil des Rätsels nirgendwohin geführt und wir müssen es anderswo versuchen." }, enUS = { completion = "Hmph. It is good that Reethe will no longer be lurking around the swamp, but it is a shame that humans are built so frail that he could not recover from a little arrow wound.\n\nIt seems that this thread of the mystery has led nowhere, and we must look elsewhere." } })
apply(1275, { "classic", "forever" }, { deDE = { progress = "Wenn ich genügend Proben habe, kann meine wahre Arbeit beginnen. Mit den verderbten Hirnstämmen der Satyrn und Naga der Blackfathom-Tiefe kann ich versuchen, einen Zusammenhang zwischen den Mutationen zu finden.\n\nMit diesem Wissen verhindern wir vielleicht, dass die Blutelfen noch deformierter und böser werden.", completion = "Ihr seid weit gereist und habt zweifellos großen Gefahren getrotzt.\n\nEure Taten waren selbstlos. Es dient ganz Azeroth, wenn Ihr mir bei meinen Forschungen helft. Ich danke Euch für alles, was Ihr getan habt, {name}.\n\nWenn Ihr mich nun entschuldigen wollt, ich habe viel Arbeit ..." }, enUS = { progress = "Once I have enough samples to study, my true work can begin. With the corrupted brain stems of both the satyr and naga of Blackfathom Deeps I can try to draw a correlation between the mutations.\n\nPerhaps with that gained knowledge we can prevent the blood elves from delving deeper into deformity and evil.", completion = "You have traveled far and undoubtedly faced great peril.\n\nYour actions have been selfless. 'Tis for the good of all Azeroth that you help me with my research. I thank you, {name}, for all that you have done.\n\nNow if you'll excuse me I have much work to do...." } })
apply(1276, { "classic", "forever" }, { deDE = { progress = "Guten Tag, {class}. Kann ich Euch mit etwas behilflich sein?", completion = "Ja, Ihr habt gewiss Recht. Das ist ein Schild, den ich gemacht habe.\n\nIch fürchte aber, ich kann Euch nicht viel mehr sagen, {name}. Ich stelle so viele Schilde und Rüstungen her, ich kann unmöglich über alle Bescheid wissen." }, enUS = { progress = "Hello there, {class}. Something I can help you with?", completion = "Yes, you are certainly correct. This is a shield that I made.\n\nI'm afraid there's not much more I can tell you though, {name}. I craft so many different shields and sets of armor, I can't keep track of them all." } })
apply(1282, { "classic", "forever" }, { deDE = { completion = "James Hyal ist sein richtiger Name. Er eröffnete ein Gasthaus an der Grenze des Brachlandes. Wollte eine hübsche Unterkunft für Reisende daraus machen...\n\nVielleicht war er größenwahnsinnig, aber eine Weile lief das Gasthaus recht gut. Dann verloren wir die Herrschaft über die Straßen im Sumpf und die Oger übernahmen sie.\n\nJames war zu störrisch, seinen Traum aufzugeben und in unsere sicheren Mauern zu kommen, und das Gasthaus Zur süßen Ruh wurde bis auf die Grundmauern niedergebrannt. Wir ermitteln, hatten aber noch kein Glück. Wenn Ihr mir helfen wollt, seht zu, was Ihr in dem Geröll findet." }, enUS = { completion = "James Hyal's his real name. He opened an inn at the edge of the Barrens. Wanted to make a nice place for travelers to stop over...\n\nMight be he was thinking too big, but the inn did do well for a while. Then we lost control of the roads in the marsh, and the ogres took over.\n\nJames was too stubborn to give up his dream for safety within our walls, and the Shady Rest Inn was burnt to the ground. We're investigating, but haven't had much luck. If you want to help out, see what you can find in the rubble." } })
apply(1284, { "classic", "forever" }, { deDE = { completion = "Hufabdrücke, hm? Stimmt es, dass es in den Ländern nahe den Marschen von Dustwallow eine außergewöhnlich hohe Zentaurenaktivität gibt? Bei den kurzen Ausflügen ins Brachland fanden wir ihre Lager und Anlagen im gesamten Areal.\n\nIch schicke Falgran Hastil, einen unserer Fährtenleser, damit er feststellt, wohin die Abdrücke führen." }, enUS = { completion = "Hoofprints, eh? It is true that there is an extraordinary amount of centaur activity in the lands near the Dustwallow Marsh. In brief excursions into the Barrens, we found their camps and holdings dotting the area.\n\nI'll send out Falgran Hastil, one of our trackers, to see if he can find where the tracks lead." } })
apply(1285, { "classic", "forever" }, { deDE = { completion = "Vermisst? Das wäre Tesorans barmherzige Umschreibung für einen Verräter.\n\nZweifellos ist er einer der Narren, die so treu zu Admiral Daelin standen, dass er zum Verräter wurde. Ist das nicht eine köstliche Ironie? Die Deserteure beschuldigen uns, dass wir die Allianz verraten." }, enUS = { completion = "Missing? That would be Tesoran's kind way of saying traitor.\n\nNo doubt he's one of those fools so blindly loyal to Admiral Daelin that he turned traitor.  Isn't that a delicious irony? The deserters accuse us of betraying the Alliance." } })
apply(1286, { "classic", "forever" }, { deDE = { completion = "Hat Mumm Euch geschickt? Konnte seine Drecksarbeit nicht selbst erledigen, was..." }, enUS = { completion = "Did Vimes send you? Couldn't do his dirty work himself, could he..." } })
apply(1287, { "classic", "forever" }, { deDE = { completion = "Ich schicke Lieutenant Caldwell, damit er sich um die Deserteure bei der verlassenen Wacht kümmert. Darüber hinaus befehle ich ihm Reethe zu suchen. Der Sumpf ist nicht so groß und ungangbar, dass er ihn nicht finden könnte." }, enUS = { completion = "I will send Lieutenant Caldwell to deal with the deserters at Lost Point. In addition, I will instruct him to find Reethe. The marsh is not so big and trackless that he should be unable to find him." } })
apply(1301, { "classic", "forever" }, { deDE = { completion = "James? Oh, der ist schon vor einer Weile fort.\n\nIch schätze, er hat seine patriotische Ader entdeckt. Ist auch nicht so schwer zu verstehen. Bei dem ganzen Wahnsinn in Lordaeron folgten viele Leute Jaina Proudmoore, als sie über das Meer kam." }, enUS = { completion = "James? Oh, he left quite some time ago.\n\nFelt the second wind of patriotism, I suppose. Not hard to see why he would. With all the insanity in Lordaeron, many people joined up with Jaina Proudmoore when she went across the sea." } })
apply(1302, { "classic", "forever" }, { deDE = { completion = "James Hyal, James Hyal... Warum kommt mir der Name so bekannt vor?\n\nNatürlich! Der Vorfall im Gasthaus Zur süßen Ruh. Wenn Ihr Informationen habt, was dort geschehen ist, beschwöre ich Euch, mit Captain Mumm darüber zu sprechen. Er leitet die Ermittlungen." }, enUS = { completion = "James Hyal, James Hyal... Why does that name sound so familiar?\n\nOf course! The Shady Rest Inn incident. If you have any information about what happened there, I would urge you to speak with Captain Vimes about it. He's handling the investigation." } })
apply(1319, { "classic", "forever" }, { deDE = { progress = "Etwas, das ich mir ansehen soll?", completion = "Hm... interessantes Stück Eisen habt Ihr da. Definitiv nicht von einem der Schmiede, die ich diesseits des Meeres kenne, und gewiss nicht mein Werk." }, enUS = { progress = "Something for me to look at?", completion = "Hm... interesting piece of iron you have here. Definitely not made by any of the blacksmiths I know over on this side of the sea, and it's certainly not my work." } })
apply(1320, { "classic", "forever" }, { deDE = { completion = "Das sind keine sehr ergiebigen Informationen, aber wir müssen sie berücksichtigen. Hoffentlich fügen sich noch ein paar Teile dieses Puzzles zusammen und ergeben ein hoffnungsvolleres Bild der Geschehnisse." }, enUS = { completion = "That's not much information to work on, but we'll have to keep it in mind. Hopefully some of the other pieces of this mystery will fall into place, and paint a more helpful picture of what happened." } })
apply(1321, { "classic", "forever" }, { deDE = { progress = "Etwas für mich, {class}?", completion = "Das ist ein guter Schild. Sehr stark, schwer, gut. Aber Do'gol braucht ihn nicht. Ich mache Schilde, ich kaufe sie nicht, {name}.\n\nDas solltet Ihr wissen." }, enUS = { progress = "Something for me, {class}?", completion = "This is good shield. Very strong, heavy, good. But Do'gol don't need it. I make shields, not buy them, {name}.\n\nYou should know that." } })
apply(1322, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Beutel der Spinnen bekommen?", completion = "Ich mag keine Spinnen, die so groß sind, dass ich mich nicht darauf setzen und sie zerquetschen kann.\n\nDanke, dass Ihr sie geholt habt, {name}. Jetzt reiße ich sie auf und gieße den Inhalt auf den Schild..." }, enUS = { progress = "Did you get them sacs from the spiders?", completion = "I don't like spiders that are so big I can't sit on them and squish them.\n\nThanks for getting them, {name}. Now I rip them open and pour them onto the shield..." } })
apply(1323, { "classic", "forever" }, { deDE = { completion = "Mosarn? Kommt mir bekannt vor... Ich komm nicht drauf. Vielleicht fällt es mir später wieder ein.\n\nWahrscheinlich ist es nicht wichtig. Ein Schild kann von überall stammen und keine Bedeutung haben..." }, enUS = { completion = "Mosarn? Sounds familiar... I can't put my finger on it. Maybe it'll come to me later.\n\nIt probably isn't important. A shield can come from anywhere and not mean anything..." } })
apply(1324, { "classic", "forever" }, { deDE = { completion = "Ich versichere Euch, wir sind alle außer uns wegen der jüngsten Ereignisse, aber lasst ihn uns zum Verhör nach Theramore bringen, dann sehen wir, ob wir den König finden.\n\nIch bin sicher, Milady Proudmoore möchte Euch für Eure Hilfe danken. Sprecht mit Ihr, wenn Ihr einen Moment Zeit habt." }, enUS = { completion = "I assure you, we're all quite upset about current events, but allow us to take him back to Theramore for some questioning, and we'll see about finding the King.\n\nI'm sure my lady Proudmore would like to thank you for your help. Speak to her when you have a moment." } })
apply(1338, { "classic", "forever" }, { deDE = { progress = "Ein Brief aus dem Zwergenland? Ich frage mich, wer von so weit aus dem Norden kommen mag...\n\nBitte lasst mich die Bestellung sehen.", completion = "Ah, eine Bitte von einem der Stormpikes. Das ist ein stolzer Klan erstklassiger Zwerge. Und reich sind sie auch.\n\nDanke, {name}. Ich werde noch heute Abend mit der Arbeit am Schild von Gebirgsjäger Stormpike beginnen." }, enUS = { progress = "A letter from the dwarven lands?  I wonder who would call from so far to the north...\n\nPlease, let me see the order.", completion = "Ah, a request from one of the Stormpikes.  That's a proud clan, full of quality dwarves.  Rich ones, too.\n\nThank you, {name}.  I'll get to work on Mountaineer Stormpike's shield by the end of the day." } })
apply(1339, { "classic", "forever" }, { deDE = { completion = "Ganz recht. Ich habe eine Aufgabe, die ich auf Wache nicht erledigen kann. Sie wird Euch weit vom Loch Modan wegführen.\n\nDie perfekte Chance auf ein Abenteuer!" }, enUS = { completion = "That's right.  I have a task that I can't do while I'm guarding.  In fact, it'll take you far from Loch Modan.\n\nYour perfect chance for adventure!" } })
apply(1358, { "classic", "forever" }, { deDE = { progress = "Habt ihr ein Päckchen für mich?", completion = "Ah, sehr gut. Wenn die ersten Berichte wahr sind, kann die Giftigkeit dieser Herzen uns weiteren Fortschritt im Wissen über Gifte bringen.\n\nDas ist eine willkommene Lieferung, {name}. Ihr habt Eure Belohnung wohl verdient." }, enUS = { progress = "You have a package for me?", completion = "Ah, very good.  If initial reports are true, then the toxicity of these hearts could lead to further advances in our knowledge of poisons.\n\nThis is a welcome delivery, {name}.  Your reward is well earned." } })
apply(1359, { "classic", "forever" }, { deDE = { progress = "Habt Ihr etwas für mich?", completion = "Ah ja, die Herzproben, von denen Renferrel sprach. Ich bin ganz erpicht darauf, mit ihnen Experimente durchzuführen... für die Königliche Apothekervereinigung ist es immer von Interesse, wenn neue Toxinformen entdeckt werden." }, enUS = { progress = "You have something for me?", completion = "Ah yes, the heart samples of which Renferrel spoke.  I am eager to experiment with these... it is always of interest to the Royal Apothecary Society when new forms of toxins are discovered." } })
apply(1360, { "classic", "forever" }, { deDE = { progress = "Na, konntet Ihr die Troggs lange genug in Schach halten, um zu meiner Truhe zu gelangen und Euch meinen Schatz zu schnappen?", completion = "Ah, ich fühle mich wieder komplett - ich danke Euch sehr.\n\nManche Zwerge schätzen den Glanz von Metall und andere schätzen den Glanz von Edelsteinen... aber ein Stoutarm ohne einen liebevoll gehüteten Bierkrug ist kein Stoutarm!" }, enUS = { progress = "Well now, we're you able to get slap around those troggs long enough to get into my chest and nab my treasure?", completion = "Ah, I feel complete again - thank you kindly.\n\nSome dwarves may treasure the luster of metal, and some may treasure the glint of gems... but a Stoutarm without a treasured stein in hand is hardly a Stoutarm at all!" } })
apply(1361, { "classic", "forever" }, { deDE = { completion = "Ja, ich rekrutiere. Die Mission führt nach Desolace und geht gegen die Zentauren dort. Ich fasse mich kurz, damit Ihr rasch beginnen könnt." }, enUS = { completion = "Yes, I am recruiting.  This mission leads into Desolace, against the centaur there.  I will be brief so that you may quickly begin." } })
apply(1362, { "classic", "forever" }, { deDE = { completion = "Seid Ihr auf Befehl von Regthar hier? Dann seid Ihr hier, um es den Zentauren zu zeigen. Gut.\n\nIch hoffe, Ihr seid erholt. Ich weiß nicht, wie unsere Kampagne gegen die Zentauren enden wird, aber ich weiß, es wird ein langer Kampf sein.\n\nNehmt Platz und hört zu." }, enUS = { completion = "You are here on orders from Regthar?  Then you are here to deal with the centaur.  Good.\n\nI hope you're rested.  I don't know how our campaign against the centaur will end, but I know the struggle will be long.\n\nHave a seat, and listen." } })
apply(1364, { "classic", "forever" }, { deDE = { progress = "Was führt Euch in die Burg Nethergarde, {race}?", completion = "Ah, grandios!\n\nIch fürchtete schon geraume Zeit, Meister Mazen in der Akademie der Arkanen Künste und Wissenschaften könnte meine Anfrage nach Khadgars 'Abhandlungen über dimensionale Konvergenz' übersehen haben.\n\nAngesichts der vielen seltsamen Vorkommnisse wird er bestimmt mit Anfragen überschwemmt.\n\nWenn Ihr mich jetzt entschuldigen würdet, ich muss sofort mit meinen Forschungen beginnen. Endlich Einblick in ein Genie wie Khadgar zu bekommen, erfüllt mich mit freudiger Erregung." }, enUS = { progress = "What brings you to Nethergarde Keep, {race}?", completion = "Ah, most splendid!\n\nFor some time I had feared my request for Khadgar's Essays on Dimensional Convergence had been overlooked by Master Mazen of the Academy of Arcane Arts and Sciences.\n\nHe must be bogged down with requests considering the many strange happenings going on.\n\nNow, if you'll excuse me, I need to begin my research at once. To finally glimpse the insight of one as great as Khadgar excites me to no end." } })
apply(1365, { "classic", "forever" }, { deDE = { progress = "{name}, habt Ihr Khan Dez'hepah besiegt?", completion = "Gut gemacht. Das rasche Vorgehen gegen die Kolkar zeugt von Kraft, und Kraft verstehen die Zentauren am besten.\n\nDer Tod des Anführers der Kolkar wird diesen Klan nicht schwächen, aber den anderen eine Pause gewähren." }, enUS = { progress = "{name}, have you defeated Khan Dez'hepah?", completion = "Well done.  This swift act against the Kolkar is an effective show of strength, and strength is what the centaur understand best.\n\nThe death of the Kolkar leader will not only disrupt that clan, but give pause to the others." } })
apply(1366, { "classic", "forever" }, { deDE = { progress = "Wie ist Eure Ohrensammlung, {name}? Groß?", completion = "Inzwischen müssen die Zentauren Euren Namen kennen. Ich bin sicher, sie kennen ihn und respektieren und fürchten ihn. Und genau wie Euch kennen sie das Banner, unter dem Ihr reitet.\n\nDas Banner der Horde." }, enUS = { progress = "How is your collection of ears, {name}?  Large?", completion = "By now, the centaur must know your name.  I'm sure they know it, and respect it, and fear it.  And just as they know you, they know the banner under which you ride.\n\nThe banner of the Horde." } })
apply(1367, { "classic", "forever" }, { deDE = { completion = "Die Gelkis weinen, wenn sie Euren Namen hören, {name}. Sie fürchten und hassen Euch. Sie hassen Euch so sehr wie die Magram!\n\nVielleicht seid Ihr so stark wie die Magram. Wir werden sehen..." }, enUS = { completion = "The Gelkis cry when they hear your name, {name}.  They fear you and they hate you.  They hate you like they hate the Magram!\n\nMaybe you are strong like the Magram.  We will see..." } })
apply(1368, { "classic", "forever" }, { deDE = { completion = "Die Erde spricht zu mir. Und sie sagt, Ihr habt viele Magram getötet. Das ist gut.\n\nWenn Ihr ein Freund der Gelkis seid, dann hört zu. Ich habe weitere Aufgaben für Euch." }, enUS = { completion = "The earth speaks to me.  And it says you have killed many Magram.  This is good.\n\nIf you are a friend of the Gelkis, then listen.  I have more tasks for you." } })
apply(1369, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr nicht unser Feind seid, dann tut Ihr, was ich verlange!", completion = "Ihr habt die Tränen! Jetzt wissen die Gelkis, dass Theradras ihnen nicht helfen wird. Sie wird nicht weinen, wenn wir sie zerschmettern! Die Magram werden herrschen!\n\nEs war klug, uns zu helfen, {name}. Wir sind die Stärksten." }, enUS = { progress = "If you are not our enemy, then you will do what I ask!", completion = "You got the tears!  Now the Gelkis will know that Theradras will not help them.  She will not cry when we crush them!  The Magram will rule!\n\nYou are smart to help us, {name}.  We are the strongest." } })
apply(1370, { "classic", "forever" }, { deDE = { progress = "Kommt wieder, wenn Ihr Euch der Gelkis abermals als würdig erwiesen habt!", completion = "Gut. Ich kann das laute Magenknurren der Magram aus ihrem weit entfernten Dorf hören!\n\nIch gebe dieses Fleisch den Gelkis. Und wir werden viele Tage ohne Unterbrechung kämpfen können.\n\nWas Ihr getan habt, war gut für die Gelkis, {name}." }, enUS = { progress = "Return after you further prove your worth to the Gelkis!", completion = "Good.  I can hear the loud Magram bellies grumble from their village, far away!\n\nI will give this meat to the Gelkis.  And we will fight for many days without rest.\n\nWhat you did is good for the Gelkis, {name}." } })
apply(1371, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr nicht unser Feind seid, dann tut Ihr, was ich verlange!", completion = "Ja, genau so etwas hatte ich! Ich bringe sie wieder dazu, sich zu bewegen. Das bringt mich zum Lachen!" }, enUS = { progress = "If you are not our enemy, then you will do what I ask!", completion = "Yes, this is what I had!  I will make it move again.  It makes me laugh!" } })
apply(1372, { "classic", "forever" }, { deDE = { completion = "Zraedus erzählte mir gerade von dem neugierigen kleinen Spitzel, ehe Ihr gekommen seid.\n\nWirklich ein Problem. Ein Naseweis, der im Bettlerschlupfwinkel herumschnüffelt, hat uns gerade noch gefehlt.\n\nIch bin sicher, die Orcs in Stonard können es kaum erwarten, zu hören, was unser Freund zu sagen hat. Da sie unsere, ähem, Verbündeten sind, müssen wir ihnen helfen, von dem Menschen alle Informationen zu bekommen.\n\nArbeitet mit mir, {name}, und wir bringen ein Wahrheitsserum nach Stonard.\n\nFür die Horde!\n\n... war das richtig?" }, enUS = { completion = "Zraedus was just telling me about the nosey little Infiltrator before you arrived.\n\nQuite a problem, indeed. The last thing we need is a busybody sniffing around Beggar's Haunt.\n\nI am sure the orcs of Stonard would be quite anxious to hear what our friend has to say. Seeing that they are our allies, ahem, we must help them to get any information they can from the human.\n\nWork with me, {name}, and we will deliver a truth serum to Stonard.\n\nFor the Horde!\n\n...did I get that right?" } })
apply(1373, { "classic", "forever" }, { deDE = { progress = "Zeigt mir, dass Ihr ein Freund der Gelkis seid, {name}.", completion = "Ja, das ist der Splitter, von dem die Erde flüsterte. Ich spüre starke Magie darin! Ich werde diese Magie gegen die Feinde der Gelkis einsetzen.\n\nIhr habt eine weitere Aufgabe für uns erledigt, {name}. Vielleicht werden wir Euch bald Freund nennen." }, enUS = { progress = "Show me you are a friend of the Gelkis, {name}.", completion = "Yes, this is the shard of which the earth whispered.  I can feel strong magic in it!  I will use this magic against the enemies of the Gelkis.\n\nYou have done one more task for us, {name}.  Maybe soon, we will call you friend." } })
apply(1374, { "classic", "forever" }, { deDE = { progress = "Zeigt mir, dass Ihr ein Freund der Gelkis seid, {name}.", completion = "Khan Jehn war stark, aber dumm. Er dachte, seine Kraft wäre groß. Er sah nicht, dass Erdmagie stärker ist. Ohne Anführer werden die Zentauren der Magram fallen und die Gelkis eines Tages herrschen!" }, enUS = { progress = "Show me you are a friend of the Gelkis, {name}.", completion = "Khan Jehn was strong, but stupid.  He thought his own strength was great.  He did not see that earth magic is stronger.  The Magram centaur will now fall without their leader, and the Gelkis will one day rule!" } })
apply(1375, { "classic", "forever" }, { deDE = { progress = "Erledigt diese Aufgabe für die Magram und ich helfe Euch.", completion = "Khan Shaka ist tot! Ich stecke seinen Kopf auf eine Lanze und nehme ihn mit, damit Shaka die Kraft der Magram sehen kann!" }, enUS = { progress = "Do tasks for the Magram, and I will help you.", completion = "Khan Shaka is dead!  I will place his head on a pike, and keep it with me so Shaka can see the strength of the Magram!" } })
apply(1380, { "classic", "forever" }, { deDE = { progress = "Ist Khan Hratha tot? Habt Ihr das Schlüsselfragment?", completion = "Er ist tot! Khan Hratha ist tot! Und jetzt werden die Maraudine untergehen! Wenn die Gelkis dieses Land regieren, {name}, werden wir uns Euer erinnern. Und die Geister der Erde werden für alle Zeiten Euren Namen singen." }, enUS = { progress = "Is Khan Hratha dead?  Do you have the key fragment?", completion = "He is dead!  Khan Hratha is dead!  And now the Maraudine will fall!  When the Gelkis rule this land, {name}, we will remember you.  And the spirits of the earth will sing your name for all time." } })
apply(1381, { "classic", "forever" }, { deDE = { progress = "Tut, was ich verlange. Beweist mir, dass Ihr ein Verbündeter der Magram seid!", completion = "Khan Hratha ist tot! Jetzt sind die Magram die stärksten aller Zentauren! Wir werden die anderen zerschmettern und Desolace beherrschen!\n\nWir werden uns Euer erinnern, {name}, und unsere Hufen werden Euch verschonen, wenn alle anderen zertrampelt werden." }, enUS = { progress = "Do what I ask.  Prove to me that you are an ally of the Magram!", completion = "Khan Hratha is dead!  Now the Magram are the strongest of the centaur!  We will crush the others, and rule Desolace!\n\nWe will remember, you, {name}, and you will be spared our hooves when all others are trampled." } })
apply(1382, { "classic", "forever" }, { deDE = { completion = "Unter den Gelkis raunt man erführchtig Euren Namen. Ihr habt viel Blut der Magram an den Händen. Das ist gut.\n\nVielleicht ist es auch gut, wenn wir reden. Erzählt, was Ihr für die Gelkis tun könnt und was wir für Euch tun können.." }, enUS = { completion = "Your name is whispered among the Gelkis.  You have much Magram blood on your hands.  This is good.\n\nMaybe it is also good if we speak.  Speak of what you can do for the Gelkis, and what we can do for you." } })
apply(1383, { "classic", "forever" }, { deDE = { progress = "Dieser Spitzel in Stonard wird bestimmt ganz... offen... wenn er mein Spezialserum getrunken hat. Ha-ha!\n\nDie erforderlichen Zutaten sind nicht leicht zu beschaffen. Schattenpanther kommen im Sumpf häufig vor, aber genug Herzen für unsere Zwecke zu beschaffen, kann schwierig sein. Und der Morastlord kann so eine heikle Bestie sein.\n\nWas den Tiefschreitertumor angeht, die sind schrecklich schwer zu finden. Aber die chemische Reaktion, die ich damit auslösen kann, ist unübertroffen.", completion = "Großartig, {name}! Und gerade rechtzeitig. Wie Zraedus mir sagte, hat der Spitzel sich von seinen Verletzungen erholt und kann von den Orcs verhört werden.\n\nGebt mir einen Augenblick, um das Gif..., ich meine das Wahrheitsserum vorzubereiten." }, enUS = { progress = "That Infiltrator in Stonard will surely.... open up... after he drinks my special serum. Haha!\n\nThe ingredients required are by no means easy to procure. Shadow Panthers are common in the Swamp but collecting enough hearts for our purpose can be daunting. And the Mire Lord can be such a fussy beast.\n\nAs for the Deepstrider tumor, they are terribly difficult to find. But the chemical reaction I can draw from it is second to none.", completion = "Splendid, {name}! And just in time too. From what Zraedus tells me, the Infiltrator has recovered from his wounds and is ready to be questioned by the orcs.\n\nGive me but a moment to prepare the pois-- I mean prepare the truth serum." } })
apply(1384, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Glücksbringer? Habt Ihr den Kolkar gezeigt, dass sie schwach sind?", completion = "Ihr habt etwas Gutes für die Gelkis getan. Die Kolkar sind schwach und werden sterben. Ihre Magie ist jämmerlich und wird sie nicht retten. Ihr habt ihnen das gezeigt und ihre Angst wird sie noch schwächer machen!\n\nUnd in unserem Land sterben die Schwachen schnell." }, enUS = { progress = "You have the charms?  You showed the Kolkar they are weak?", completion = "You do a good thing for the Gelkis.  The Kolkar are weak and will die.  Their magic is pathetic and will not save them.  You showed them this, and their fear will make them even more feeble!\n\nAnd in our lands, the feeble soon die." } })
apply(1385, { "classic", "forever" }, { deDE = { completion = "Viele Gelkis fielen Euch zum Opfer. Das gefällt mir. Vielleicht könnt Ihr noch mehr, das mir gefällt. Vielleicht könnt Ihr und die Magram Freunde sein." }, enUS = { completion = "Many Gelkis fall to you.  I like that.  Maybe you can do more things I like.  Maybe you and the Magram can be friends." } })
apply(1386, { "classic", "forever" }, { deDE = { completion = "Die Kolkar fürchten Euch jetzt! Hoffentlich habt Ihr gelacht, als Ihr sie getötet habt. Es ist gut, wenn man beim Töten lacht, dann sieht der Gegner, dass er schwach ist." }, enUS = { completion = "The Kolkar fear you now!  I hope you laughed when you killed them.  It is better to laugh when you kill, so the enemy can see he is weak." } })
apply(1387, { "classic", "forever" }, { deDE = { progress = "Habt Ihr einen Bericht, {name}?", completion = "Ah, die Ohren. Gut gemacht.\n\nEure Verdienste um die Allianz stehen außer Frage, {name}. Das Blut, das Ihr in Desolace vergossen habt, wird zweifellos zahllose Leben retten." }, enUS = { progress = "Do you have a report, {name}?", completion = "Ah, the ears.  Well done.\n\nYour service to the Alliance is unquestioned, {name}.  The blood you spilled in Desolace will, no doubt, save countless lives." } })
apply(1388, { "classic", "forever" }, { deDE = { progress = "Ich hoffe, Ihr habt Euch unserem teuren Freund, dem Apotheker Faustin, als nützlich erwiesen.", completion = "Ich wusste, der alte Faustin würde sich was Gutes ausdenken! Ihr wart zweifellos eine enorme Hilfe.\n\nKommen wir nun zum Geschäft, ja?" }, enUS = { progress = "I hope you have proven yourself of use to our dear friend, Apothecary Faustin.", completion = "I knew old Faustin would come up with something good! You were a tremendous help, no doubt.\n\nNow let's get down to business, shall we?" } })
apply(1389, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Kristalle?", completion = "Danke, {name}. Wir stehen in Eurer Schuld." }, enUS = { progress = "Do you have the crystals?", completion = "Thank you, {name}.  We, are in your debt." } })
apply(1391, { "classic", "forever" }, { deDE = { progress = "Bitte habt Erbarmen mit mir! Ich habe Informationen, die über die Bande der Allianz hinausgehen. Ich hege keine Sympathie für die Horde, aber hier findet ein politischer Verrat statt, der ans Licht gebracht werden muss!", completion = "Ein Getränk für mich? Wie gütig. Sie haben mich seit Tagen nichts mehr trinken lassen. Ich trinke das rasch und dann erzähle ich Euch, was ich herausgefunden habe..." }, enUS = { progress = "Please have mercy on me! I have information that goes beyond alliance boundaries. While I am no sympathizer of the Horde, there is political treachery going on that must be revealed!", completion = "A drink for me? How kind. It's been days since they've allowed me to drink. Let me drink this down and then I'll tell you what I've learned...." } })
apply(1392, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt. Und willkommen im sicheren Hafen.", completion = "Habt Ihr die Waffe des verhassten Noboru? Ist er denn tot?\n\nDas ist ein Freudentag für den sicheren Hafen. Noboru und seine Bande waren ein Schrecken für uns, denn sie zogen durch die Sümpfe und töteten jeden Draenei, der ihren Weg kreuzte. Er war eine unmittelbare Bedrohung für unser Überleben und wir hatten nicht die Kraft, ihm zu trotzen.\n\nWir sind glücklich, einen Freund in Euch zu haben, {name}." }, enUS = { progress = "Greetings.  And welcome to the Harborage.", completion = "You have gained the weapon of the dreaded Noboru?  Is he then dead?\n\nThis is a joyous day for the Harborage.  Noboru and his gang were a terror to us, wandering the swamps and killing any Draenei who crossed his path.  He was a direct threat to our survival, and we did not have the strength to face him.\n\nWe are fortunate to have a friend in you, {name}." } })
apply(1393, { "classic", "forever" }, { deDE = { completion = "Das Schlüsselloch dieser Geldkassette ist voll von schwarzem Harz. Man kann sie unmöglich öffnen.\n\nAber Galen erzählte Euch von einem geheimen Schalter an der Unterseite des Kastens... \n\n... Nach einer kurzen Suche findet Ihr den Schalter. Der Schalter kippt und die Geldkassette öffnet sich..." }, enUS = { completion = "The keyhole of this strongbox is filled with black resin.  It is impossible to open.\n\nBut Galen told you of a hidden latch on the box's bottom... \n\n...After a quick search the latch is found.  The latch is flipped, and the strongbox opens..." } })
apply(1394, { "classic", "forever" }, { deDE = { completion = "Ah, {name}. Es ist lange her, seit Ihr mein Heim das letzte Mal betreten habt. Anscheinend sind viele Monde vergangen, seit Ihr den ersten Schritt auf Eurem Weg gegangen seid.\n\nUnd jetzt kehrt Ihr stärker als einst zu mir zurück... erleuchteter. Das freut mich. Und Ihr solltet gerecht belohnt werden, weil ihr meine Tests bis zum Ende durchgehalten habt." }, enUS = { completion = "Ah, {name}. It has been a long time since you have last stepped into my home. It seems like many moons have passed since you took your first leap that set you upon your path.\n\nAnd now you return to me stronger than you once were... more enlightened. This pleases me. And you should be justly rewarded for seeing my tests to the end." } })
apply(1395, { "classic", "forever" }, { deDE = { progress = "Hallo! Stört Euch nicht an dem Durcheinander, so ist das immer in der Burg Nethergarde.\n\nHabt ihr denn etwas für mich?", completion = "Ah, die Kraftsteine! Die Magier werden sich freuen, die zu sehen!\n\nVielen Dank, {name}. Ich weiß, Eure Reise von Dunkelhain war nicht leicht." }, enUS = { progress = "Hello!  Don't mind all the commotion, it's just business as usual at Nethergarde Keep.\n\nYou have something for me?", completion = "Ah, the powerstones!  The mages will be happy to see these!\n\nMany thanks, {name}.  I know your trip from Darkshire was not an easy one." } })
apply(1396, { "classic", "forever" }, { deDE = { completion = "Die Geräusche der Tiere klingen jetzt leiser, ferner. Danke, {name}. Hoffentlich kommen sie nicht zurück!" }, enUS = { completion = "The sounds of animals are now faint, more distant.  Thank you, {name}.  Now let's hope they don't return!" } })
apply(1398, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Treibholz gefunden, {name}?", completion = "Dieses Holz ist leicht, aber fest. Danke, {name}. Es ist genau richtig." }, enUS = { progress = "Did you find any driftwood, {name}?", completion = "This wood is light, but tough.  Thank you, {name}.  It will work nicely." } })
apply(1418, { "classic", "forever" }, { deDE = { completion = "Helgrum möchte einen Bericht, hm? Ich sandte einen Kundschafter nach Stonard, das ist noch keine drei Tage her. Hat er seine Mission nicht erfüllt? Wenn Stonard meinen Bericht nicht hat, muss er versagt haben.\n\nHoffen wir, dass der nächste Läufer, den ich schicke, mehr Fertigkeiten oder mehr Glück hat." }, enUS = { completion = "Helgrum wants a report, eh?  I sent an outrunner to Stonard not three days past.  Did he fail his mission?  If Stonard does not have my report, then it appears he did fail.\n\nLet's hope the next runner I send has more skill, or more luck." } })
apply(1419, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Kieferknochen?", completion = "Das ist eine nette Sammlung Kieferknochen, {name}. Jetzt werden diese Kojoten nicht mehr unsere Vorräte nach Futter durchwühlen.\n\nGut gemacht. Die Kojoten des Ödlandes sind keine leichte Beute. Eure Tat zeigt mir, dass Ihr hier tatsächlich überleben könntet." }, enUS = { progress = "Do you have the jawbones?", completion = "That's a nice collection of jawbones, {name}.  Now those coyotes won't be tearing through our supplies for scraps.\n\nWell done.  The coyotes of the Badlands aren't easy prey.  Your deed shows me that you might just survive here." } })
apply(1420, { "classic", "forever" }, { deDE = { progress = "Ihr seid zurück. Habt Ihr einen Bericht?", completion = "Danke, {name}. Neekas Bericht entnehme ich, dass die Allianz selbst auch Probleme hat. Und wir können feststellen, dass einige Feinde gemeinsame Feinde sind." }, enUS = { progress = "You returned.  You have a report?", completion = "Thank you, {name}.  From Neeka's report, I see the Alliance is not without its own problems.  And we may find that some enemies are shared between us." } })
apply(1421, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Hexerreagenzien, {name}?", completion = "Ah, Ihr habt sie gefunden! Damit können die Hexer in Nethergarde ihre Arbeit fortsetzen. Ich weiß nicht, was sie tun, aber es hat mit dem Dunklen Portal in den verwüsteten Landen zu tun und ist wichtig für die Sicherheit der Allianz." }, enUS = { progress = "Do you have the wizard's reagents, {name}?", completion = "Ah, you found them!  With these, the wizards in Nethergarde may continue their work.  I do not know what it is that they do, but it is linked to the Dark Portal in the Blasted Lands, and is vital to the security of the Alliance." } })
apply(1422, { "classic", "forever" }, { deDE = { completion = "Schweigt einen Moment, {class}. Trotz der dumpf tosenden Brandung könnt Ihr das abscheuliche Gluckern der Fischmenschen hören." }, enUS = { completion = "Be silent a moment, {class}. Even over the dull roar of the sea you can still hear those disgusting gurgles from the fish men." } })
apply(1423, { "classic", "forever" }, { deDE = { progress = "Habt Ihr etwas für mich?", completion = "Ah, vielen Dank, {name}! So viele Vorräte gehen auf dem Weg von Dunkelhain hierher verloren. Es tut gut zu sehen, dass einige davon wiederbeschafft werden." }, enUS = { progress = "You have something for me?", completion = "Ah, thank you {name}!  So many supplies are lost from Darkshire to here.  It's good to see that some are recovered." } })
apply(1424, { "classic", "forever" }, { deDE = { progress = "Niemand weiß, welche dunklen Rituale im Tempel von Atal'Hakkar durchgeführt wurden. Aber wir wissen, dass große und mächtige magische Kräfte benutzt wurden.\n\nWir müssen so viel wir können über diese Magie lernen. Vielleicht erweisen sich die Zauber der Atal'ai als nützlich für die Horde.\n\nWenn Ihr genügend Artefakte der Atal'ai rings um den Tränenteich gesammelt habt, verstehe ich vielleicht, was sich die Trolle erhofften und was so schrecklich schief gegangen ist.", completion = "Euer Geschick beim Aufspüren der Artefakte der Atal'ai verdient höchstes Lob, {class}." }, enUS = { progress = "No one knows what dark practices went on inside The Temple of Atal'Hakkar. But we do know that great and powerful forces of magic were used.\n\nWe must learn as much as we can about such magic. Perhaps the spells of the Atal'ai will prove of use to the Horde.\n\nOnce you have gathered enough Atal'ai artifacts from around the Pool of Tears, I can begin to understand what the trolls were hoping to accomplish and what went so horribly wrong.", completion = "Your diligence in collecting the Atal'ai artifacts is worthy of praise, {class}." } })
apply(1425, { "classic", "forever" }, { deDE = { progress = "Habt Ihr etwas mit mir zu schaffen?", completion = "Was? Ein Päckchen von Briggs' Karawane? Wir dachten, es wäre verloren, genau wie er.\n\nDanke, {name}. Mit etwas Glück befinden sich bei diesen Vorräten die dringend benötigten Reagenzien Azorankristalle. Unser Vorrat wird knapp..." }, enUS = { progress = "You have business with me?", completion = "What?  A package from Biggs' caravan?  We thought it, and he, were lost.\n\nThank you, {name}.  With luck, these supplies will carry the much needed reagent, Azoran Crystals.  Our stock is running low..." } })
apply(1426, { "classic", "forever" }, { deDE = { progress = "Ich bin geduldig. Geduldig und ewig wie ein alter Kankstein von Draenor. Die Fischmenschen werden unsere Grenzen nicht passieren - nicht solange ich stehe. Hätten wir eine Armee, würde ich diese Welt und alle anderen von ihnen säubern. Ich spüre, wie mein Hass lodert, wenn ich nur von ihnen spreche.", completion = "Das Meer wirkt weit und unbarmherzig, doch Ihr habt es mit dem Blut seiner eigenen Brut besudelt. Die Fischmenschen kennen den Schmerz. Durch ihre Dummheit müssen sie ihre Reihen nach der Verheerung, die Ihr über sie brachtet, neu auffüllen, und das ist gut.\n\nSollen ihre gurgelnden Schreie das Brüllen der Brandung noch bis weit in die Nacht übertönen. Ich werde jedes Mal lächeln, wenn einer von ihnen verstummt.\n\nKehrt zu mir zurück, wenn Ihr noch mehr Fischmenschen töten wollt. Ich werde Euch gern abermals belohnen." }, enUS = { progress = "I am patient. Patient and everlasting like an old kank stone from Draenor. The fish men shall not make it past our borders--not while I still stand. If we had an army at our disposal I would cleanse this world and all others of their presence. I feel my hatred seethe just speaking about them.", completion = "The sea seems vast and relentless, but you have stained her with the blood of her own spawn. The fish men know pain. Their stupidity will force them to refortify their ranks from the devastation you've caused, and that is good.\n\nLet their gurgling screams overshadow the sea's roar long into the night. I shall smile every time I hear one of them silenced.\n\nReturn to me if you wish to slay more of the fish men. I will gladly reward you again." } })
apply(1427, { "classic", "forever" }, { deDE = { completion = "Ah, {name}, Ihr seid zurück. Gut. Ich habe weitere Waffen für unseren Kampf gegen die Murlocs hergestellt. Da Ihr uns frisches Sägezahnfleisch gebracht und ein Lächeln auf Katars Gesicht gezaubert habt, biete ich Euch eine davon an." }, enUS = { completion = "Ah, {name}, you've returned. Good. I've finished crafting more weapons for our fight against the murlocs. For bringing us the fresh sawtooth meat, and for bringing a small smile to Katar's face, I offer one of them to you." } })
apply(1428, { "classic", "forever" }, { deDE = { progress = "Erst wenn das Meer und all seine Kinder verstummt sind, werde ich zufrieden sein... besonders diese abstoßenden Fischmenschen.", completion = "Gut gemacht, {class}. Ich möchte mehr von ihrem Blut sehen. Mögen alle Fischmenschen verschwinden." }, enUS = { progress = "Not until the sea and all her children are silenced will I be pleased... especially those disgusting fish men.", completion = "Well done, {class}. I call for more of their blood. Let all the fish men perish." } })
apply(1429, { "classic", "forever" }, { deDE = { progress = "Ihr seid tapfer, hierher zu kommen. Tapfer oder töricht...", completion = "Bringt Ihr mir die Beschwörungsartefakte der Atal'ai?\n\nIch sehe, dass Jammal'an der Prophet die Schüler der Kammer des Blutes zu ihrem gewählten Schicksal führen wird. Ob Hakkar wohl zum Tempel zurückgekehrt ist? Hat sich ihr Schicksal erfüllt?" }, enUS = { progress = "You are brave to come here. Brave or foolish...", completion = "You bring me the summoning artifacts of the Atal'ai?\n\nI see Jammal'an the Prophet is leading the disciples of the Chamber of Blood towards their chosen fate. Has Hakkar returned to the Temple I wonder? Has their fate been met?" } })
apply(1430, { "classic", "forever" }, { deDE = { progress = "Ich habe ein Fässlein Wein, das auf Euren Erfolg wartet, {name}. Es ist nur recht und billig, dass ich meine Ware prüfe, bevor ich sie zu den Kunden liefern lasse.", completion = "Ah, das müsste perfekt sein. Ich kann es kaum erwarten, sie zu kosten, wenn sie perfekt über einem offenen Feuer zubereitet wurden. Ihr solltet eine Kostprobe mit auf Eure Reisen nehmen. Es ist wirklich köstlich." }, enUS = { progress = "I have a cask of wine waiting for your success, {name}. It's only right I taste the goods before I have it shipped back to my customers.", completion = "Ah, this should be perfect. I can't wait to taste these after they are prepared perfectly over an open fire. You should take a sample of it with you on your travels. It truly is delicious." } })
apply(1431, { "classic", "forever" }, { deDE = { completion = "Putanni, Edler {class}. Ich bin Keldran, Student der Magie... und anderer mystischer Künste.\n\nDie Angelegenheit, in der Craven Euch hergeschickt hat, erfordert ein klein wenig mehr Feinsinnigkeit als bisher erforderlich war, aber das bedeutet nicht, dass Ihr unserer Sache nicht dienlich sein könnt.\n\nBitte macht es Euch bequem, dann sage ich Euch, warum der Kriegshäuptling meine Unterstützung braucht... und Eure.\n\nEs fängt mit Äußerlichkeiten an, {name}. Wie die Horde sich selbst sieht. Wie unsere Verbündeten uns sehen. Und am wichtigsten, wie unsere Feinde uns sehen." }, enUS = { completion = "Putanni, noble {class}. I am Keldran, student of magic... and other mystical arts.\n\nThe business Craven sent you here to speak to me about requires a touch more subtlety than you've previously needed, but that does not mean you can not still aid our cause.\n\nPlease, make yourself comfortable, and I shall tell you why the Warchief has need of my aid... and yours.\n\nIt starts with appearances, {name}. How the Horde sees itself. How our allies see us. And most importantly, how our enemies see us." } })
apply(1432, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {class}. Ihr bringt Neuigkeiten aus Orgrimmar, das ist gut.\n\nDie Dämonenbrut beherrscht dieses Gebiet noch schlimmer als der Geruch von Zentaurendung. Die Pferdemenschen beanspruchen dieses Land für sich, aber es gibt eindeutig Einflüsse außerhalb ihrer Kontrolle, die sie zerschmettern, hält man sie nicht im Zaum.\n\nEs freut mich nicht, dass wir die Zentauren indirekt unterstützen, aber es dient dem Wohl der Horde, daher erfülle ich meine Pflicht gegenüber dem Kriegshäuptling, auch wenn es bedeutet, dass ich den Hexenmeistern in der Horde helfen muss." }, enUS = { completion = "Greetings, {class}. You bring news from Orgrimmar; that is good.\n\nThe demon infestation overwhelms this area even more than the smell of centaur dung. The horse-men claim this land as their own, but clearly there are influences out of their control that will crush them if not kept in check.\n\nIt does not please me that we aid the centaur indirectly, but it is for the good of the Horde, so I do my duty for the Warchief, even if it means helping the warlocks within the Horde." } })
apply(1433, { "classic", "forever" }, { deDE = { completion = "Ah, ja. Hilfe von denen, die dem Kriegshäuptling loyal sind, ist immer willkommen.\n\nMein Name ist Maurin. Ich bin hier auf Geheiß von Keldran und dem jungen Kriegshäuptling Thrall. Es ist mein Wunsch, dem jungen Anführer gegen das Böse beizustehen, das seine Regentschaft zu stören droht.\n\nKommt, kommt näher, {class}. Ich erkläre Euch meinen Plan, wie man die Eiterbeule Burning Blade beseitigen kann." }, enUS = { completion = "Ah, yes. Aid from those loyal to the Warchief is always appreciated.\n\nMy name is Maurin. I am here at the behest of Keldran and the Warchief cub Thrall. It is my desire to aid the youngling leader against the evils that threaten his rule.\n\nCome, come closer, {class}. I shall explain to you my plan for removing the festering boil that is the Burning Blade." } })
apply(1434, { "classic", "forever" }, { deDE = { completion = "Ihr habt Eure Sache gut gemacht, {class}. Ihr habt Ehre und Entschlossenheit gezeigt.\n\nWenn Eure Kampagne in Desolace beendet ist, wird der Kriegshäuptling erfahren, dass ihr uns bei unseren Aktionen hier unterstützt und geholfen habt, dass sein Wille geschehe.\n\nIch danke Euch." }, enUS = { completion = "You have done well, {class}. You have shown honor and dedication.\n\nWhen our campaign in Desolace is done, the Warchief will know that you aided us in our actions here, and that you helped make his will manifest.\n\nI thank you." } })
apply(1435, { "classic", "forever" }, { deDE = { progress = "Ich habe versucht, die Magie so einfach wie möglich zu machen. Es sollte ein Kinderspiel sein, den Geist Eures Opfers aus seiner verletzten Hülle herauszuziehen. Verlasst Euch aber nicht darauf, dass die Macht des Edelsteins Eure Gegner ganz tötet. Ihr dürft den Edelstein erst aktivieren, wenn sie dem Tode nahe sind, sonst ist er wirkungslos.", completion = "Ah, Ihr seid erfolgreich zurückgekehrt. Das ist gut. Gebt mir die Edelsteine und ich verwahre sie an einem sicheren Ort...\n\nMeine Aufgaben für Euch sind abgeschlossen, {class}. Sprecht mit Takata, wenn Ihr erholt seid. Er hat vielleicht andere Aufgaben für Euch oder bittet Euch nach Orgrimmar zurückzukehren, um Keldran von den Fortschritten hier in Desolace zu informieren." }, enUS = { progress = "I have tried to make the magics as simple as possible. Drawing the spirit of your victim out of its injured form should be child's play. Do not rely on the gem's power to slay your foe completely. You must only activate the gem when they are close to death, or it will be useless.", completion = "Ah, you've returned successful. That is good. Give me the gems and I shall put them someplace safe....\n\nMy tasks for you are complete, {class}. Speak to Takata when you are rested. He may have other tasks for you, or perhaps needs you to return to Orgrimmar to inform Keldran of our progress here in Desolace." } })
apply(1436, { "classic", "forever" }, { deDE = { completion = "Ihr seid mehr als erfolgreich aus Desolace zurückgekehrt, {name}. Danke.\n\nDanke für Eure Bemühungen, Eure Zeit und Euer Verständnis für meine Bitte. Thrall versteht und wünscht Frieden zwischen der Horde und der Allianz, und wenn wir Maßnahmen ergreifen, um unser Erscheinungsbild zu verbessern, werden wir keine weitere sinnlose Gewalt provozieren.\n\nIch stehe in Eurer Schuld." }, enUS = { completion = "You have returned from Desolace more than successful, {name}. Thank you.\n\nThank you for your efforts, your time, and your understanding to my plea. Thrall understands and desires peace between the Horde and Alliance, and by taking measures to insure our appearance is acceptable, we will not provoke any further threats of unnecessary violence.\n\nI am indebted to you." } })
apply(1437, { "classic", "forever" }, { deDE = { completion = "Als Ihr in den Überresten des Wagens sucht, stellt Ihr fest, dass er mit Zauber und mit Waffen angegriffen wurde. Es scheint ein ungleicher und schneller Kampf gewesen zu sein; Blut ist keines zu sehen, auch keine Toten.\n\nWer immer den Wagen angegriffen hat, war tüchtig und schnell." }, enUS = { completion = "As you rummage around the remains of the wagon, it becomes obvious that it was attacked by both spells and weapons. The battle seemed one-sided and quick; there's no blood to be found, and no remains of any bodies.\n\nWhoever attacked the wagon was efficient and swift." } })
apply(1438, { "classic", "forever" }, { deDE = { completion = "Elune sei Dank, endlich kommt jemand zu Hilfe. Bitte, {class}, ich brauche Eure Hilfe. Mein Bruder Tyranis und ich wurden von den Burning Blade gefangen genommen und hierher gebracht. Ich glaube, sie wollen mich ihren Dämonenmeistern opfern!\n\n Ich weiß, es war ein Fehler, nach Desolace zu kommen, aber Tyranis entwickelte jüngst ein Interesse an allem Arkanen - gegen den Wunsch unserer eigenen Leute. Er beschloss, diese Reise zu machen, als er von der Dämonenplage des Landes erfuhr.\n\nIch fürchte das Schlimmste für ihn." }, enUS = { completion = "Thank Elune someone has finally come to help. Please, {class}, I need your help. My brother Tyranis and I were captured and brought here by the Burning Blade. I think they mean to sacrifice me to their demon masters!\n\n I knew coming to Desolace was a mistake, but Tyranis has recently begun craving knowledge of all things arcane--even against the wishes of our people. He decided to make this trek even after hearing tales of this land's demon infestation.\n\nI fear the worst for him." } })
apply(1439, { "classic", "forever" }, { deDE = { progress = "Ich fürchte, Tyranis wird versuchen, die Geheimnisse der Burning Blade zu erlernen und sich ihnen anschließen, wenn sie ihn lassen - er hat stets die Macht bewundert, die Magie allen bringt, die sich von ihr verführen lassen.\n\nIch bin nicht sicher, ob ich zu meiner Familie zurückkehren und ihnen sagen kann, dass Tyranis' Geist mit solchen Gefahren spielt. Bei meinesgleichen ist es ein schreckliches Verbrechen, so etwas zu suchen, aber das zu werden, wovor wir uns schützen möchten, das ist verständlich.", completion = "Das ist schrecklich! Aber ich denke, es war notwendig. Hättet Ihr es nicht getan, dann gewiss einer meines Volkes. Ich nehme an, ich sollte Euch danken... bitte verzeiht mir, wenn es unaufrichtig wirkt. Es war nicht böse gemeint.\n\nDa ich das Schicksal meines Bruders nun kenne, scheint es mir an der Zeit zu fliehen. Wenn Ihr noch gewillt seid, nehme ich Eure Hilfe an, um von diesem schrecklichen Ort zu fliehen.\n\nSolltet Ihr bereit sein, können wir uns in Sicherheit bringen." }, enUS = { progress = "I fear Tyranis will attempt to learn the Burning Blade's secrets and count himself among their kind if they allow it--he has always adored the power magic brings to those who are seduced by it.\n\nI'm not sure I could endure returning home to my family with news of Tyranis' spirit flirting with such dangers. It's a terrible enough crime among my kind to pursue such things, but to become that which we attempt to protect ourselves from, well, that's apprehensible.", completion = "This is terrible! But I suppose it was necessary. If it wasn't by your hand, it would have surely been by that of my people's. I suppose I should thank you--please forgive me if it doesn't seem sincere. I mean no offense.\n\nWith the knowledge of my brother's fate in hand, it seems the time for my escape has come. If you are still willing, I will accept your aid in escaping this horrible place.\n\nWhen you are ready, we can make our way to safety." } })
apply(1440, { "classic", "forever" }, { deDE = { completion = "Danke, {name}. Dalinda hat es wohlbehalten zur Nijelspitze geschafft und in besserer Verfassung, als ich es für möglich gehalten hätte. Allein, dass sie aus eigener Kraft hier eintraf, war ein gutes Zeichen. Ich hoffe, es geht Euch gut.\n\nEs schmerzt mich zu wissen, dass weder Tyranis noch Dalinda zurückgekehrt sind, aber mit der Schande von Tyranis' Entscheidungen muss sie leben. Damit muss sie sich auseinander setzen, wenn sie nach Darnassus zurückkehrt." }, enUS = { completion = "Thank you, {name}. Dalinda made it safely back here to Nijel's Point, and in much better condition than I could have asked for. The fact that she arrived here under her own power was a good sign. I hope you're well?\n\nIt pains me to know that both Tyranis and Dalinda didn't return, but the embarrassment of Tyranis' decisions is hers to endure. It is something she will have to deal with when she returns to Darnassus." } })
apply(1442, { "classic", "forever" }, { deDE = { progress = "Bei einem, der nicht dem heiligen Weg folgt, wäre ich nicht so vertrauensselig, wenn er nach einem Kor-Edelstein fragen würde. Aber ich traue Euresgleichen fast mehr als meiner Art. Ich beurteile nicht Euren ganzen Orden nach den Taten eines gefallenen Mitglieds.", completion = "Das ist wahrhaftig der Edelstein, den Stilwell begehrt, doch ehe ich zulassen kann, dass Ihr ihn zu ihm bringt, muss er von Verderbnis geläutert werden - die Frauen der Naga stärken die Edelsteine mit Macht, das stimmt, aber mit ihrer eigenen bösen Macht.\n\nLasst Stilwell wissen, dass die Macht unversehrt ist und bei jedem Ritual, das er durchführen möchte, funktionieren sollte.\n\nIch hoffe nur, Ihr wisst, was Ihr tut, {class}, es ist kein einfacher Gegenstand, den Ihr da besitzt." }, enUS = { progress = "I would be less trustful of one not on a holy path if they came asking about a Kor gem. But I trust your kind more than some of my kin. I do not judge your entire order based on the actions of just one of your fallen kind.", completion = "This is indeed the gem Stilwell desires, but before I can allow you to bring it to him, it must be purified of corruption--the naga wenches imbue the gems with power, that much is true, but of their own, evil kind.\n\nLet Stilwell know that its power is intact, and it should work well for whatever ritual he wishes it to be part of.\n\nI hope you know what you're doing, {class}, this is no simple item you possess." } })
apply(1444, { "classic", "forever" }, { deDE = { completion = "Es ist eine Weile her, seit wir miteinander sprachen, {class}. Ich hoffe, Eure Reise war erfolgreich.\n\nWelches Wissen habt Ihr von dem verbannten Atal'ai im Hinterland erlernt?" }, enUS = { completion = "It has been quite some time since we spoke, {class}. I hope your journey was successful.\n\nWhat knowledge did you gain from the exiled Atal'ai in the Hinterlands?" } })
apply(1445, { "classic", "forever" }, { deDE = { progress = "Wenn die Fetische der Atal'ai die Macht besitzen, Hakkar zu beschwören und Jammal'ans Prophezeiung zu erfüllen, müssen wir sie haben. Die Horde muss solche Mächte verstehen!", completion = "Tapferer {class}, Ihr habt Euch als ein großer Held der Horde erwiesen.\n\nWir müssen uns unverzüglich um diese Fetischsammlung von Hakkar kümmern!" }, enUS = { progress = "If the Atal'ai fetishes hold the power to summon Hakkar and fulfill Jammal'an's prophecy they must be seized. Such powers must be understood by the Horde!", completion = "Brave {class}, you have proven yourself to be a great champion of the Horde.\n\nNow this collection of fetishes of Hakkar must be dealt with at once!" } })
apply(1446, { "classic", "forever" }, { deDE = { progress = "Sobald Jammal'an nicht mehr ist, habe ich die Chance, zu meinem Volk zurückzukehren.\n\nMit Jammal'an als ihrem spirituellen Anführer ist der Untergang der Atal'ai gewiss.", completion = "Jammal'ans blindes Vertrauen in falsche Visionen führte mein Volk in die ewige Verdammnis.\n\nIch danke Euch, {class}, dass Ihr meine Verbannung gerächt habt. Ich trauere um mein Volk. Jetzt habe ich keine Heimat mehr." }, enUS = { progress = "Once Jammal'an has been removed, I stand a chance of returning to my people.\n\nWith Jammal'an as their spiritual leader, the Atal'ai face certain destruction.", completion = "Jammal'an's reckless trust of false visions led my people to their eternal doom.\n\nI thank you, {class}, for avenging my exile. I mourn for my people. I have no home to return to." } })
apply(1447, { "classic", "forever" }, { deDE = { progress = "Ich dachte mir nichts bei der Bemerkung, dass Ihr dumm seid, {class}. Wir sind Freunde, oder? Nichts für ungut?", completion = "Es gibt also einen Grund, dass Ihr zu mir kommt. Was ist Euer Begehr?" }, enUS = { progress = "I didn't mean anything by the comment 'bout you being a stupid {class}. We're friends, right? No hard feelings?", completion = "So, you came to me for a reason. What is it you need?" } })
apply(1448, { "classic", "forever" }, { deDE = { completion = "Der Tempel von Atal'Hakkar ist im Tränenteich versunken? Und vom grünen Drachenschwarm umzingelt?\n\nEine erstaunliche Entdeckung, {class}. Aber offenkundig ist etwas furchtbar schief gegangen." }, enUS = { completion = "The Temple of Atal'Hakkar has been sunk beneath the Pool of Tears? And surrounded by the green dragonflight?\n\nAn amazing discovery, {class}. But obviously something has gone terribly wrong." } })
apply(1449, { "classic", "forever" }, { deDE = { completion = "Was wollt Ihr, Jüngelchen? Seht Ihr denn nicht, dass ich mich hier um Probleme kümmern muss? Wer hat schon Zeit, hier rumzustehen und mit einer Quasselstrippe von {race} zu plaudern?\n\nEs kommen Trolle aus dem Unterholz! Fasst Euch kurz." }, enUS = { completion = "What do you want, laddy? Can't you see I've got problems to take care of here? Who has time to stand around yapping with some {race} chatterbox?\n\nThere are trolls coming out of the woodwork! Make it snappy." } })
apply(1451, { "classic", "forever" }, { deDE = { completion = "Hicks!\n\nIch seh Euch gerade an, aber Ihr hüpft immerzu auf und ab. Das macht mich ganz schwindelig. Hoho!\n\nHicks!\n\nBoah! Habt Ihr das gespürt? Die Erde bebt. Ich muss was trinken.\n\nHicks!" }, enUS = { completion = "Hiccup!\n\nI'm a-lookin' right at you but you keep bobbing up and down. Makin' me dizzy. Hoho!\n\nHiccup!\n\nWhoa! Did ya feel that? Ground is a-shakin', my friend. I need a drink.\n\nHiccup!" } })
apply(1452, { "classic", "forever" }, { deDE = { progress = "Schon mal ein Rhapsody-Malzbier getrunken? Eines meiner besten Gebräue, wenn ich das so sagen darf. Hicks!\n\nAber wenn ich den Schrecken dieses Fluges über... hicks... den Sumpf noch mal durchleben soll, brauch ich was deutlich Stärkeres. Hicks!\n\nIhr habt wohl nicht zufällig die Muskelmägen und Lebern gefunden, die meinem Kalimdor-Cocktail den richtigen Pfiff geben?\n\nHicks!", completion = "Wie ich sehe, habt Ihr mir mühelos beschafft, was ich brauche! War bestimmt nicht leicht für Euch im fernen Kalimdor.\n\nDauert nur einen Moment, bis ich aus den Muskelmägen und Lebern extrahiert habe, was ich brauche. Hicks!\n\nDann kann ich mir einen starken Drink brauen und Euch endlich erzählen, was Ihr wissen wollt.\n\nHicks!\n\nWenn ich nur an den ollen Sumpf denke, krieg ich 'ne Gänsehaut.\n\nHicks!\n\nIch werd den Drink schnell zusammenrühren." }, enUS = { progress = "Ya ever had a Rhapsody Malt? One of my finest brews, if I do say so myself. Hiccup!\n\nBut if I'm gonna relive the horrors of that fateful flight over... hiccup... the swamp, well I'm gonna need me something a wee bit stronger. Hiccup!\n\nDon't suppose you found me those gizzards and livers I need to add that extra kick to my Kalimdor Kocktail?\n\nHiccup!", completion = "I see ya had no trouble at all getting me what I need! Musta been quite a stint you had over there in far-off Kalimdor.\n\nIt won't take but a moment for me to extract what I need from these gizzards and livers. Hiccup!\n\nThen I can distill me a fierce ol' drink and finally tell ya what ya wanna know.\n\nHiccup!\n\nGetting shivers just thinking about that ol' swamp.\n\nHiccup!\n\nLemme whip up a drink real fast." } })
apply(1453, { "classic", "forever" }, { deDE = { completion = "Schön zu sehen, dass die Wiederbeschaffer nicht knapp an Arbeit oder Abenteurern sind, die ihnen aushelfen wollen.\n\nIch bin Kreldig, {name}. Es war eine kluge Entscheidung, den Wiederbeschaffern zu helfen. Heutzutage braucht jeder irgendetwas: Die Leute verlieren ein Familienerbstück, einen magischen Gegenstand oder einen geliebten Menschen. Es ist schon recht erstaunlich. Aber wenn die Wiederbeschaffer in der Gegend sind, gibt es keinen Grund, warum nicht jeder für einen angemessenen Preis wiederbekommen sollte, was er verloren hat." }, enUS = { completion = "Glad to see the Reclaimers aren't in short supply of work, or adventurers willing to help out.\n\nI'm Kreldig, {name}. You've made a smart move helpin' out the Reclaimers. Everyone needs something these days: they've lost a family heirloom, a magic item, a loved one. You never can tell. But with the Reclaimers around, there's no reason, for the right price, everyone can't find what they've lost." } })
apply(1454, { "classic", "forever" }, { deDE = { completion = "Ihr bemerkt, dass die Truhe keine Wasserschäden genommen hat.\n\nAls Zweites bemerkt Ihr, dass der Deckel aufgebrochen wurde. Eventuelle magische Fallen, die der Sicherung dienten, wurden längst ausgelöst - das erkennt man an den Brandspuren an den Kanten." }, enUS = { completion = "You notice the chest does not seem to have any water damage.\n\nThe second thing you notice is that the top has been forced open, and whatever magical traps were set to safeguard it have long been triggered--this much is obvious from the burn marks around its edges." } })
apply(1455, { "classic", "forever" }, { deDE = { completion = "Willkommen in der Nijelspitze, {name}. Sagt mir, was Ihr gefunden habt.\n\nWas!? Nichts? Ich fürchte, eine leere Truhe bringt uns keinen Lohn ein.\n\nErzählt mir mehr von diesen Spuren, die Ihr gesehen habt... diesen Rillen." }, enUS = { completion = "Welcome back to Nijel's Point, {name}. So, tell me what you found.\n\nWhat!? Nothing? An empty chest ain't gonna get us paid, I'm afraid.\n\nTell me more about these marks you saw... these slashes." } })
apply(1456, { "classic", "forever" }, { deDE = { progress = "Nicht, dass ich Nijel zu nahe treten wollte, wer immer das sein mag, aber dieses Lager ist nicht das bequemste, in dem ich je eine Nacht verbrachte, {name}.", completion = "Das ist toll, {name}! Ihr habt Karnitols Habseligkeiten gefunden!\n\nDiese elenden Naga machen ständig Ärger. Ich würde lieber mein Leben lang Krieg gegen die Horde führen als gegen ihre Art anzutreten. Ihr habt den Wiederholern einen großen Dienst erwiesen." }, enUS = { progress = "No offense to whoever Nijel is, but this camp ain't the most comfortable place I've spent a night, if you know what I mean, {name}.", completion = "This is great, {name}! You found Karnitol's belongings!\n\nThose blasted naga, always causing trouble. I think I'd rather spend my life at war with the Horde than have to go against their kind. You've done a great service to the Reclaimers." } })
apply(1457, { "classic", "forever" }, { deDE = { progress = "Das Geschäft blüht, {name}, und ich habe nicht viel Zeit für Fragen. Wenn Ihr etwas von den Wiederholern wollt, rückt heraus damit. Wenn nicht, muss ich Euch bitten, mit einem meiner Handlanger zu sprechen. Sie sind durchaus imstande, sich um alles hier zu kümmern.", completion = "Ah, die Karnitol-Angelegenheit in Desolace. Exzellent!\n\nDie Truhe wurde also zerstört, aber die Gegenstände sind alle da, hm? Tja, das soll er selbst nachprüfen. Ein Gutes hat das Geschäft, das ich hier betreibe: Wenn er nicht zufrieden ist, kann ich ihm sagen, er soll in den Wind schießen! Die Leute erwarten von uns, dass wir ihr Zeug finden ... und nicht, dass alles in perfektem Zustand ist, wenn sie es zurückerhalten.\n\nGute Arbeit, {name}. Dann wollen wir Euch mal Euren Lohn geben." }, enUS = { progress = "Business is booming, {name}, and I don't have a lot of time for questions. If you've got business with the Reclaimers, then let's hear it. If not, I'm gonna have to ask you to talk to one of me underlings--they're adept enough at taking care of things 'round here.", completion = "Ah, the Karnitol business in Desolace. Excellent!\n\nSo, the chest was destroyed, but the items are all here, huh? Well, I'll let him be the judge of that. One good part about this business I got going on here is that if they're not satisfied, I can tell 'em to shove it! They're relyin' on us to find their stuff... not make sure it's all pretty and in good shape when they get it back.\n\nGood work, {name}. Let's see about gettin' you paid." } })
apply(1458, { "classic", "forever" }, { deDE = { progress = "Abscheuliche Kreaturen, die Satyrn. Man sagt, sie seien irgendwie mit den Nachtelfen verwandt, doch das glaube ich nicht.\n\nIch glaube, das liegt nur an dem einen Elfen, der sie vor Jahren überredete, in den Krieg zu ziehen. Das hat die Welt für immer verändert. Heute ist sie viel gefährlicher und Furcht erregender.", completion = "Gut, gut, {name}. Ich bin nicht sicher, ob die Qualität ausreicht, aber wenn Leftwitch eine bestimmte Art wollte, hätte er es genauer sagen müssen, ehe er die Wiederholer losschickte.\n\nGehen wir zum nächsten Gegenstand auf der Liste, ja?" }, enUS = { progress = "Despicable creatures, the satyr. Story says they're somehow tied to the night elves, but I'm not so sure I believe it.\n\nI think they get that on account of that one elf that brought them into the war few years back. World's never been the same since. Lot more dangerous, and a lot scarier.", completion = "Good good, {name}. Not sure if these are of any good quality, but if Leftwitch wanted a specific type, he should have specified before sending the Reclaimers out here to begin with.\n\nWhat say you to getting on with the next item on his list?" } })
apply(1462, { "classic", "forever" }, { deDE = { completion = "Nehmt dies und vergesst nicht, es ist heilig." }, enUS = { completion = "Take this and remember, it is sacred." } })
apply(1463, { "classic", "forever" }, { deDE = { completion = "Ich gebe Euch voller Vertrauen einen. Ihr habt Euren Wert schon einmal bewiesen, doch ich finde, künftig solltet Ihr vorsichtiger sein." }, enUS = { completion = "I give you one in good faith. You already proved yourself once, but me tinkin' you should be more careful in the future." } })
apply(1464, { "classic", "forever" }, { deDE = { completion = "Möge Feuer in Eurem Herzen brennen, {name}.\n\nDie Elemente erwarten Euch." }, enUS = { completion = "May fire burn within your heart, {name}.\n\nThe elements await you." } })
apply(1465, { "classic", "forever" }, { deDE = { completion = "Zum Auswachsen! Dieses ganze Fiasko!\n\nDie beiden waren gewarnt, wie gefährlich es sein würde, hierher zu kommen. Nun werden sie vermisst... oder Schlimmeres.\n\nIhr sagt, Ihr habt Spuren zu einem Fort in der Nähe gesehen? Das dürfte unsere beste Chance sein.\n\nSchenkt man den Einheimischen Glauben, wimmelt es in dieser Festung von Orcs der Burning Blade, die sich dämonischen Mächten verschrieben haben. Sie teilen vielleicht nicht die meisten Ansichten der Horde, sind aber böse und töten ohne Umschweife, wenn sie jemanden beim Spionieren erwischen." }, enUS = { completion = "Infuriating! This entire fiasco!\n\nThe two of them were warned about how dangerous coming here would be. Now they're both missing... or worse.\n\nYou said you saw tracks heading to a fort nearby? That may be our best bet.\n\nFrom what the locals have said, that fortress is infested with members of the Burning Blade--orcs who have dedicated themselves to demon causes. They may not represent the majority of the Horde's beliefs, but they are evil and will slay you on sight if you're caught spying." } })
apply(1466, { "classic", "forever" }, { deDE = { progress = "Ich wusste nicht einmal, dass es diese Dämonenwesen in Desolace gibt. Zuletzt hörte ich, dass das Land weitgehend den Zentauren gehört, nachdem die Nachtelfen vor Jahren zusammengepackt haben und abgezogen sind.\n\nIch frage mich, warum und wie sie hierher kamen.", completion = "Ehrlich? Das hätte ich nicht gedacht. Ihr seid erstaunlich, {name}. Es wegen eines Magierexperiments mit Dämonen aufzunehmen und unversehrt zurückzukehren. Gute Arbeit!\n\nWenn ich wieder in Ironforge bin, werde ich Roetten persönlich von Euch berichten." }, enUS = { progress = "I didn't even realize these demon things were in Desolace. Last I read, centaur pretty much owned the land after the night elves picked up and left years ago.\n\nI wonder why they took up here, and how.", completion = "Honestly? I wouldn't have thought it. You're amazing, {name}. Taking on demons for a mage's experiments, and coming back in one piece to boot. Great job!\n\nI'm personally gonna tell Roetten about you when I get back to Ironforge." } })
apply(1467, { "classic", "forever" }, { deDE = { progress = "Grüße, {name}. Das Geschäft blüht, die Laute von Hämmern auf Ambossen hallen durch ganz Ironforge, die Blasebälge entfachen das Feuer und meine Frau backt mir einen Kuchen als Dessert nach dem Abendessen. Könnte das Leben schöner sein?", completion = "Ah, das Päckchen für Leftwitch aus Desolace. Exzellent. Ich schätze Eure Arbeit und Eure Pünktlichkeit, {class}. Schön, dass wir Euch wenigstens für diesen kleinen Auftrag an Bord haben.\n\nIch habe Euren Lohn hier. Lasst alle wissen, dass die Wiederholer AG für eine harte Arbeit stets guten Lohn bezahlt." }, enUS = { progress = "Well met, {name}. Business is booming, the sounds of anvils being struck rings throughout Ironforge, the bellows blow the fires hot, and me wife's making me a pie for dessert after tonight's dinner. Could life be any grander?", completion = "Ah, the package for Leftwitch from Desolace. Excellent. I 'preciate the work, and your timeliness, {class}. Glad to have you aboard for at least this small bit of work.\n\nI got your payment right here. Let it be known that Reclaimers Inc. always pays well for a hard week's work." } })
apply(1469, { "classic", "forever" }, { deDE = { progress = "Endlich seid Ihr zurückgekehrt, {name}. Es ist eine Weile her, seit wir zuletzt miteinander sprachen. Ich dachte schon, Ihr hättet meinen Auftrag an Euch vielleicht vergessen.\n\nHabt Ihr diesen nichtsnutzigen Greifenreiter gefunden? Hatte er etwas zu berichten?", completion = "Rhapsody Shindigger! Genau... wie konnte ich so einen Namen nur vergessen?\n\nEr wusste also die ganze Zeit von dem versunkenen Tempel? Also das hätte Euch gewiss eine Menge Laufarbeit sparen können.\n\nAber dieses Artefakt der Atal'ai! Das nenne ich einen Fund!" }, enUS = { progress = "At long last you have returned, {name}. It has been quite some time since we last spoke. I thought perhaps you had forgotten about my quest.\n\nDid you locate that wily gryphon rider? Did he have anything to report?", completion = "Rhapsody Shindigger! That's right... how could I forget such a name?\n\nSo he knew about the sinking of the temple all along? Well, that certainly would have saved you some leg work.\n\nBut this Atal'ai artifact! Why, it's quite a find!" } })
apply(1470, { "classic", "forever" }, { deDE = { progress = "Eure Macht ist noch gering, doch ich vermute, Ihr ahnt die Möglichkeiten bereits.\n\nMit der Macht, die uns durchströmt, könnten selbst Tote sich lebendig fühlen.", completion = "Wiewohl Ihr noch unerfahren und am Anfang des Lernens seid, habt Ihr bewiesen, dass Ihr hinreichend Fähigkeiten besitzt, das Beschwören und Binden eines Wichtels zu meistern. Lasst Euch nicht von der Größe eines Wichtels täuschen. Ihm fehlt es zwar an Körperkraft, aber dafür besitzt er Macht und Klugheit, die Euch dienlich sein werden.\n\nHört mir gut zu, {name}, denn ich werde diese Lektion nicht wiederholen und überlasse es Euch, sie zu meistern." }, enUS = { progress = "Your power is little now, though I suspect already you sense the possibilities.\n\nEven the dead might feel alive, with that power coursing through us.", completion = "Though you are still untested and young in your learning, you have proven that you possess sufficient ability to master the summoning and binding of an imp. Do not be deceived by an imp's size. Though it lacks physical strength, it possesses powers and a cleverness that will serve you well.\n\nAttend me carefully, {name}, for I will not repeat this lesson, and I will leave its mastery to you." } })
apply(1471, { "classic", "forever" }, { deDE = { progress = "Ich erwarte, von Eurem Erfolg zu hören, {name}. Doch solltet Ihr scheitern, wird es Eure geringste Sorge sein, dass Ihr meinen Erwartungen nicht entsprochen habt.", completion = "Ihr habt Eure Sache gut gemacht, {name}. Jetzt will ich Euch den Zauber verraten, mit dem der Leerwandler beschworen wird.\n\nDie Macht, die er freisetzt, steht nun zu Eurer Verfügung. Benutzt sie weise." }, enUS = { progress = "I expect to hear of your success, {name}. Not meeting my expectations will be the least of your worries, however, should you fail.", completion = "You have done well, {name}. Now, I will impart to you the spell used for summoning the voidwalker.\n\nThe power that it unleashed upon you is now yours to command. Use it wisely." } })
apply(1473, { "classic", "forever" }, { deDE = { progress = "Egalin war der Lehrmeister, der mich unterrichtete. Er vermochte den Leerwandler, den er beschworen hatte, fast nebenbei zu kontrollieren.\n\nAls ich an der Reihe war, es zu versuchen, überschätzte ich mich. Spielt nicht mit den Mächten, die Ihr besitzt, {name}, sie können selbst den Wachsamsten verzehren.", completion = "Ah, das ist ausgezeichnet. Vermutlich hatte Perrine keine Ahnung von der wahren Macht des verstaubten Buches, das er uns gestohlen hatte.\n\nEs wird uns nicht noch einmal genommen werden. Studiert die Struktur des Zaubers, {name}, und die Art und Weise, auf die Eure Macht kanalisiert werden muss." }, enUS = { progress = "Egalin was the teacher that taught me. With hardly a look, he was able to command the voidwalker he had summoned.\n\nWhen it came my turn to try, I was overconfident. Do not trifle with the powers that you wield, {name}, they can consume even the vigilant.", completion = "Ah, this is excellent. Like as not, Perrine was ignorant to the true power of the musty book he had stolen from us.\n\nIt will not fall out of our hands again. Observe, {name}, the structure of the spell, the manner in which your power must be channeled." } })
apply(1474, { "classic", "forever" }, { deDE = { progress = "Von den Mächten jenseits der Leere ist der Sukkubus eine der gefährlichsten, da er die Schwachen leicht um den Finger wickeln kann.\n\nDenkt jetzt und immerzu daran.", completion = "Wieder habt Ihr Eure Sache gut gemacht, {name}. Es ist eine Weile her, seit ich einen jungen {class} mit so viel Potenzial wie Euch gesehen habe. Seid versichert, dass ich Eure Fortschritte im Auge behalten und Euch bei künftigen Prüfungen vorbereiten und unterstützen werde.\n\nJetzt will ich Euch den Beschwörungszauber für den gerade von Euch unterworfenen Sukkubus zeigen." }, enUS = { progress = "Of the powers from beyond the void, the succubus is one of the most dangerous, as the weak are most easily wrapped around its fingers.\n\nRemember that now and in the future.", completion = "Again, you have done well, {name}. It has been quite some time since I have seen a young {class} with as much potential as you. Be assured that I will continue to watch your progress, and prepare and assist you in your future trials.\n\nFor now, let me show you the summoning spell for your newly dominated succubus." } })
apply(1475, { "classic", "forever" }, { deDE = { progress = "Da sich langsam das Dunkel über meine Laufbahn senkt, wende ich mich an Euch, {name}, damit Ihr mir bei meinem letzten Auftrag für die Forscherliga helft. Wenn meine alten Knochen genug Kraft hätten, die Sümpfe des Elends und den versunkenen Tempel zu meistern, würde ich an Eurer Seite kämpfen.\n\nMein Stolz macht es mir schwer, Euch um Eure Hilfe beim Sammeln der Schrifttafeln der Atal'ai zu bitten. Doch das hohe Alter schließt andere Möglichkeiten aus.\n\nBitte helft mir, {name}. Ich möchte erst aus der Forscherliga ausscheiden, wenn ich ihre letzte Bitte erfüllt habe.", completion = "Die Schrifttafeln der Atal'ai! Ich danke Euch, {name}!\n\nWenn ich sie der Forscherliga übergeben habe, werden unser beider Namen in die Geschichte eingehen. Ihr habt einem alten Zwerg geholfen, die letzte Verpflichtung seines Lebens zu erfüllen. Dafür bin ich Euch ewig dankbar." }, enUS = { progress = "As dusk slowly descends upon my career I turn to you, {name}, to help me in my final quest for the Explorers' League. If my old bones could muster the strength to brave the Swamp of Sorrows and the sunken temple I would be fighting right alongside you.\n\nPride makes it hard for me to ask for your help in collecting the Atal'ai Tablets. But old age forces the necessity.\n\nPlease help me, {name}. I want to retire from the Explorers' League having completed their final bidding.", completion = "The Atal'ai Tablets! Thank you, {name}!\n\nOnce I deliver these to the Explorers' League our names shall go down in history together. You have helped an old dwarf fulfill his final obligation in life. For that I am eternally grateful." } })
apply(1477, { "classic", "forever" }, { deDE = { completion = "Andromath schickt Euch? Sehr gut. Ich habe eine wichtige Aufgabe für Euch..." }, enUS = { completion = "Andromath sent you?  Very good.  I have an important task for you..." } })
apply(1478, { "classic", "forever" }, { deDE = { completion = "Gut, wie ich sehe, konnte Ageron Euch finden, {name}. Vergeuden wir keine Zeit mit müßigem Geplauder und Höflichkeiten, sondern konzentrieren wir uns auf die Ausbildung. Ihr habt immer noch viel zu lernen." }, enUS = { completion = "Good, I see Ageron managed to find you, {name}. Let us waste little time with small talk and pleasantries and focus on your training. There is still much you have to learn." } })
apply(1480, { "classic", "forever" }, { deDE = { progress = "Die Burning Blade begreifen langsam, wie schwach sie wirklich sind. Ihre Magie ist jämmerlich, ihre Stärke lachhaft.\n\nIhre einzige Macht kommt von jenen, denen sie dienen, und nicht von einem Verständnis von wahrer Macht und Wissen.", completion = "Hmm, diese Runen stammen tatsächlich von einer Sprache, {name}, einer alten Sprache. Sie scheinen vage Ähnlichkeit mit der Sprache der Eredun zu haben, doch die Unterschiede sind gewichtig. Wenn ich mich nicht irre, ist dies eine Art von Vertrag... Hier, ja, dieses Symbol ist die Unterschrift eines Dämons: Lord Azrethoc." }, enUS = { progress = "The Burning Blade begin to realize how weak they truly are. Their magics are pathetic, their strength feeble.\n\nTheir only power comes from those they serve, and not from any understanding of true power and knowledge.", completion = "Hmm, these runes are indeed a language, {name}, an old language. They seem remotely similar to the Eredun language, but the differences are drastic. If I am not mistaken, this is a contract of some kind.... Here, yes, this symbol is the demon's signature: Lord Azrethoc." } })
apply(1481, { "classic", "forever" }, { deDE = { progress = "Bringt mir keinen falschen Skalp, {class}. Die falschen Reagenzien würden unseren Tod bedeuten. Der Dämonenlord könnte Kontingenzzauber besitzen, die alle töten, die ihm wahrsagen.\n\nDas Schicksal hat mir schon genug Schmerzen zugefügt.", completion = "Die Schattenpirscher konnten Euch nicht töten, {class}. Eindrucksvoll... höchst eindrucksvoll.\n\nDieser Skalp wird für meinen Zauber genügen. In Eurer Abwesenheit konnte ich einige andere Reagenzien für den Zauber sammeln.\n\nIch bin fast bereit. Ich brauche nur noch einen Fokus für den Zauber... etwas, um ein Bild des Dämonenlords und seines Aufenthaltsortes zu projizieren." }, enUS = { progress = "Do not bring me an incorrect scalp, {class}. Using the incorrect reagents could cause our deaths. The demon lord may have contingency spells on his person to slay those who would scry upon him.\n\nFate has already dealt me enough pain.", completion = "The shadowstalkers were unable to slay you, {class}. Impressive... most impressive.\n\nThis scalp will do nicely for my spell. While you were away, I was able to gather some of the other reagents needed for the spell.\n\nI am almost ready. I only need a focus for the spell--something to project an image of the demon lord and his whereabouts." } })
apply(1482, { "classic", "forever" }, { deDE = { progress = "Ich bin bereit für den Orakelkristall, {class}. Wenn wir diesen Lord Azrethoc finden und vernichten könnten, würden wir beide in der Gunst des Kriegshäuptlings steigen. Wir wären gut beraten, wenn wir eiligst zusammenarbeiten würden, damit wir unsere Sache voranbringen und in der Gunst des Kriegshäuptlings steigen.", completion = "Ein kostbarer Orakelkristall... makellos... wunderschön. So ist es.\n\nWir sollten unverzüglich beginnen. Unsere oberste Sorge sollte sein, diesen Dämonenlord zu finden. Unsere ganze Konzentration muss darauf gerichtet sein, ihn zu töten.\n\nTretet einen Schritt zurück, {class}, und lasst uns sehen, was dieser Dämon ist und wo wir ihn finden können." }, enUS = { progress = "I am ready for the oracle crystal, {class}. Finding and destroying this Lord Azrethoc would garner a great deal of favor with the Warchief for both of us. We would do well to work together and to do so swiftly so we may further our own ends and curry favor with the Warchief.", completion = "A precious oracle crystal... flawless... beautiful. Indeed.\n\nWe shall begin immediately. Finding this demon lord should be our primary concern, and its slaying demands our utmost attention.\n\nTake a step back, {class}, and let us see what this demon is, and where he may be found." } })
apply(1483, { "classic", "forever" }, { deDE = { completion = "Ich dachte, die Bosse der Venture Company wären Sklaventreiber, doch dann traf ich Sputtervalve, den Grausamsten von ihnen!\n\nHa! Aber immer noch besser als arbeitslos zu sein, denke ich... Oder schlimmer, mit diesem Gerenzo zu arbeiten. Wenn Ihr helfen wollt, habe ich etwas für Euch zu tun." }, enUS = { completion = "I thought those Venture Company higher-ups were slave drivers, but then I met Sputtervalve, the cruelest of them all!\n\nHa! Though it's better than being out of a job, I suppose... Or worse, working with that Gerenzo. If you're here to help, I've got something for you to do." } })
apply(1484, { "classic", "forever" }, { deDE = { completion = "Ich wurde Zeuge, was soeben mit Maurin und dem Dämonenlord geschah. Diese Kreatur scheint selbst als Erscheinung mehr Macht zu haben als mein Hexenmeistergefährte. Ich frage mich, ob er der Aufgabe gewachsen ist, das Monster zu besiegen? Es stünde dem Kriegshäuptling besser zu Gesicht, wenn ich selbst ginge, aber angesichts meiner Verantwortung hier würde ich dem Klan Schande machen, wenn ich meine Pflichten hier vernachlässigen würde, um zur eigenen Ehre gegen das Böse zu kämpfen." }, enUS = { completion = "I witnessed what just occurred with Maurin and the demon lord. That creature, even as an apparition, seems to have more power than my warlock companion. I wonder if he's up to the task of defeating the monster? It would serve the Warchief better if I go myself, but with my responsibilities here, I would disgrace my clan if I turned my back on my duties here to battle this evil for my own honor." } })
apply(1485, { "classic", "forever" }, { deDE = { progress = "Es ist wichtig, dass Ihr die Wesen kontrollieren könnt, die Ihr durch Eure Magie beschwört. Nur wenige interessieren sich für die Lehren der {class}, daher möchte ich Euer Leben nicht gefährden, indem ich Euch etwas lehre, ehe Ihr dazu bereit seid.", completion = "Während Eurer Ausbildung zum {class} werdet Ihr lernen, Wesen vielerlei Arten herbeizurufen. Manchen sieht man es nicht an, aber alle sind nützliche Werkzeuge.\n\nLasst Euch nicht von der geringen Größe eines Wichtels täuschen. Ihr habt zweifellos bemerkt, dass sie dennoch gefährliche Widersacher sind." }, enUS = { progress = "It is important that you can control the beings that you summon through your magic. There are few enough interested in learning the ways of the {class} that I would risk throwing your life away by teaching you something before you are ready.", completion = "Throughout your training as a {class}, you will learn to call forth beings of many sorts. Some may not seem it, but all are useful tools.\n\nDo not be fooled by the imp's small size. As you no doubt noticed, it is still a formidable adversary." } })
apply(1486, { "classic", "forever" }, { deDE = { progress = "Ich bin sehr daran interessiert, die Bälge der Deviatkreaturen zu untersuchen, die sich in diesen Höhlen eingenistet haben. Konntet Ihr einige beschaffen, {class}?", completion = "Eure Bemühungen bei der Beschaffung dieser Bälge werden nicht unbemerkt bleiben, {name}.\n\nVielen Dank für Eure Mühe." }, enUS = { progress = "I am very interested in examining the hides from the deviate creatures who have infested these caves. Have you had any luck in collecting some, {class}?", completion = "Your efforts shall not go unnoticed in gathering these hides, {name}.\n\nThank you for your dedication." } })
apply(1487, { "classic", "forever" }, { deDE = { completion = "Als Jünger von Naralex bewundere ich Eure Tapferkeit, {name}.\n\nEure Unterstützung bei der Befreiung der Höhlen ist der erste Schritt bei unserer schweren Aufgabe, das Brachland wiederherzustellen.\n\nVielen Dank, und möge Euch Wohlstand gewiss sein." }, enUS = { completion = "As a Disciple of Naralex, I commend your bravery, {name}.\n\nYour aid in ridding the caverns is the first step in our long plight to see the Barrens restored.\n\nThank you and may you prosper." } })
apply(1488, { "classic", "forever" }, { deDE = { completion = "Ein großer Sieg für uns alle, {name}. Feiern wir unseren Erfolg. Ich gehe jetzt davon aus, dass unsere Zukunft hier nicht so trostlos ist, wie ich einst dachte.\n\nDie Dämonen werden besiegt werden, die Bemühungen der Burning Blade sind zum Scheitern verurteilt und wir haben vielleicht eines Tages einen Ort, den wir eine sichere Heimat nennen dürfen." }, enUS = { completion = "A mighty victory for us all, {name}. Let us rejoice in your success. I trust now that our future here is not as bleak as I once thought.\n\nThe demons will be slain, the Burning Blade will fail in their efforts, and we may one day have a place we can safely call home again." } })
apply(1489, { "classic", "forever" }, { deDE = { completion = "Ich grüße Euch, {name}. Ihr seid hier willkommen und ich schlage vor, dass Ihr all Eure Kraft zusammennehmt. Denn die Aufgabe, die wir Euch stellen... ist schrecklich." }, enUS = { completion = "I bid you greetings, {name}.  You are welcome here, and I suggest you gather all your strength.  For the task we now set before you ... is a dire one." } })
apply(1490, { "classic", "forever" }, { deDE = { completion = "Ja, es stimmt. Ich weiß von den Druiden in den Höhlen des Wehklagens. Ich habe ihre verzerrten schuppigen Gesichter gesehen. Ich kenne ihre Verbrechen ebenso wie ihre Pläne.\n\nIhr müsst sie aufhalten, {name}." }, enUS = { completion = "Yes, it is true.  I know of the druids in the Wailing Caverns.  I have seen their twisted, scaled faces.  I know their crimes, and I know their plans.\n\nYou must stop them, {name}." } })
apply(1491, { "classic", "forever" }, { deDE = { progress = "Wo ist meine Klageessenz?", completion = "Prima, Ihr habt sie! Ich kann es kaum erwarten, sie zu erproben. Das wird mir ein Vermögen einbringen, ich weiß es!\n\nDanke, {name}. Nehmt das. Wenn ich reich bin, schicke ich Euch mehr, versprochen!" }, enUS = { progress = "Where is my wailing essence?", completion = "Great, you got it!  I can't wait to try it out.  This is going to make me a fortune, I just know it!\n\nThank you, {name}.  Take this, and after I'm rich I'll send you more, I promise!" } })
apply(1492, { "classic", "forever" }, { deDE = { progress = "Ihr wollt mit dem nächsten Schiff fahren oder habt einen Gegenstand, der an Bord gebracht werden soll?", completion = "Eine recht kleine Kiste. Ja, dafür müsste ich noch Platz an Bord des Schiffes finden. Es läuft mit der nächsten Flut aus, das dürfte wohl schnell genug sein. Exzellent. Lasst es mich noch eben in mein Geschäftsbuch eintragen.\n\nAlles erledigt! Guten Tag, {class}." }, enUS = { progress = "You seek passage on the next ship, or have some item you wish to send aboard it?", completion = "A small enough crate. Yes, I should be able to find room for this aboard the ship. It sails with the next tide, I trust this is soon enough? Excellent. Let me just enter it into my ledger.\n\nAll taken care of! Good day to you, {class}." } })
apply(1498, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Schuppen, {name}? Wenn Ihr den Angriffen der Donner-Echsen nicht trotzen könnt, könnt Ihr von meiner Unterweisung nicht profitieren.", completion = "Ah. Ich sehe, Ihr habt die Donner-Echsen besiegt, was Eure Zähigkeit beweist. Jetzt zeige ich Euch, wie harte Haut und listige Bewegungen zusammen eine undurchdringliche Verteidigungsmauer bilden können.\n\nPrägt Euch das gut ein, {name}. Und seid bereit für weitere Instruktionen." }, enUS = { progress = "Do you have the scales, {name}?  Unless you can withstand the attacks of the thunder lizards, you will not benefit from my instruction.", completion = "Ah.  I see you have defeated the thunder lizards, which proves you are tough.  Now I will show you how tough skin and shrewd movements can combine to form an impenetrable wall of defense.\n\nLearn your lesson well, {name}.  And be ready for future instruction." } })
apply(1499, { "classic", "forever" }, { deDE = { completion = "Ihr habt Eure Sache gut gemacht, {name}.\n\nDie abscheulichen Familiare waren zwar nur Schoßtierchen der dunkleren Mächte bei den Burning Blade, doch Euer Erfolg gegen sie lässt kommende Großtaten ahnen." }, enUS = { completion = "You have done well, {name}.\n\nAlthough the vile familiars were merely pets of the darker powers within the Burning Blade, your success against them foretells greater deeds ahead." } })
apply(1501, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Schrifttafel der Verga, {name}? Ich wünsche erst wieder mit Euch zu sprechen, wenn Ihr sie habt.", completion = "Gut. Ich hoffe, Ihr habt den Burning Blade weitere Verluste zugefügt, als Ihr dies beschafft habt.\n\nSie sind dem Kriegshäuptling ein Dorn im Auge und eine echte Pest für die {class} im Allgemeinen." }, enUS = { progress = "Do you have the Tablet of Verga, {name}? If not, I do not wish to speak with you until you do.", completion = "Good. I hope you inflicted some other losses on the Burning Blade when you went to retrieve this.\n\nThey have been a source of great annoyance for the Warchief, and a great blight upon warlocks as a whole." } })
apply(1502, { "classic", "forever" }, { deDE = { completion = "Meine Augen sind schon lange ausgetrocknet, weil ich ins Feuer der Schmiede schaute, aber manches kann ich noch sehen. Ich kann sehen, dass Ihr etwas wollt.\n\nUnd da Ihr den Weg hierher gefunden habt, kann ich mir denken, was Ihr begehrt." }, enUS = { completion = "My eyes have long dried out from staring into the forge's flame,  but some things I can still see.  I can see you want something.\n\nAnd if you found your way here, then I can guess what you desire." } })
apply(1503, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meine Stahlbarren?", completion = "Ihr habt sie gefunden! Und alle Stangen sind da, was mich nicht überrascht. Ich glaube nicht, dass die Grimmhauer wussten, was sie mit diesem edlen Stahl anfangen sollten.\n\nDanke, {name}. Hier ist Eure Belohnung. Möge sie Euch nützlich sein." }, enUS = { progress = "Do you have my steel bars?", completion = "You found them!  And all the bars are here, which doesn't surprise me.  I didn't think the Razormanes would know what to do with fine steel like this.\n\nThank you, {name}.  Here is your reward.  May it serve you well." } })
apply(1504, { "classic", "forever" }, { deDE = { progress = "Der Leerwandler ist eine mächtige Kreatur. Ich weiß noch, wie ich an Eurer Stelle war, {name}. Nach diesen vielen Jahren bekämpft mich mein eigener Leerwandler inzwischen etwas weniger stark, aber vermutlich nur, weil er darauf hofft, dass meine Wachsamkeit dann nachlässt.\n\nVergesst das nicht, {name}.", completion = "Ihr habt Eure Sache gut gemacht, {name}. Ich werde Euch zeigen, wie man einen Leerwandler beschwört, der dem, den Ihr gerade besiegt habt, sehr ähnlich ist.\n\nIhr solltet wissen, dass wir große Erwartungen in Euch setzen, und bisher habt Ihr sie auch erfüllt.\n\nAber dass Euch das nicht zu Kopf steigt, denn verglichen mit den Aufgaben, die noch vor Euch liegen, war dies hier ein Kinderspiel." }, enUS = { progress = "The voidwalker is a powerful creature. I remember when it was I that was in your shoes, {name}. Over the years, my own voidwalker has grown to fight me less, though I suspect that is only because it hopes I will let my guard down.\n\nRemember that, {name}.", completion = "You have done well, {name}. I will show you how to summon the voidwalker similar to the one you just defeated.\n\nYou should know that we have high expectations for you, and you have, so far, matched them.\n\nDo not let it go to your head, however, as the tasks that still lie before you will make this seem as simple as waking in the morning." } })
apply(1505, { "classic", "forever" }, { deDE = { completion = "Hallo, Jüngelchen. Seid Ihr zur Ausbildung hier, ja?" }, enUS = { completion = "Hello, young one.  Here for some instruction, are you?" } })
apply(1506, { "classic", "forever" }, { deDE = { completion = "Gut. Ich hatte befürchtet, Ophek würde Euch nicht erreichen.\n\nEs ist Zeit, dass ich Eure Hexenmeisterausbildung fortsetze. Eure aktuellen Angelegenheiten müssen warten.\n\nIch gehe davon aus, dass das kein Problem sein wird." }, enUS = { completion = "Good. I was afraid Ophek wouldn't reach you.\n\nIt is time that I further your {class} training. Any business you have currently will have to wait.\n\nI trust there will not be a problem with this?" } })
apply(1509, { "classic", "forever" }, { deDE = { completion = "Zankaja? Das ist Dograns Gefährtin, nicht?\n\nJa, ich habe von ihm gehört, aber keine Neuigkeiten, die Ihr ihr überbringen solltet...\n\nNein, er ist nicht tot. Aber er ist verletzt und Gefangener der Stacheleber." }, enUS = { completion = "Zankaja? That's Dogran's mate, right?\n\nYeah, I've heard from him, but it's not the sort of news we should let get back to her...\n\nNo, he's not dead. But he is injured and a prisoner of the quilboar." } })
apply(1510, { "classic", "forever" }, { deDE = { completion = "Ein {race}, hm? Ich hoffe, Ihr seid nicht wegen ihm gekommen. Er hat es nicht geschafft. Diese Goblins haben ihn alle gemacht.\n\nEr sagte nur, er bräuchte ein Heilgebräu, sonst nichts." }, enUS = { completion = "Another orc, eh? I hope you haven't come for the other. He didn't make it. Those goblins did him in good.\n\nHe said he needed a healing draught, but not much else." } })
apply(1511, { "classic", "forever" }, { deDE = { progress = "Ja, was gibt's?", completion = "Das wurde auch Zeit! Dogran wäre fast gestorben, während er darauf wartete.\n\nWir müssen den Trunk sofort zu ihm bringen, aber die meisten Grunzer, die hier stationiert sind, befinden sich auf Nahrungssuche." }, enUS = { progress = "Yes, what is it?", completion = "Well, it's about time! Dogran has been dying out there, waiting for this.\n\nWe need to get this out to him right away, but most of the grunts stationed here are out on a foraging mission." } })
apply(1512, { "classic", "forever" }, { deDE = { progress = "Ihr seid zurückgekehrt. Seid Ihr bereit, gegen einen Sukkubus zu kämpfen?", completion = "Wenn Ihr mir sagt, dass dies genügt, dann vertraue ich Euch, {name}. Aber erlaubt mir, ihn zu reinigen... Sauber und glänzend dürfte er für einen Sukkubus noch verlockender sein." }, enUS = { progress = "You have returned. Are you ready to battle a succubus?", completion = "If you tell me that this will suffice, then I trust you, {name}. Allow me to clean it though... Pristine and shining, it may be even more enticing to a succubus." } })
apply(1513, { "classic", "forever" }, { deDE = { progress = "Wenn ich einen Sukkubus ansehe, geht mir das Herz auf... Aber zugleich kann ich fast meiner Seele Niedergeschlagenheit spüren, die wie die Gezeiten abfließt.\n\nSeid wachsam.", completion = "Erfolg! Seid versichert, dass ich von meinem Musterschüler nichts anderes erwartet habe.\n\nIhr habt Euch als würdig erwiesen, daher zeige ich Euch mit Freuden die Methode, wie Ihr Euren unterworfenen Sukkubus beschwört. Geht jetzt, Ihr habt viel zu lernen. Wenn ich Euch das nächste Mal sehe, erwarte ich, dass Ihr wahre Meisterschaft über Euren Sukkubus erlangt habt.\n\nÜberlasst die Trauer um Dogran und Zankaja denen unter uns, die älter an Jahren sind, aber vergesst sie nicht und bewahrt sie als Schutz gegen die Launen der dunklen Macht, die Ihr heute zu beschwören gelernt habt." }, enUS = { progress = "When I look upon a succubus, my heart begins to soar... But at the same time, I can almost sense my soul's ebb, drifting away like the tides.\n\nBe wary, my friend.", completion = "Success! Be sure I expected nothing less from my star pupil.\n\nYou have proven your worth, and gladly will I show you the method of summoning your subdued succubus. Go now, you have much to learn, and when next I see you, I will expect you to have found true mastery over your succubus.\n\nLeave the sorrow of Dogran and Zankaja to those of us who are longer in years, but remember it, and hold it as protection against the wiles of the dark power you have learned to summon today." } })
apply(1516, { "classic", "forever" }, { deDE = { progress = "Geduld ist der Erde größte Tugend. Die Erde sieht den Zyklus aller Dinge: die Berge werden zu Wüsten, Flüsse werden zu Schluchten. Die Erde ist das störrischste und weiseste aller Elemente, sie toleriert keine Ungeduld.\n\nDie Erde ruft Euch nun, denn eine Zeit der Konflikte rückt näher. Wenn Ihr erfolgreich zu mir zurückkehrt, werdet Ihr dem Ziel, ganzheitlich zu werden, sehr viel näher sein.\n\nAndere werden Euch Eure Weisheit neiden und Euch ihrer Unwissenheit wegen hassen.", completion = "Exzellent. Euer Erfolg zeigt, dass Ihr vorbereitet seid.\n\nVon allen Elementen repräsentiert die Erde das Fundament aller Dinge. Sie ist Eure Kraft, Eure Ausdauer und Eure Geduld. Die Erde wird Euch schützen, aber nur, wenn Ihr angemessenen Respekt zeigt. Die Erde kann, wie alle anderen Elemente auch, kleinmütig sein. Die Erde ist die Grundlage des Lebens und wenn Ihr ihre Gesetze achtet, wird Euch größere Weisheit zuteil. Vergesst niemals die Geheimnisse, die die Erde mit Euch teilt.\n\nIch werde jetzt ein Sapta für Euch machen. Wenn Ihr es akzeptiert, werdet Ihr Euren Weg erkennen." }, enUS = { progress = "Patience is earth's greatest virtue. The earth witnesses the cycle of all things: the mountains becoming deserts; rivers becoming canyons. The earth is the most stubborn and wise of all the elements and it does not tolerate impatience.\n\nThe earth beckons you now because a time of conflict draws near. When you return to me successful, then you shall be that much closer to being made whole.\n\nOthers will be envious of your wisdom and hate you for their ignorance.", completion = "Excellent. Your success shows that you are prepared.\n\nOf all the elements, earth represents the foundation of all things. It is your strength, your stamina, and your patience. Earth will protect you, but only if shown the proper respect. Like the other elements, even earth can be fickle. Earth is the basis for life, and by observing its laws, you will gain greater wisdom. Never forget the secrets earth shares with you.\n\nI shall make a sapta for you now, and by accepting it, you will realize your path." } })
apply(1518, { "classic", "forever" }, { deDE = { progress = "Ich möchte der Erste sein, der Euch auf dem ersten der vier Pfade begrüßt, die Euch für immer Eurem Schicksal zuführen werden.\n\nWenn Ihr den Stein besitzt, den Euch die Erde gab, werde ich Euch das versprochene Totem geben.\n\nWenn nicht, hebt Euch hinfort, bis Ihr Euren Weg gefunden habt.", completion = "Exzellent!\n\nDas Totem, das ich für Euch anfertigen werde, ist mehr als nur ein Symbol für Euren Status unter den Schamanen... es besitzt Fähigkeiten, die darüber hinausgehen. Ein Nutzen des Totems ist, dass es als Fokus für Zauber dient. Diese Zauber sind mit der Erde verbunden. Je mehr Weisheit Ihr erlangt, desto mehr Fähigkeiten der Erde werden Euch zugänglich sein.\n\nDie Lehrer werden wissen, wann Ihr für größeres Wissen bereit seid.\n\nNehmt vorerst dieses Erdtotem..." }, enUS = { progress = "I wish to be the first to welcome you fully to the first of four paths that will forever lead you in your destiny.\n\nIf you have the stone the earth gave to you, I will give you the totem it promised.\n\nIf not, then be gone with you until you have found your way.", completion = "Excellent!\n\nThe totem I will craft for you is more than a symbol of your status among {class}--it has abilities beyond that. One use of the totem is as a focus for spells. Those spells are tied to the earth, and as you earn greater and greater wisdom, more of the earth's abilities will be made accessible to you.\n\nThe trainers will know when you are ready for greater knowledge.\n\nBut for now, take this earth totem..." } })
apply(1519, { "classic", "forever" }, { deDE = { progress = "Die Erde ist geduldig und wird auf Euch warten, bis Ihr bereit seid, denn sie weiß, mit der Zeit schwinden alle Dinge und werden wiedergeboren. Das ist der Zyklus des Lebens. Berge werden zu Wüsten. Flüsse werden zu Schluchten. Die Erde ist das störrischste und weiseste aller Elemente.\n\nIhr müsst vor allem Geduld und Ausdauer lernen. Die Erde ruft Euch nun, denn sie spürt, dass Ihr bereit seid. Betrachtet dies als Eure Wiedergeburt, wenn Ihr erfolgreich seid. Hinterher werdet Ihr niemals wieder zur Unwissenheit zurückkehren können.", completion = "Gut, {name}. Eure Rückkehr hierher zeigt, dass Ihr wahrlich für den nächsten Schritt bereit seid.\n\nVon allen Elementen repräsentiert die Erde das Fundament aller Dinge. Sie ist Eure Kraft, Eure Ausdauer und Eure Geduld. Die Erdenmutter wird Euch schützen, aber nur, wenn Ihr ihr den angemessenen Respekt erweist. Sie ist die Grundlage des Lebens und wenn Ihr ihre Gesetze achtet, wird Euch größeres Wissen zuteil. Vergesst niemals die Geheimnisse, die sie mit Euch teilt.\n\nIch werde jetzt Euer Sapta für Euch machen. Wenn Ihr es akzeptiert, wird sich ein neuer Weg vor Euch auftun." }, enUS = { progress = "The earth is patient, and will wait for you until you are ready because she knows in time all things erode and are reborn. It is the cycle of things. Mountains become deserts. Rivers become canyons. The earth is the most stubborn and wise of all the elements.\n\nYou must learn patience and stamina above all things. The earth calls for you now because she feels you are ready. Consider this your rebirth if you succeed. You will never be able to go back to ignorance afterwards.", completion = "Good, {name}. Your return here signifies that you are indeed prepared for the next step.\n\nOf all the elements, earth represents the foundation of all things. It is your strength, your stamina, and your patience. The Earth Mother will protect you, but only if you show her proper respect. She is the basis for life, and by observing her laws, you will gain a greater wisdom. Never forget the secrets she shares with you.\n\nI shall make your sapta for you now, and by accepting it, a new path will open before you." } })
apply(1521, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {name}. Ihr würdet nicht zu mir zurückkehren, wenn Ihr Eure Aufgabe nicht bewerkstelligt hättet. Ich möchte der Erste sein, der Euch auf dem ersten der vier Pfade begrüßt, die für immer Eure Reise beherrschen werden.\n\nWenn Ihr den Stein besitzt, den Euch die Erde gab, werde ich Euch das versprochene Totem geben. Wenn nicht, bedauere ich Euch. Mit großem Stolz erfüllt es den, der sich voll und ganz den Elementen verschrieben hat.", completion = "Großartig.\n\nDas Totem, das ich für Euch anfertigen werde, ist mehr als nur ein Symbol... es besitzt Fähigkeiten, die darüber hinausgehen. Ein Nutzen des Totems ist, dass es als Fokus für Zauber dient. Diese Zauber sind mit der Erde verbunden. Je mehr Weisheit Ihr erlangt, desto mehr Fähigkeiten der Erde werden Euch zugänglich sein. Die Lehrer in ganz Kalimdor werden wissen, wann Ihr für größeres Wissen bereit seid und es Euch sagen, wenn Ihr sie besucht.\n\nNehmt vorerst dieses Erdtotem..." }, enUS = { progress = "Greetings, {name}. You would not return to me if you had not accomplished your task. May I be the first to welcome you fully to the first path of four that will forever rule your travels.\n\nIf you have the stone the earth gave to you, I will give you the totem it promised. If not, then I pity you. There is much pride to be had when you've fully dedicated yourself to the elements.", completion = "Splendid.\n\nThe totem I will craft for you is more than a symbol--it has abilities beyond that. One use of the totem is a focus for spells. Those spells are tied to the earth, and as you earn greater and greater wisdom, more of the earth's abilities will be made accessible to you. Trainers found throughout Kalimdor will know when you are ready for greater knowledge and will let you know as much when you visit them.\n\nBut for now, take this earth totem..." } })
apply(1522, { "classic", "forever" }, { deDE = { completion = "Hmmm, hat Searn Euch geschickt, ja?\n\nAlso Searn kann man immer vertrauen. Er scheint überzeugt, dass Ihr bereit seid, Euer nächstes Sapta zu nehmen, das Feuersapta.\n\nIch sehe es schon in Euren Augen, das Lodern, das Verlangen. Ihr habt von der Macht gekostet und seid jetzt bereit für mehr. Geduld, {name}. Vergesst nicht, was Euch die Erde lehrte. Macht und Zerstörung werden sicherlich kommen, doch Ihr müsst dennoch wissen, wann Ihr Euch zurückhalten solltet." }, enUS = { completion = "Hmmm, Searn sent you to me, did he?\n\nWell then, Searn could always be trusted, so that must mean you're ready to take part of the next sapta--the sapta of fire.\n\nI see it in your eyes already, the burning, the desire. You've tasted power, and now you're ready for more of it. Patience, {name}. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand." } })
apply(1523, { "classic", "forever" }, { deDE = { completion = "Hmmm, hat Xanis Euch geschickt, ja?\n\nAlso Xanis kann man immer vertrauen. Er scheint überzeugt, dass Ihr bereit seid, Euer nächstes Sapta zu nehmen, das Feuersapta.\n\nIch sehe es schon in Euren Augen, das Lodern, das Verlangen. Ihr habt von der Macht gekostet und seid jetzt bereit für mehr. Geduld, {name}. Vergesst nicht, was Euch die Erde lehrte. Macht und Zerstörung werden sicherlich kommen, doch Ihr müsst dennoch wissen, wann Ihr Euch zurückhalten solltet." }, enUS = { completion = "Hmmm, Xanis sent you to me, did he?\n\nWell then, Xanis could always be trusted, so that must mean you're ready to take part of the next sapta--the sapta of fire.\n\nI see it in your eyes already, the burning, the desire. You've tasted power, and now you're ready for more of it. Patience, {name}. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand." } })
apply(1524, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {name}. Ihr befindet Euch am Schrein der schlafenden Flamme. Nur jene, die wahrlich in den schamanistischen Künsten bewandert sind, werden je die Geheimnisse dieses Ortes und der Macht kennen lernen, die er birgt. Tut mir Leid, dass Ihr den weiten Weg auf Euch genommen habt, nur um jetzt abgewiesen zu werden - die Reise hierher ist alles andere als sicher -, aber ich bin der Bewahrer des Schreins und kann nicht jeden hier umherstreifen lassen.", completion = "Ah, mein Fehler, {name}. Ich muss mich entschuldigen. Mir war nicht klar, dass Ihr die Fackel besitzt. Es freut mich, Eure Bekanntschaft zu machen.\n\nViele Abenteurer finden auf der Suche nach verlorenen Schätzen oder der Jagd auf mystische Kreaturen hierher und werden von einem scheinbar leeren Schrein abgewiesen. Aber wir kennen die Wahrheit, nicht, {name}?\n\nDieser Schrein verbirgt ein größeres Geheimnis vor den einfachen Mitgliedern der Horde. Für uns ist er heilig." }, enUS = { progress = "Greetin's, {name}. You've found yourself at the Shrine of the Dormant Flame. Only those knowledgeable enough in the shamanistic arts will ever learn the secrets of this place and the power it holds. I'm sorry you made the trip all this way, only to be turned back now--the journey up here is far from safe after all--but I am the keeper of the shrine, and I cannot allow just anyone to wander around here.", completion = "Ah, my mistake, {name}. I apologize. I did not realize you possessed the Torch. I am pleased to make your acquaintance.\n\nMany adventurers find their way here while looking for lost treasure or the promise of mystical creatures to slay, only to be turned away from a seemingly empty shrine. But we know the truth, do we not, {name}?\n\nThis shrine holds a greater secret from the mundane members of the Horde. To us, it is sacred." } })
apply(1525, { "classic", "forever" }, { deDE = { progress = "Ich habe genügend Zutaten für ein Feuersapta, wenn Ihr den Reagenzienbeutel und etwas Feuerteer finden könnt. Die Fanatiker der Burning Blade tragen die richtigen Komponenten für die meisten ihrer Zauber in diesen Beuteln und haben meist ausreichend von den Gegenständen, die ich benötige, damit Ihr nicht weiter nach etwas anderem suchen müsst.\n\nDie Saptas werden stets aus Zutaten hergestellt, die in enger Verbindung zu ihrem jeweiligen Element stehen. Es macht unsere Arbeit leichter, da die Hexenmeister mit dem Feuer verbunden sind.", completion = "Diese werden genügen, {name}.\n\nFeuer ist mehr als Chaos und Zerstörung... Ihr tut gut daran, das nicht zu vergessen. Es dreht sich auch um Leben und Schöpfung. Alle Dinge sind auf diese Weise miteinander verbunden. Kräfte sind einander entgegengesetzt, doch zugleich kann die eine nicht ohne die andere existieren. Beide löschen sich gegenseitig aus, geben einander aber auch erst einen Sinn. Vergesst das niemals.\n\nUnterschiedliche Arten der Magie in Verbindung miteinander zu verwenden, zeigt nicht nur wahre Fertigkeit, sondern große Weisheit." }, enUS = { progress = "I have enough ingredients for a sapta of fire if you can find the reagent pouch and some fire tar. The Burning Blade fanatics carry the proper components for most of their spells in those pouches, and usually have enough of the items I need that we will not have to search much farther for anything else.\n\nThe saptas are always made from ingredients that are closely tied to their respective elements. It makes our work easier because of the warlocks' ties to fire.", completion = "These will do nicely, {name}.\n\nFire is more than chaos and destruction--do well to remember that. It is also about life, and creation. All things are tied together in such a way. Forces oppose one another, but at the same time, one cannot exist without the other. Both extinguish one another, but also give one another meaning. Always remember this.\n\nUsing different types of magic in conjunction with one another will show not only true skill, but great wisdom." } })
apply(1526, { "classic", "forever" }, { deDE = { progress = "Die Kohlenpfanne hat etwa ein Drittel Eurer Höhe und sieht normal aus, abgesehen von den Inschriften auf ihrem glatten Metallrand. Das Metall scheint nicht vom Wetter angegriffen zu sein und die Schale, die darauf ruht, fühlt sich kalt an.", completion = "Eine weiß glühende Flamme lodert in der Schale auf, als Ihr die Glut hineinlegt. Ihr könnt spüren, wie die magischen Effekte des Sapta durch Euren Körper strömen und das Feuer rhythmisch vor Euch tanzt.\n\nIhr haltet das Ende der Fackel in die Pfanne und sie fängt sofort Feuer." }, enUS = { progress = "The brazier stands about a third your height, and looks normal, save for the inscriptions along its smooth metal rails. The metal shows no signs of wear from the weather, and the bowl seated at the top of it feels cool to the touch.", completion = "A white hot flame ignites within the bowl as you place the ember within. You can feel the magical effects of the sapta coursing through your body and the fire dances rhythmically before you.\n\nYou place the top of the torch within the basin, and it immediately catches on fire." } })
apply(1527, { "classic", "forever" }, { deDE = { progress = "Ja, {name}? Was habt Ihr da?", completion = "Euer Geist brennt heller als jede Fackel, die ich je gesehen habe, {name}, und darauf solltet Ihr stolz sein.\n\nWenn Ihr diesem Weg weiter folgt, werdet Ihr über die Elemente gebieten und unsere Brüder werden Führung und Weisheit bei Euch suchen. Lasst mich der Erste sein, der Euch gratuliert und Euch Euer neuestes Totem überreicht." }, enUS = { progress = "Yes, {name}? What do you have there?", completion = "Your spirit burns brighter than any torch I've ever seen, {name}, and for that, you should be proud.\n\nIf you continue down this path, the elements will be yours to command, and our brethren will look to you for guidance and wisdom. Let me be the first to congratulate you and present to you your newest totem." } })
apply(1528, { "classic", "forever" }, { deDE = { completion = "Der Wind weht heftig vom Horizont her, die Erde unter Euren Füßen ist fest und Euer Geist ist bereits vom Feuer gewärmt... ich würde sagen, es ist an der Zeit, dass Ihr etwas über die Reinheit des Wassers lernt.\n\nEuer Weg hat Euch so weit gebracht und Euer Geist wird Euch die Kraft geben, noch weiter zu gehen. Doch den ersten Schritt müsst Ihr selbst machen." }, enUS = { completion = "The wind approaches you quickly from the horizon; the earth is steady beneath your feet; and your spirit is already warmed by fire--I would say it is time for you to learn about the purity of water.\n\nYour path has led you this far, and your spirit will give you the strength to carry on even further. But the first step is yours to take." } })
apply(1529, { "classic", "forever" }, { deDE = { completion = "Der Wind weht heftig vom Horizont her, die Erde unter Euren Füßen ist fest und Euer Geist ist bereits vom Feuer gewärmt... ich würde sagen, es ist an der Zeit, dass Ihr etwas über die Reinheit des Wassers lernt.\n\nEuer Weg hat Euch so weit gebracht und Euer Geist wird Euch die Kraft geben, noch weiter zu gehen. Doch den ersten Schritt müsst Ihr selbst machen." }, enUS = { completion = "The wind approaches you quickly from the horizon; the earth is steady beneath your feet; and your spirit is already warmed by fire--I would say it is time for you to learn about the purity of water.\n\nYour path has led you this far, and your spirit will give you the strength to carry on even further. But the first step is yours to take." } })
apply(1530, { "classic", "forever" }, { deDE = { completion = "Ja?\n\nMmm, ich habe das Gefühl, als wüsste ich, was Ihr mich fragen wollt: was veranlasst jemanden, hier im tiefsten Brachland zu leben, ständig von Stachelebern bedroht und ohne Schutz? Wir alle haben unsere Gründe, mit denen wir unser Tun rechtfertigen. Die wahre Frage ist jedoch, was führt einen bescheidenen {race} in die entlegensten Winkel des Brachlandes, um mit einer Frau zu sprechen, die sich eindeutig nicht um ihr Wohlergehen schert?\n\nIch wette, die Antwort darauf kennen wir beide." }, enUS = { completion = "Yes?\n\nMmm, I have a feeling I know what you're going to ask me: what would possess someone to live out here in the deepest part of the Barrens, the threat of quilboar all around, and no protection? Well, we all have our reasons to justify why we act the way we do. The real question is, what brings a lowly {race} to the deepest reaches of the Barrens to speak to a woman who obviously has no concern for her own well-being?\n\nI'm willing to bet we both know the answer to that." } })
apply(1531, { "classic", "forever" }, { deDE = { completion = "Fürs Erste werde ich Euch geben, was Ihr benötigt, um Eure Sprüche zu fokussieren und die Geister der Luft anzurufen. Nehmt dieses Totem, und wenn Ihr bereit seid, übt noch etwas mehr mit mir." }, enUS = { completion = "For the time being, I shall give you what you need to focus your spells and to call upon the spirits of air. Take this totem, and when you are ready, train with me some more." } })
apply(1534, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Wasser schon, {name}? Es heißt, die Ruinen werden von riesigen Kreaturen der Natur beschützt, die keine Besucher dulden, doch das könnten Mythen sein, um die Feinde der Nachtelfen einzuschüchtern.\n\nSeid dennoch vorsichtig.", completion = "Großartig, {name}. Nachdem Ihr alle drei Proben gesammelt habt, kann ich für Euch eine Phiole des reinsten Wassers herstellen, das ein lebendiges Geschöpf finden kann. Es wird bei den nächsten Schritten Eures Initiationsritus Verwendung finden.\n\nEs freut mich, Euch in unserer Mitte begrüßen zu dürfen, {name}. Ihr gereicht allen Schamanen zum Stolz. Ich kann es kaum erwarten, von Euren zukünftigen Taten zu hören." }, enUS = { progress = "Do you have the water yet, {name}? Tales say the ruins were protected by large creatures of nature that do not care for visitors, but those could be myths to scare off the enemies of the night elves.\n\nRegardless, be careful.", completion = "Wonderful, {name}. With all three samples gathered, I can create for you a vial of the purest water any living creature will find. It will be used in the next steps of your rite of passage.\n\nI am pleased to count you among our kind, {name}. You do all {class} proud, and I look forward to hearing about your exploits in the future." } })
apply(1535, { "classic", "forever" }, { deDE = { progress = "Ich bin fast bereit, Euch die anderen Aufgaben zu geben. Habt Ihr den Schlauch schon gefüllt?\n\nIch weiß, welche Beschützerinstinkte die Stacheleber entwickeln können. Für sie bedeutet selbst so eine kleine Wasserquelle großen Reichtum. Bei der geringsten Menge Regen im Brachland feiern sie ein großes Fest. Wasser ist ihrer Art heilig, weil es so selten ist. Habt Ihr verstanden?", completion = "Ich dachte mir, dass es zu Blutvergießen kommt, wenn Ihr versucht, Wasser aus dem Teich zu schöpfen. Leider begreifen die Stacheleber nicht, dass alle Lebewesen miteinander verbunden sind; dass ihre Gier nur Leid und Schmerz über ihr Volk bringt. Wie viel könnten sie erreichen, wenn sie ihre Differenzen beilegen und ihre Klans vereinigen würden.\n\nNochmals, ein Jammer, aber vermutlich ein Segen für alle anderen Völker des Brachlandes." }, enUS = { progress = "I am just about prepared to send you on your other tasks. Have you filled the skin yet?\n\nI know how protective the quilboar can be. Even such a small water source is a vast hoard of wealth to them. They have great feasts when even the slightest rain comes to the Barrens. Water is sacred to their kind because it is so scarce. Do you understand?", completion = "I thought some bloodshed might ensue if you tried to take water from the pool. It is a pity the quilboar do not realize that all living things are tied together; that their greed only perpetuates the pain and suffering of their people. How much could they accomplish if they were to put their differences aside and their clans came together.\n\nAgain, a pity, but more than likely a boon for the other races of the Barrens." } })
apply(1536, { "classic", "forever" }, { deDE = { progress = "Der Brunnen, der mitten in der Stadt rein bleibt, erinnert mich an Geschichten, die mir in meiner Kindheit erzählt wurden, {name}. Selbst in Zeiten von großem Schmerz und Kummer kann man ein Fünkchen Hoffnung finden, ein kleines Symbol, um das man sich schart. Das Orc-Volk sieht Thrall auf diese Weise. Er überlebte allen Widrigkeiten zum Trotz, erhob sich und führte unser Volk durch seine Kraft und sein Vorbild.\n\nIch bin nicht sicher, ob je ein Orc so viel gelitten hat wie er, aber gleichzeitig bin ich nicht sicher, ob je ein Orc stärker sein wird als er.", completion = "Das ist gut, {name}. Ihr geht die vorliegende Aufgabe entschlossen an und seid fähig, das zu suchen, was benötigt wird.\n\nIch benötige nur noch eine Probe, um das Reagenz herzustellen, das für Euer Sapta erforderlich ist. Islen wird ebenfalls zufrieden sein." }, enUS = { progress = "The well remaining pure within the town reminds me of stories told to me when I was younger, {name}. Even in times of great pain and sorrow one can find a sliver of hope, a small symbol to rally around. The orc people see Thrall this way. He survived against great odds and rose up to lead our people through his strength and example.\n\nI'm not sure any orc has suffered as much as he has, but at the same time, I'm not sure any orc is as strong as he is either.", completion = "This is good, {name}. You're dedicated to the task at hand and have the ability to seek out that which is needed.\n\nOne more sample is all I need to create the reagent needed for your sapta. Islen will be pleased as well." } })
apply(1560, { "classic", "forever" }, { deDE = { progress = "Wo ist Tooga?", completion = "Er konnte also den Rückweg nicht allein finden? Typisch.\n\nAlso ich finde, Ihr verdient etwas für Eure Mühe..." }, enUS = { progress = "Where is Tooga?", completion = "So he couldn't find his way back on his own? Figures.\n\nWell, I guess you deserve something for your troubles...." } })
apply(1578, { "classic", "forever" }, { deDE = { progress = "Ich habe keine Zeit zu plaudern. Haben wir etwas miteinander zu tun?", completion = "Ah, Entschuldigung! Ich wusste nicht, dass Ihr hier seid, um die Truppen auszurüsten. Die Sachen, die Ihr hergestellt habt, werden eine große Hilfe sein!\n\nHier sind Pläne für einige Rüstungen. Ich hoffe, Ihr findet sie nützlich." }, enUS = { progress = "I have no time to chat.  Do you have business with me?", completion = "Ah, apologies!  I didn't realize you were here to help resupply our troops.  The stuff you made will be a big help!\n\nHere are plans for some armor.  I hope you find them useful." } })
apply(1579, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meine Klemm-Muffen gefunden, {name}? Ohne meine Klemm-Muffen kann ich meine Stintelpleuel nicht nachziehen!", completion = "Ich kann nicht glauben, dass Ihr sie gefunden habt! Ihr seid der {race} mit dem meisten Glück in Kalimdor!" }, enUS = { progress = "Did you find my gaffer jacks, {name}?  Without my gaffer jacks I can't tune my stintle pegs!", completion = "I can't believe you found them!  You must be the luckiest {race} in Kalimdor!" } })
apply(1580, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meine Elektropeller gefunden? Ich brauche sie, wenn ich meine Forschungen über Entenattrappen fortsetzen soll...", completion = "Ich kann es nicht glauben! Ihr habt sie gefunden! Ihr seid der beste Angler, den ich je gesehen habe!\n\nDanke, {name}. Und hier, nehmt dies. Ihr seid so gut und braucht sie wahrscheinlich nicht, aber sie helfen Euch beim Angeln." }, enUS = { progress = "Did you find any electropellers?  I'll need them if I'm to continue my research on duck decoys...", completion = "I can't believe it!  You found them!  You are the best fisherman I've ever seen!\n\nThank you, {name}.  And here, take these.  Although you're so good and you probably don't need them, they will help you with your fishing." } })
apply(1581, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Habt Ihr die Elixiere zum Tauschen?", completion = "Die sind ordentlich gemischt. Ihr nehmt Euer Handwerk ernst, {name}, und das ist wichtig für einen Alchimisten.\n\nHier sind Eure frisch gesammelten Kräuter. Benutzt sie mit Umsicht." }, enUS = { progress = "Hello, {name}.  Do you have the elixirs to trade?", completion = "These are nicely mixed.  You take great care in your trade, {name}, and that is important for an alchemist.\n\nHere are your herbs, freshly gathered.  May you use them well." } })
apply(1582, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {name}.", completion = "Ja, das sind gute Stücke. Ihr habt eine geschickte Hand und ein Auge für Details. Eure Zukunft als Lederer scheint viel versprechend.\n\nHier, {name}. Lasst mich Euch das Muster für eine Mondscheinweste zeigen." }, enUS = { progress = "Greetings, {name}.", completion = "Yes, these are good pieces. You have a skilled hand and an eye for detail. Your future as a leatherworker is promising.\n\nHere, {name}. Let me show you the pattern to make the Moonglow Vest." } })
apply(1598, { "classic", "forever" }, { deDE = { progress = "Es wäre zu auffällig für mich gewesen, das Buch selbst zu stehlen. Zum Glück hat mir einer ihrer eigenen Trottel die Drecksarbeit abgenommen.", completion = "Exzellent... Ich wäre nie an diesen Text rangekommen. Er wurde in einem gesicherten Flügel der Bibliothek verwahrt und es hätte verdächtig ausgesehen, wenn ich dort herumgeschlichen wäre.\n\nIhr habt Eure Sache gut gemacht, als Ihr das geholt habt. Ich bin überzeugt, Ihr werdet mit einem eigenen Wichtel fertig, daher sehe ich keinen Grund, Euch nicht zu zeigen, wie man einen beschwört." }, enUS = { progress = "It was too conspicuous for me to steal the book myself. What luck one of their own patsies did the dirty work for me.", completion = "Excellent... I was never able to gain access to this text, it was held in a protected wing of the library that would have looked suspicious for me to be loitering around.\n\nWell, you did a good job in getting this, and I'm convinced that you can probably handle your own imp, so there's no reason for me not to show you how to summon one." } })
apply(1599, { "classic", "forever" }, { deDE = { progress = "Diese Federglücksbringer der Novizen besitzen eine Art von magischer Kraft. Es wird interessant sein, sie zu erforschen. Hätte ich von den Trollen gar nicht erwartet.", completion = "Sehr gut, sehr gut! Ihr habt Eure Sache gut gemacht, {name}. Vielleicht ist das Interesse, das man Euch entgegenbringt, ja doch gerechtfertigt.\n\nAber das müssen andere entscheiden... vorausgesetzt, Euer Wichtel überwältigt Euch nicht und bereitet damit Eurer Karriere ein vorzeitiges Ende. Vorerst bin ich schon damit zufrieden, dass Ihr die ersten Monate als {class} vermutlich überleben werdet.\n\nEin Wort zu dem Wichtel, {name}. Lasst Euch, wie jeder {race} weiß, nicht von der Größe täuschen, seine Magie kann sehr gefährlich sein." }, enUS = { progress = "Those feather charms the novices carry have some sort of magical power to them. It will be interesting to research them. I wouldn't have expected it from the trolls.", completion = "Very good, very good! You've done well, {name}. Perhaps the interest that is being shown in you is deserved, after all.\n\nThat'll be for the others to decide--assuming your imp doesn't overpower you and nip your career in the bud. For now, I'm satisfied that you'll probably survive your first few months as a {class}.\n\nA word about the imp, {name}. As a {race} knows, don't let its size fool you, its magic can be very dangerous." } })
apply(1618, { "classic", "forever" }, { deDE = { progress = "Ich hoffe, Ihr bringt gute Nachrichten aus Ironforge. Denn ich bin mit meiner Weisheit am Ende!", completion = "Danke, {name}. Das wird mir unwahrscheinlich helfen. Da die Orcs der Blackrock von der Burg Steinwacht angreifen und die Rotkammgnolle in den Vorgebirgen im Norden lauern, muss ich ständig Rüstungen ausbessern und neue Waffen für unsere Truppen anfertigen.\n\nDie Vorräte, die Ihr gebracht habt, bescheren mir einen Moment Ruhe. Daher habe ich genug Zeit, Euch etwas beizubringen..." }, enUS = { progress = "I hope you're here with good news from Ironforge.  Because I'm at my wit's end!", completion = "Thank you, {name}.  This will help me out tremendously.  With the Blackrock orcs attacking from Stonewatch Keep and the Redridge gnolls lurking in the foothills to the north, I'm always fixing armor and making new weapons for our troops.\n\nThe supplies you brought will give me a moment's peace.  I will have enough time to teach you something..." } })
apply(1638, { "classic", "forever" }, { deDE = { completion = "Oh-ho! Trinkt einen Schluck mit mir, Junge. Äußerlich macht Ihr einen zähen Eindruck. Mal sehen, ob Euer Magen ein paar Krüge vom Stärksten aus dem Pfeifenden Schwein verträgt!!!\n\nOder... seid Ihr wegen einer Lektion hier?" }, enUS = { completion = "Oh ho!  Have a drink with me, lad.  You look tough on the outside, but let's see if your gut can handle a few mugs of the Pig and Whistle's strongest!!\n\nOr... were you here for a lesson?" } })
apply(1639, { "classic", "forever" }, { deDE = { completion = "Hallo, mein Junge! Was hat jemand wie Ihr im Pfeifenden Schwein verloren? Vorsicht, sonst brecht Ihr Euch einen Nagel ab..." }, enUS = { completion = "Hello, fancy boy!  What's a prissy thing like you doing in the Pig and Whistle?  Be careful, or you might break a nail..." } })
apply(1640, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr diesen Krug wollt, müsst Ihr ihn mir aus den kalten, toten Händen brechen...", completion = "Ihr seid viel zäher als Ihr ausseht!" }, enUS = { progress = "The only way you'll get this mug is if you pry it from my cold, dead fingers...", completion = "You're a lot tougher than you look!" } })
apply(1642, { "classic", "forever" }, { deDE = { completion = "Abermals hallo, {name}. Was machen Eure Studien des Folianten der Offenbarung?\n\nDann solltet Ihr bereit sein, Euch prüfen zu lassen. Es gibt in der Stadt und unseren Ländern immer etwas zu tun; barmherzige und verständnisvolle Taten; Menschen, die Hilfe brauchen; Kreaturen, die besiegt werden müssen.\n\nWenn Ihr beweist, dass Ihr die Geduld habt, anderen zu helfen, besonders jenen, die nicht so glücklich sind, beweist Ihr, dass Ihr ein Diener des Lichts und bei klarem Verstand seid." }, enUS = { completion = "Hello again, {name}. How goes your studies of the Tome of Divinity?\n\nThen you should be prepared to have yourself tested. There are always tasks to be done throughout the city and our lands; acts of compassion and understanding; people who need help; creatures to slay.\n\nBy proving you have the patience to help others, especially those who are less fortunate, you prove that you are a servant of the Light and of sound mind." } })
apply(1643, { "classic", "forever" }, { deDE = { completion = "Ach, hallo. Was machen Eure Abenteuer? Oh, freut mich zu hören, dass alles gut läuft.\n\nOh, ich? Danke der Nachfrage - alles in allem geht es mir ganz gut.\n\nDurch die wachsende Zahl der Händler sind die Leute nicht mehr so bereit, sich von Leder und Tuch zu trennen, Daher ist es schwerer, Kleidung für die Kinder im Waisenhaus zu machen, aber wir bekommen das schon hin. Mit \"wir\" meine ich meinen Mann und mich. Er ist in Ironforge und sucht dort Hilfe bei den Bürgern." }, enUS = { completion = "Oh, hello, luv. How go your adventures? Oh, I'm so glad to hear you're doing well.\n\nOh, me? Thank you for asking--I'm doing well, all things considered.\n\nThe increase in tradesmen has kind of put a damper on the amount of leather and cloth people are willing to part with these days, so it's been tougher to make clothing for the children at the orphanage, but we'll manage. By \"we\" I mean my husband and I. He's up in Ironforge trying to seek help from the citizens there." } })
apply(1644, { "classic", "forever" }, { deDE = { progress = "Ich hoffe, John hat in Ironforge mehr Glück. Die Ausflüge dorthin sind ihm so zuwider, weil er mich und die Kinder allein lassen muss, aber er weiß, es geht nicht anders. Er ist so herzensgut.\n\nManche Jahre waren besser als andere, aber dieses war bei weitem das Schlimmste. Es ist fast, als würde eine gewaltige Veränderung in der Luft liegen. Wer weiß?", completion = "Danke {name}, vielen, vielen Dank!\n\nDie Kinder werden sich freuen und Ihr habt mir so viel Zeit gespart. Jetzt kann ich mich auf die anderen Bedürfnisse der Kinder konzentrieren und mein John hoffentlich früher heimkehren als wir dachten.\n\nNochmals danke, {name}. Ich wusste, ich kann mich auf die Barmherzigkeit anderer verlassen. Das Licht sei mit Euch." }, enUS = { progress = "I hope my John is having better luck in Ironforge. He so dislikes his trips there because it leaves the kids and me alone, but he knows it must be done. He's so kind-hearted.\n\nSome years have been easier than others, but this one's been rougher by far. It's almost as though something in the air is signaling a huge change. Who knows though?", completion = "Thank you, {name}, thank you so much!\n\nThe children will be so pleased, and you've saved me so much time. I'll now be able to focus on the children's other needs, and hopefully my John will be able to return home sooner than we thought.\n\nThank you again, {name}. I knew I could rely on the charity of others. The Light be with you." } })
apply(1646, { "classic", "forever" }, { deDE = { completion = "Willkommen zurück, {name}. Ich hoffe, Ihr habt die Zeit genutzt und das Buch gelesen.\n\nDann solltet Ihr bereit sein, Euch prüfen zu lassen. Es gibt in der Stadt und unseren Ländern immer etwas zu tun; barmherzige und verständnisvolle Taten; Menschen, die Hilfe brauchen; Kreaturen, die besiegt werden müssen.\n\nWenn Ihr beweist, dass Ihr die Geduld habt, anderen zu helfen, besonders jenen, die nicht so glücklich sind, beweist Ihr, dass Ihr ein Diener des Lichts und bei klarem Verstand seid." }, enUS = { completion = "Welcome back, {name}. You've spent time reading the book, I hope?\n\nThen you should be prepared to have yourself tested. There are always tasks to be done throughout the city and our lands; acts of compassion and understanding; people who need help; creatures to slay.\n\nBy proving you have the patience to help others, especially those who are less fortunate, you prove that you are a servant of the Light and of sound mind." } })
apply(1647, { "classic", "forever" }, { deDE = { completion = "DAS WAISENHAUS VON STOR... oh, tut mir Leid, ich wollte Euch nicht anschreien, Sire,\n\nIch heiße John Turner. Wie ist das werte Befinden?\n\nGut, gut, freut mich zu hören, dass alles gut für Euch läuft. Ich hatte schon einen langen Arbeitstag und vermisse meine Frau sehr, aber das ist der Preis, den man zahlt, wenn es Mäuler zu füttern und Leiber zu bekleiden gilt." }, enUS = { completion = "THE ORPHANAGE OF STOR... oh, sorry, didn't mean to shout at you, sir,\n\nMy name is John Turner. How are you?\n\nGood, good, glad to hear things go well for you. I've had a long day of work already, and I miss my wife terribly, but that's the price you have to pay when there are mouths to feed and backs to clothe." } })
apply(1648, { "classic", "forever" }, { deDE = { progress = "Bei dem Zustrom von Händlern hier und in ganz Azeroth, sind die Gegenstände knapper, aus denen wir Kleidung für die Kinder in unserem Waisenhaus machen. Es ist sehr anständig von Euch, dass Ihr mir helft, Leinen zu sammeln, damit meine Frau neue Kleidung nähen kann, {name}. Danke.\n\nHoffentlich kann ich bald zu meiner Frau heimkehren.", completion = "Das ist so wunderbar von Euch, {name}. Nochmals danke.\n\nEs ist so anständig von Euch, Mann, dass Ihr das für mich tut. Es ist schön zu sehen, dass Ihr dem Licht folgt. Gäbe es doch nur einen Weg, wie ich Euch vergelten könnte, was Ihr getan habt... wie war das? Es war das Mindeste, das Ihr tun konntet? Seht Ihr? Genau das meine ich, {name}, edel bis zuletzt.\n\nMöget Ihr sicher wandeln und das Licht Euch auf Euren Reisen beschützen." }, enUS = { progress = "What with the influx of tradesmen here and throughout Azeroth, there's a smaller supply of items we use to make clothes for the children of our orphanage. Helping me collect linen so my wife can make new clothes for them is very noble of you, {name}. Thank you.\n\nHopefully, I'll be able to return home to my wife soon.", completion = "This is so wonderful of you, {name}. Thank you again.\n\nYou're a noble man for doing this for me. It's no wonder you've chosen to follow the Light. I wish there was some way I could repay you for all you've done... what's that? It's the least you could do? See? That's what I'm talking about, {name}, noble to the end.\n\nBe safe, and may the Light protect you in your travels." } })
apply(1649, { "classic", "forever" }, { deDE = { completion = "Ah, Ihr möchtet eine Prüfung Eurer Ehre von mir. Großartig.\n\nEs gibt viele Aufgaben in der Stadt und dem Umland, die Herausforderungen bieten und wo Männer mit Euren Fertigkeiten gebraucht werden.\n\nIhr solltet diese Prüfung nicht zu leicht nehmen, {name}. Dies könnte, wie so vieles auf unserem Weg, unser Leben kosten. Die Kirche möchte ihre Schäflein stets mehren, weiß aber um die Opfer, die gebracht werden müssen, um den Wert der Paladine, die ihr dienen, zu beweisen.\n\nSeid Ihr bereit?" }, enUS = { completion = "Ah, you wish to petition me for a test of valor. Splendid.\n\nThere are many tasks throughout the city and surrounding lands that hold much challenge, and they could use a man with your skills.\n\nThis test should not be taken lightly, {name}. This, like many things along our path, could take our lives. The Church always wishes to bolster its ranks, but it understands the sacrifices needed to ensure the paladins serving it are worthy.\n\nAre you prepared?" } })
